css/base.css:
/* base.css - modulo del sistema grafico condiviso. */
:root{--bg:#07110f;--surface:#101b18;--surface2:#162521;--line:#284039;--text:#f4f7f5;--muted:#9db0a9;--accent:#27d17f;--gold:#f2c14e;--danger:#ff6b6b;--max:var(--ds-content-max);--page-gutter:24px;--container-width:min(var(--max),calc(100% - 2 * var(--page-gutter)));color-scheme:dark;font-family:Inter,Segoe UI,Arial,sans-serif}

*{box-sizing:border-box}

html{scroll-behavior:smooth}

body{margin:0;background:radial-gradient(circle at 80% 0,#16392c 0,transparent 28rem),var(--bg);color:var(--text);line-height:1.55}

a{color:inherit}

h1{max-width:850px;margin:0;font-size:clamp(38px,6vw,76px);line-height:1.02;letter-spacing:-.045em}

h2{margin:0 0 18px;font-size:clamp(25px,3vw,38px);letter-spacing:-.025em}

h3{margin:0 0 9px}

body{background:radial-gradient(circle at 82% -5%,rgba(35,91,180,.72) 0,transparent 31rem),radial-gradient(circle at 5% 55%,rgba(15,60,132,.38) 0,transparent 36rem),var(--bg)}

html{scroll-padding-top:100px}

body{background:radial-gradient(circle at 85% -8%,rgba(33,88,181,.62),transparent 34rem),radial-gradient(circle at -10% 52%,rgba(20,67,147,.32),transparent 34rem),linear-gradient(180deg,#03102d 0,var(--bg) 60%,#020819 100%);font-feature-settings:"tnum" 1}

body::before{content:"";position:fixed;z-index:-1;inset:0;pointer-events:none;background-image:linear-gradient(rgba(255,255,255,.018) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.018) 1px,transparent 1px);background-size:48px 48px;mask-image:linear-gradient(to bottom,black,transparent 70%)}

button,a,select,input{outline-offset:3px}

:focus-visible{outline:2px solid var(--gold)}

body{background:radial-gradient(circle at 76% -12%,rgba(57,91,153,.3),transparent 34rem),radial-gradient(circle at 5% 48%,rgba(23,56,112,.18),transparent 40rem),#050812;letter-spacing:-.006em}

body::before{display:none}

h1,h2,h3,strong{letter-spacing:-.025em}

h1{font-weight:720}

h2{font-weight:690}

body{background:radial-gradient(circle at 78% -10%,rgba(48,126,230,.52),transparent 34rem),radial-gradient(circle at -8% 48%,rgba(18,89,190,.32),transparent 40rem),linear-gradient(180deg,#06265b 0,#031a3d 48%,#02132f 100%)}

body{
  background:#e8e8e8;
  color:var(--text);
}

body::before{
  display:block;
  background:
    radial-gradient(circle at 80% -10%,rgba(31,100,184,.1),transparent 32rem),
    radial-gradient(circle at 4% 42%,rgba(183,132,31,.07),transparent 34rem);
  mask-image:none;
}

body{background:#e8e8e8;color:var(--glass-text)}

h1,h2,h3,h4,strong{color:var(--glass-text)}

h1,h2,h3,
.hero-stat strong,
.hero-season strong,
.editorial-empty-mark{
  font-family:var(--font-display);
  font-weight:400!important;
  font-style:normal;
  letter-spacing:.025em!important;
  word-spacing:.06em;
}

:root{
  --background-page:var(--bg);
  --background-surface:var(--surface);
  --background-surface-strong:var(--surface2);
  --color-text:var(--text);
  --color-text-muted:var(--muted);
  --color-border:var(--line);
  --color-accent:var(--accent);
  --space-1:var(--ds-space-1);
  --space-2:var(--ds-space-2);
  --space-3:var(--ds-space-3);
  --space-4:var(--ds-space-4);
  --space-5:var(--ds-space-5);
  --space-6:var(--ds-space-6);
  --space-7:var(--ds-space-7);
  --max-width:var(--max);
  --transition-fast:var(--ds-transition-fast);
  --transition-base:var(--ds-transition-base);
}
/* Due superfici glass condivise; applicazione esplicita, senza cambiare i token legacy. */
:root{
 --glass-light-bg:rgba(220,233,236,.78);
 --glass-dark-bg:rgba(23,46,64,.92);
 --glass-light-border:rgba(255,255,255,.68);
 --glass-dark-border:rgba(255,255,255,.16);
 --glass-blur:blur(22px) saturate(135%);
 --glass-shadow:0 8px 24px rgba(20,43,59,.09),inset 0 1px rgba(255,255,255,.2);
 --glass-light-text:#283a3b;
 --glass-dark-text:#f4f7fa;
}

css/betting.css:
body[data-page="betting"]{--betting-ink:#081626;--betting-blue:#1c6dff;--betting-cyan:#62efff;--betting-gold:#ffd76b}
body[data-page="betting"] main>.hero{display:block;min-height:0;margin-bottom:18px;padding:18px 20px;border:1px solid var(--glass-border);border-radius:18px;background:rgba(255,255,255,.42);box-shadow:none;text-align:left}
body[data-page="betting"] main>.hero::before,body[data-page="betting"] main>.hero::after{display:none;content:none}
body[data-page="betting"] main>.hero h1{max-width:none;margin:0;color:var(--glass-text);font-size:clamp(34px,4vw,48px);line-height:1.04}
body[data-page="betting"] main>.hero .lead{max-width:760px;margin:7px 0 0;color:var(--glass-muted);font-size:15px;line-height:1.45}
body[data-page="betting"] main>.hero .eyebrow{margin-bottom:4px;color:var(--glass-muted);font-size:10px;letter-spacing:.1em}
.site-nav .page-link[data-page-link="betting"]{position:relative;overflow:hidden;border-color:transparent;font-weight:850}
.page-link[data-page-link="betting"]::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 25%,rgba(255,255,255,.52),transparent 70%);transform:translateX(-130%);animation:betting-nav-shine 4.8s ease-in-out infinite}
.betting-archive{display:grid;gap:24px}
.betting-archive-intro{display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,.7fr);gap:30px;align-items:end;padding:0 8px}
.betting-archive-intro h2{margin:4px 0 0;font-size:clamp(30px,4vw,52px);letter-spacing:-.045em}
.betting-archive-intro>p{margin:0;color:var(--muted);line-height:1.65}
.betting-archive-list{width:100%;max-width:var(--max);margin:0;padding:0}
.betting-archive-card{color:#fff;text-decoration:none}
.betting-archive-card-front{gap:0}
.betting-archive-number{width:100%;color:#fff;font-family:"Anton",sans-serif;font-size:88px;font-weight:400;line-height:.85;text-align:center;text-shadow:0 12px 24px rgba(0,0,0,.32)}
.betting-archive-card-back strong{font-size:1.45rem}
.betting-archive-card--champions .betting-archive-card-back{gap:4px;padding:14px}
.betting-archive-card--champions .betting-champions-verification{font-size:.65rem}
.betting-archive-card--champions .team-flip-front{background:radial-gradient(circle at 70% 18%,rgba(80,196,255,.5),transparent 42%),linear-gradient(145deg,#0966e8,#031b4b)!important}
.betting-champions-front{display:grid;place-content:center;justify-items:center}
.betting-champions-front small{margin-top:9px;color:#c8ecff;font-size:10px;font-weight:950;letter-spacing:.32em}
.betting-champions-front-summary{margin-top:13px;color:#d9f2ff;font-size:9px;font-weight:850;letter-spacing:.04em;text-transform:uppercase}
.betting-round-page--champions .betting-round-heading .eyebrow{color:#0756c9}
.betting-champions-stage{border:1px solid rgba(7,86,201,.18);border-radius:28px;background:radial-gradient(circle at 95% 4%,rgba(69,181,255,.25),transparent 22rem),linear-gradient(145deg,rgba(239,248,255,.96),rgba(222,238,255,.84))}
.betting-champions-stage .betting-coverage{border-color:rgba(7,86,201,.16);background:rgba(255,255,255,.54);color:#48627c}
.betting-champions-stage .betting-coverage strong{color:#0a477f}
.betting-slip--champions{border-color:rgba(7,86,201,.24);background:radial-gradient(circle at 91% 7%,rgba(61,170,255,.18),transparent 13rem),linear-gradient(155deg,#fafdff,#e8f3ff)}
.betting-slip--champions::before{background:radial-gradient(circle,rgba(25,111,230,.3),transparent 67%)}
.betting-slip--champions>header p{color:#0756c9}
.betting-champions-metrics{grid-template-columns:1.2fr 1fr 1fr}
.betting-archive-performance{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;width:100%;margin-top:3px}
.betting-archive-performance>span{padding:7px 8px;border:1px solid rgba(255,255,255,.72);border-radius:10px;background:rgba(255,255,255,.82);text-align:center}
.betting-archive-performance small,.betting-archive-performance strong{display:block;color:#000}
.betting-archive-performance small{font-size:9px;font-weight:800;letter-spacing:.09em;line-height:1.1;text-transform:uppercase;opacity:.78}
.betting-archive-performance strong{margin-top:2px;font-size:1rem;line-height:1.1}
.betting-round-back{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 16px}
.betting-round-back a{display:inline-flex;align-items:center;min-height:42px;padding:0 15px;border:1px solid rgba(28,109,255,.18);border-radius:999px;background:rgba(255,255,255,.66);color:#174f87;font-size:12px;font-weight:850;text-decoration:none;box-shadow:0 8px 22px rgba(27,61,104,.08);transition:transform .2s ease,box-shadow .2s ease}
.betting-round-back a:hover{transform:translateY(-2px);box-shadow:0 12px 28px rgba(27,61,104,.14)}
.betting-round-heading{margin:0 0 18px;padding:0 8px}
.betting-round-heading h2{margin:4px 0 0;font-size:clamp(30px,4vw,52px);letter-spacing:-.045em}
.betting-stage{position:relative;isolation:isolate;padding:clamp(24px,4vw,46px);overflow:hidden;background:radial-gradient(circle at 95% 4%,rgba(98,239,255,.18),transparent 22rem),linear-gradient(145deg,rgba(255,255,255,.82),rgba(238,247,255,.72));box-shadow:inset 0 1px #fff}
.betting-stage::before{content:"";position:absolute;z-index:-1;left:-100px;bottom:-130px;width:330px;height:330px;border:1px solid rgba(28,109,255,.09);border-radius:50%;box-shadow:0 0 0 48px rgba(28,109,255,.035),0 0 0 96px rgba(28,109,255,.02)}
.betting-intro{display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,.7fr);gap:30px;align-items:end;margin-bottom:30px}
.betting-intro h3{margin:4px 0 0;font-size:clamp(30px,4vw,52px);letter-spacing:-.045em}
.betting-intro>p{margin:0;color:var(--muted);line-height:1.65}
.betting-result-legend{display:flex;flex-wrap:wrap;gap:7px;align-items:center;margin:-14px 0 22px}
.betting-result-legend>span,.betting-leg-result{display:inline-flex;gap:5px;align-items:center;border:1px solid;border-radius:999px;font-weight:850}
.betting-result-legend>span{padding:6px 10px;font-size:10px;text-transform:uppercase}
.betting-result-legend--won{border-color:rgba(22,135,84,.25)!important;background:rgba(24,174,105,.11);color:#087144}
.betting-result-legend--lost{border-color:rgba(201,50,58,.24)!important;background:rgba(224,66,73,.1);color:#a7212a}
.betting-result-legend--void{border-color:rgba(28,109,255,.26)!important;background:rgba(28,109,255,.11);color:#1257a6}
.betting-result-legend small{color:var(--muted);font-size:10px}
.betting-slip-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;align-items:start}
.betting-slip-grid-qualified{grid-template-columns:repeat(2,minmax(0,1fr));max-width:none}
.betting-slip{position:relative;overflow:hidden;padding:16px 18px;border:1px solid rgba(30,79,135,.15);border-radius:18px;background:linear-gradient(155deg,rgba(255,255,255,.92),rgba(240,247,253,.76));box-shadow:inset 0 1px #fff,0 10px 24px rgba(26,61,102,.08);transition:transform .25s ease,box-shadow .25s ease}
.betting-slip::before{content:"";position:absolute;right:-55px;top:-55px;width:145px;height:145px;border-radius:50%;background:radial-gradient(circle,rgba(98,239,255,.34),transparent 67%);filter:blur(2px)}
.betting-slip--bagliore{margin-top:0}
.betting-slip--supernova{border-color:rgba(190,133,13,.3);background:radial-gradient(circle at 90% 7%,rgba(255,215,107,.2),transparent 13rem),linear-gradient(155deg,#fffdf7,#eef7ff)}
.betting-slip--prisma,.betting-slip--quasar{margin-top:0}
.betting-slip--prisma{grid-column:auto;border-color:rgba(91,96,214,.24);background:radial-gradient(circle at 91% 7%,rgba(159,139,255,.15),transparent 13rem),linear-gradient(155deg,#fdfcff,#eef8ff)}
.betting-slip--quasar{grid-column:auto;border-color:rgba(217,71,143,.22);background:radial-gradient(circle at 91% 7%,rgba(255,112,190,.14),transparent 13rem),linear-gradient(155deg,#fffafd,#eef8ff)}
.betting-slip--costellazione{grid-column:auto;border-color:rgba(92,67,214,.28);background:radial-gradient(circle at 88% 8%,rgba(129,112,255,.15),transparent 16rem),linear-gradient(145deg,#fcfbff,#eef8ff)}
.betting-slip--quadrante{grid-column:auto;border-color:rgba(255,135,75,.28);background:radial-gradient(circle at 90% 8%,rgba(255,165,92,.15),transparent 14rem),linear-gradient(150deg,#fffaf6,#eef8ff)}
.betting-slip--ventaglio{grid-column:auto;border-color:rgba(33,173,147,.25);background:radial-gradient(circle at 92% 8%,rgba(79,224,189,.14),transparent 15rem),linear-gradient(150deg,#f8fffd,#eef7ff)}
.betting-slip:hover{transform:translateY(-2px);box-shadow:inset 0 1px #fff,0 16px 32px rgba(26,61,102,.13)}
.betting-slip>header{position:relative;display:flex;justify-content:space-between;gap:16px;align-items:center}
.betting-slip>header p{margin:0;color:#1b65bb;font-size:10px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}
.betting-quality{max-width:132px;padding:6px 8px;border:1px solid rgba(27,101,187,.15);border-radius:999px;background:rgba(255,255,255,.66);color:#1b65bb;font-size:9px;font-weight:900;line-height:1.2;text-align:center;text-transform:uppercase}
.betting-slip[data-quality="laboratorio"] .betting-quality{border-color:rgba(180,91,40,.18);color:#9a4c20}
.betting-slip[data-quality="qualificata"] .betting-quality{border-color:rgba(26,137,99,.2);color:#137557}
.betting-slip h2{margin:2px 0 0;font-size:25px;letter-spacing:-.04em}
.betting-slip>header small{display:block;max-width:850px;margin-top:4px;color:var(--muted);font-size:10px;line-height:1.35}
.betting-slip-index{color:rgba(22,72,126,.14);font-family:"Anton",sans-serif;font-size:48px;line-height:.8}
.betting-slip-copy{min-height:58px;margin:16px 0;color:var(--muted);font-size:13px;line-height:1.55}
.betting-family-list{display:flex;flex-wrap:wrap;gap:5px;margin:-3px 0 14px}
.betting-family-list span{padding:5px 8px;border:1px solid rgba(28,109,255,.12);border-radius:999px;background:rgba(255,255,255,.62);color:#17528e;font-size:9px;font-weight:850;letter-spacing:.04em;text-transform:uppercase}
.betting-quote{display:grid;grid-template-columns:1fr auto;align-items:end;padding:17px 18px;border:1px solid rgba(255,255,255,.16);border-radius:19px;background:linear-gradient(135deg,#092448,#0e4f84);color:#fff;box-shadow:0 13px 28px rgba(10,46,91,.22)}
.betting-quote span{align-self:start;color:#bfe4ff;font-size:10px;font-weight:850;letter-spacing:.12em;text-transform:uppercase}
.betting-quote strong{grid-row:1/3;grid-column:2;font-size:39px;line-height:.9;letter-spacing:-.04em;text-shadow:0 0 17px rgba(98,239,255,.58)}
.betting-quote small{color:#fff;font-weight:700}
.betting-slip ol{display:grid;grid-template-columns:1fr;margin:10px 0 0;padding:0;list-style:none}
.betting-slip li{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:8px;align-items:center;min-height:48px;padding:7px 0;border-bottom:1px solid rgba(22,72,126,.1)}
.betting-slip li div{display:grid;min-width:0;gap:2px}
.betting-slip li strong{overflow:hidden;font-size:12px;text-overflow:ellipsis;white-space:nowrap}
.betting-slip li div>span{color:#334b64;font-size:11px;line-height:1.35}
.betting-slip li small{color:var(--muted)}
.betting-slip li>b{padding:5px 7px;border-radius:8px;background:rgba(28,109,255,.08);color:#154e8c;font-size:12px}
.betting-mycombo-options li{display:block;min-height:0;padding:0}
.betting-mycombo-pick{display:grid;width:100%;grid-template-columns:minmax(0,1fr) auto;gap:8px;align-items:center;min-height:48px;padding:7px 5px;border:0;border-radius:10px;background:transparent;color:inherit;font:inherit;text-align:left;cursor:pointer;transition:background .18s ease,box-shadow .18s ease,transform .18s ease}
.betting-mycombo-pick:hover{background:rgba(28,109,255,.07);transform:translateX(2px)}
.betting-mycombo-pick:focus-visible{outline:3px solid rgba(28,109,255,.3);outline-offset:1px}
.betting-mycombo-pick[aria-pressed="true"]{background:linear-gradient(90deg,rgba(28,109,255,.16),rgba(98,239,255,.08));box-shadow:inset 3px 0 #1c6dff}
.betting-mycombo-pick-copy{display:grid;min-width:0;gap:2px}
.betting-mycombo-pick-copy>strong{overflow:hidden;font-size:12px;text-overflow:ellipsis;white-space:nowrap}
.betting-mycombo-pick-copy>span{color:#334b64;font-size:11px;line-height:1.35}
.betting-mycombo-pick>b{padding:5px 7px;border-radius:8px;background:rgba(28,109,255,.08);color:#154e8c;font-size:12px}
.betting-mycombo-pick:disabled{cursor:default}
.betting-mycombo-pick:disabled:hover{background:transparent;transform:none}
.betting-personal-pick,.betting-personal-add-slip{display:inline-flex;gap:5px;align-items:center;justify-content:center;border:1px solid rgba(28,109,255,.22);border-radius:999px;background:#fff;color:#1257a6;font:inherit;font-size:10px;font-weight:900;cursor:pointer;transition:background .18s ease,color .18s ease,transform .18s ease}
.betting-personal-pick{min-height:30px;padding:5px 9px}
.betting-personal-add-slip{position:relative;margin-top:10px;padding:8px 12px}
.betting-personal-pick:hover,.betting-personal-add-slip:hover{transform:translateY(-1px)}
.betting-personal-pick:focus-visible,.betting-personal-add-slip:focus-visible,.personal-betslip-root button:focus-visible{outline:3px solid rgba(28,109,255,.32);outline-offset:2px}
.betting-personal-pick.is-selected{border-color:#087144;background:#e5f7ed;color:#087144}
.betting-personal-pick:disabled{opacity:.58;cursor:default}
.betting-slip li.betting-leg--won{margin:2px 0;padding:6px 7px;border:1px solid rgba(22,135,84,.2);border-radius:10px;background:linear-gradient(90deg,rgba(24,174,105,.12),rgba(24,174,105,.035))}
.betting-slip li.betting-leg--lost{margin:2px 0;padding:6px 7px;border:1px solid rgba(201,50,58,.2);border-radius:10px;background:linear-gradient(90deg,rgba(224,66,73,.11),rgba(224,66,73,.03))}
.betting-slip li.betting-leg--void{margin:2px 0;padding:6px 7px;border:1px solid rgba(28,109,255,.24);border-radius:10px;background:linear-gradient(90deg,rgba(28,109,255,.13),rgba(28,109,255,.035))}
.betting-leg-result{justify-self:start;margin-top:4px;padding:3px 7px;font-size:9px;letter-spacing:.03em;text-transform:uppercase}
.betting-leg--won .betting-leg-result{border-color:rgba(22,135,84,.25);background:#e5f7ed;color:#087144}
.betting-leg--lost .betting-leg-result{border-color:rgba(201,50,58,.24);background:#fdebed;color:#a7212a}
.betting-leg--void .betting-leg-result{border-color:rgba(28,109,255,.26);background:#e8f1ff;color:#1257a6}
.betting-leg--unavailable .betting-leg-result{border-color:rgba(81,101,123,.18);background:#eef2f6;color:#52657a}
.betting-leg--won li>b,.betting-leg--won>b{background:rgba(24,174,105,.12);color:#087144}
.betting-leg--lost li>b,.betting-leg--lost>b{background:rgba(224,66,73,.11);color:#a7212a}
.betting-leg--void li>b,.betting-leg--void>b{background:rgba(28,109,255,.13);color:#1257a6}
.betting-slip-metrics{display:grid;grid-template-columns:1.25fr repeat(3,1fr);gap:1px;margin-top:10px;overflow:hidden;border:1px solid rgba(22,72,126,.1);border-radius:12px;background:rgba(22,72,126,.08)}
.betting-slip-metrics>div{display:flex;justify-content:center;flex-direction:column;min-height:55px;padding:7px 11px;background:rgba(255,255,255,.72);text-align:center}
.betting-slip-metrics span{color:var(--muted);font-size:8px;font-weight:850;letter-spacing:.06em;text-transform:uppercase}
.betting-slip-metrics strong{margin-top:2px;color:var(--betting-ink);font-size:15px}
.betting-slip-metrics small{color:var(--muted);font-size:9px}
.betting-slip-metrics .betting-slip-total{align-items:center;flex-direction:row;flex-wrap:wrap;gap:2px 8px;background:linear-gradient(135deg,#092448,#0e4f84);color:#fff}
.betting-slip-metrics .betting-slip-total span,.betting-slip-metrics .betting-slip-total small{color:#bfe4ff}
.betting-slip-metrics .betting-slip-total strong{color:#fff;font-size:22px;line-height:1}
.betting-weakest{margin:7px 0 0;padding-top:7px;border-top:1px solid rgba(22,72,126,.1);color:var(--muted);font-size:9px;line-height:1.35}
.betting-weakest strong{color:#334b64}
.betting-weakest small{display:block;margin-top:3px;color:#1b65bb}
.betting-nd-compact{display:flex;gap:10px;align-items:baseline;margin:-4px 0 24px;padding:10px 13px;border:1px solid rgba(22,72,126,.11);border-radius:13px;background:rgba(255,255,255,.58)}
.betting-nd-compact strong{color:#174f87;font-size:12px}
.betting-nd-compact span{color:var(--muted);font-size:11px}
