.betting-champions-preferred{display:grid;gap:14px;padding:20px;border:1px solid rgba(7,86,201,.18);border-radius:18px;background:rgba(255,255,255,.82);box-shadow:0 12px 30px rgba(13,57,105,.07)}
.betting-champions-preferred>header{display:flex;justify-content:space-between;align-items:end;gap:16px;padding-bottom:12px;border-bottom:1px solid rgba(22,72,126,.12)}
.betting-champions-preferred>header .eyebrow{margin:0;color:#2878D4}
.betting-champions-preferred>header h3{margin:3px 0 2px;color:#0a477f;font-size:25px}
.betting-champions-preferred>header p{margin:0;color:#52677d;font-size:11px}
.betting-champions-preferred>header>span{flex:0 0 auto;padding:5px 9px;border-radius:999px;background:#eaf3ff;color:#175ea9;font-size:9px;font-weight:900;text-transform:uppercase}
.betting-champions-preferred>ol{display:grid;gap:6px;margin:0;padding:0;list-style:none}
.betting-preferred-list-row{display:grid;grid-template-columns:minmax(130px,.8fr) minmax(220px,1.45fr) repeat(3,minmax(64px,.45fr)) minmax(118px,auto);gap:10px;align-items:center;min-height:78px;padding:10px 11px;border:1px solid rgba(22,72,126,.11);border-left:3px solid #D4A43B;border-radius:10px;background:#fff}
.betting-preferred-list-fixture{display:grid;gap:3px;min-width:0}.betting-preferred-list-fixture small{color:#65788b;font-size:8px;font-weight:850;text-transform:uppercase}.betting-preferred-list-fixture strong{overflow-wrap:anywhere;color:#163f69;font-size:11px;line-height:1.35}
.betting-preferred-list-copy .betting-editorial-badges{margin:1px 0 2px}.betting-preferred-list-copy>strong{overflow-wrap:anywhere}.betting-preferred-list-contract{color:#52677d;font-size:8px!important;line-height:1.35}
.betting-preferred-list-metric{display:grid;gap:2px;text-align:center}.betting-preferred-list-metric small{color:#6b7c8e;font-size:8px;font-weight:800;text-transform:uppercase}.betting-preferred-list-metric b{color:#203b55;font-size:12px;font-variant-numeric:tabular-nums}.betting-preferred-list-metric.is-positive b{color:#087144}.betting-preferred-list-metric.is-negative b{color:#a7212a}
.betting-preferred-list-pick{display:inline-flex;align-items:center;justify-content:center;gap:5px;min-height:36px;padding:7px 10px;border:1px solid #2878D4;border-radius:9px;background:#edf5ff;color:#175ea9;font:inherit;font-size:9px;font-weight:900;cursor:pointer}.betting-preferred-list-pick>span:first-child{font-size:14px;line-height:1}.betting-preferred-list-pick:hover{background:#e1efff}.betting-preferred-list-pick:focus-visible{outline:3px solid rgba(40,120,212,.25);outline-offset:2px}.betting-preferred-list-pick[aria-pressed="true"]{border-color:#126443;background:#126443;color:#fff}
.betting-personal-column{min-width:0;align-self:stretch}
.personal-betslip-panel>footer{grid-template-columns:1fr}
.personal-betslip-analysis{display:grid;gap:7px;margin-top:10px;padding:10px;border:1px solid rgba(22,72,126,.15);border-radius:10px;background:#f8fbff}.personal-betslip-analysis>strong{color:#0a477f;font-size:11px}.personal-betslip-analysis ul{display:grid;gap:5px;margin:0;padding:0;list-style:none}.personal-betslip-analysis li{display:grid;gap:1px;padding-left:8px;border-left:2px solid rgba(39,116,200,.35)}.personal-betslip-analysis li b{font-size:9px}.personal-betslip-analysis li span,.personal-betslip-analysis>small{color:#52677d;font-size:8px;line-height:1.4}.personal-betslip-analysis li[data-issue-type="MARKET_CONTRADICTION"],.personal-betslip-analysis li[data-issue-type="SCENARIO_INCOMPATIBILITY"]{border-left-color:#cc7a13}

@media(min-width:1180px){
  .betting-personal-column{display:block}
  .personal-betslip-root{position:sticky;z-index:20;top:88px}
  .personal-betslip-trigger{display:none}
  .personal-betslip-panel{display:flex;position:static;width:100%;height:min(720px,calc(100vh - 108px));max-height:calc(100vh - 108px);border:1px solid rgba(22,72,126,.17);border-radius:14px;box-shadow:none;transform:none;opacity:1}
  .personal-betslip-panel.is-empty{height:auto;max-height:none}
  .personal-betslip-panel[hidden]{display:flex}
  .personal-betslip-close{display:none}
  .personal-betslip-panel>header{padding:16px 16px 12px;background:#0a315b}
  .personal-betslip-panel>header h2{font-size:22px}
  .personal-betslip-panel>footer{grid-template-columns:1fr}
}

@media(max-width:1179px){
  .betting-workspace{display:block}
  .betting-personal-column{display:contents}
}

@media(max-width:760px){
  .betting-workspace-content{gap:18px}
  .betting-matchday-heading{align-items:flex-start}
  .betting-matchday-controls{justify-items:start}
  .betting-preferred-list-row{grid-template-columns:minmax(120px,.72fr) minmax(190px,1.28fr) repeat(3,minmax(58px,.4fr));gap:8px}
  .betting-preferred-list-pick{grid-column:1/-1;justify-self:stretch}
}

@media(max-width:680px){
  body[data-page="betting"] main>.hero{margin-bottom:14px;padding:14px 16px;border-radius:14px}
  body[data-page="betting"] main>.hero h1{font-size:32px}
  body[data-page="betting"] main>.hero .lead{font-size:14px}
  .betting-round-heading{margin-bottom:12px;padding-inline:2px}
  .betting-round-heading h2{font-size:28px}
  .betting-matchday-heading{display:grid;gap:9px}
  .betting-matchday-actions{justify-content:flex-start}
  .betting-match-panel>summary{grid-template-columns:minmax(0,1fr) auto;gap:7px;min-height:58px;padding:9px 10px}
  .betting-match-count{grid-column:1/2;text-align:left}
  .betting-match-toggle{grid-column:2;grid-row:1/3}
  .betting-match-body{padding:10px}
  .betting-champions-md02-markets{padding:13px 10px 18px;border-radius:14px}
  .betting-scenario-summary{grid-template-columns:auto 1fr;padding:9px}.betting-scenario-summary>p{grid-column:1/-1}.betting-scenario-legend{gap:6px 10px}.betting-scenario-main strong{font-size:22px}
  .betting-market-columns{display:none}
  .betting-market-row{position:relative;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;padding:10px 36px 10px 8px}
  .betting-market-copy{grid-column:1/-1}
  .betting-market-metric{text-align:left}
  .betting-market-quote-unavailable{grid-column:2/4}
  .betting-selection-check{position:absolute;top:9px;right:7px}
  .betting-champions-preferred{padding:14px 10px;border-radius:14px}
  .betting-champions-preferred>header{align-items:flex-start;flex-direction:column;gap:8px;padding-inline:2px}
  .betting-champions-preferred>header h3{font-size:23px}
  .betting-preferred-list-row{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;padding:11px 9px}
  .betting-preferred-list-fixture,.betting-preferred-list-copy{grid-column:1/-1}
  .betting-preferred-list-metric{text-align:left}
  .betting-preferred-list-pick{grid-column:1/-1;width:100%}
}

/* Archived selected forecasts retain the same settlement palette as slips. */
.betting-market-row.betting-leg--won .betting-market-metric:nth-of-type(2) b{color:#087144;background:#e5f7ed}
.betting-market-row.betting-leg--lost .betting-market-metric:nth-of-type(2) b{color:#a7212a;background:#fdebed}
.betting-market-row[aria-disabled="true"]{cursor:default}
.betting-market-row.betting-leg--won,.betting-market-row.betting-leg--won:hover{border-color:rgba(22,135,84,.2);background:linear-gradient(90deg,rgba(24,174,105,.12),rgba(24,174,105,.035))}
.betting-market-row.betting-leg--lost,.betting-market-row.betting-leg--lost:hover{border-color:rgba(201,50,58,.2);background:linear-gradient(90deg,rgba(224,66,73,.11),rgba(224,66,73,.03))}

/* Keep the Champions flip within the archive's existing card dimensions. */
.betting-archive-card--champions .team-flip-inner{display:block;height:100%;min-height:0;padding:0;border:0;background:none;box-shadow:none;overflow:visible;transform:none!important}
.betting-archive-card--champions:hover .team-flip-inner,.betting-archive-card--champions:focus-visible .team-flip-inner{transform:rotateY(180deg)!important}
.betting-archive-card--champions .team-flip-face{position:absolute;inset:0;min-height:0;overflow:hidden;border:1px solid #00000015;border-radius:26px;backface-visibility:hidden;-webkit-backface-visibility:hidden}
.betting-archive-card--champions .team-flip-back{transform:rotateY(180deg);background:radial-gradient(circle at 100% 0,color-mix(in srgb,var(--team-primary) 11%,transparent),transparent 52%),radial-gradient(circle at 0 100%,color-mix(in srgb,var(--team-secondary) 9%,transparent),transparent 48%),linear-gradient(115deg,rgba(255,255,255,.46),transparent 36%),#b5faff31}
@media(max-width:1000px){.betting-archive-card--champions .betting-archive-card-back>strong{font-size:1.18rem}.betting-archive-card--champions .betting-archive-card-back>span{font-size:.7rem}.betting-archive-card--champions .betting-archive-card-back .betting-champions-verification{font-size:.6rem}.betting-archive-card--champions .team-flip-back b{margin-top:4px;padding-top:7px}}

@media(hover:none){.betting-archive-card--champions{height:300px;perspective:1100px}}
@media(max-width:760px){.betting-archive-card--champions{height:260px;perspective:1100px}}

/* Champions MD2: audit archive only; the operational forecasts are unchanged. */
.betting-champions-md02-summary .betting-result-legend{margin:12px 0 0}
.betting-champions-md02-summary .betting-result-legend--pending{border-color:#aab6c2;background:#e4e9ee;color:#354657}
.betting-champions-md02-summary .betting-result-legend--void{border-color:#bdc6ce!important;background:#f0f2f4;color:#465563}
.betting-champions-md02-markets .betting-market-row[data-settlement="won"],.betting-champions-preferred [data-settlement="won"]{border-color:rgba(22,135,84,.3);background:linear-gradient(90deg,#dff3e8,#f0faf4);box-shadow:inset 3px 0 #168754}
.betting-champions-md02-markets .betting-market-row[data-settlement="lost"],.betting-champions-preferred [data-settlement="lost"]{border-color:rgba(201,50,58,.3);background:linear-gradient(90deg,#f8dfe2,#fdf1f2);box-shadow:inset 3px 0 #c9323a}
.betting-champions-md02-markets .betting-market-row[data-settlement="pending"],.betting-champions-preferred [data-settlement="pending"]{border-color:#b6c1cc;background:linear-gradient(90deg,#e1e7ed,#f0f3f6);box-shadow:inset 3px 0 #7b8b9b}
.betting-champions-md02-markets .betting-market-row[data-settlement="void"],.betting-champions-preferred [data-settlement="void"]{border-color:#c4cdd5;background:#f1f3f5;box-shadow:inset 3px 0 #a1adb8}
.betting-audit-economics{padding:12px;border:1px solid rgba(22,72,126,.13);border-radius:10px;background:rgba(238,246,252,.8)}
.betting-audit-economics>header{display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:6px 14px}
.betting-audit-economics>header>strong{font-size:14px}
.betting-audit-economics>header>span,.betting-audit-economics>p{color:#52677d;font-size:10px;line-height:1.5}
.betting-audit-economics dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:10px 0 0}
.betting-audit-economics dl>div{min-width:0;padding:8px;border:1px solid rgba(22,72,126,.09);border-radius:8px;background:rgba(255,255,255,.72)}
.betting-audit-economics dt{color:#52677d;font-size:10px}
.betting-audit-economics dd{margin:3px 0 0;color:#142c40;font-size:15px;font-weight:800;font-variant-numeric:tabular-nums}
.betting-audit-economics>p{margin:8px 0 0}
@media(max-width:580px){.betting-audit-economics dl{grid-template-columns:repeat(2,minmax(0,1fr))}}

.betting-round-page--audit .betting-workspace-content{grid-template-columns:minmax(0,1fr)}
.betting-round-page--audit .betting-workspace-content>section{min-width:0}
.betting-round-page--audit .betting-champions-preferred{grid-template-columns:minmax(0,1fr)}
@media(min-width:681px){.betting-round-page--audit .betting-preferred-list-row{grid-template-columns:minmax(100px,.8fr) minmax(160px,1.45fr) repeat(3,minmax(54px,.45fr)) minmax(80px,auto);gap:8px}}

/* Touch: show the CL2 archive return directly, within the existing card size. */
@media(hover:none){
  .betting-archive-card--champions[data-champions-matchday="2"]{height:300px;perspective:none}
  .betting-archive-card--champions[data-champions-matchday="2"] .team-flip-inner{transform:none!important}
  .betting-archive-card--champions[data-champions-matchday="2"] .team-flip-front{visibility:hidden}
  .betting-archive-card--champions[data-champions-matchday="2"] .team-flip-back{transform:none;backface-visibility:visible;-webkit-backface-visibility:visible}
}
@media(max-width:760px) and (hover:none){.betting-archive-card--champions[data-champions-matchday="2"]{height:260px}}

.betting-archive-card--champions[data-champions-matchday="2"] .betting-archive-card-back{gap:3px;padding:12px}
.betting-archive-card--champions[data-champions-matchday="2"] .betting-archive-card-back>strong{margin-bottom:2px}
.betting-archive-card--champions[data-champions-matchday="2"] .team-flip-back>b{margin-top:5px;padding-top:7px}

css/buttons.css:
/* buttons.css - sistema condiviso per CTA, filtri e azioni compatte. */
:root{
  --button-blue:#1e5f9d;
  --button-blue-strong:#164c82;
  --button-gold:#9b6c17;
  --button-surface:rgba(255,255,255,.68);
  --button-border:rgba(36,90,120,.2);
  --button-shadow:0 7px 18px rgba(40,58,59,.09),inset 0 1px 0 rgba(255,255,255,.88);
  --button-shadow-hover:0 11px 24px rgba(31,78,116,.15),inset 0 1px 0 rgba(255,255,255,.94);
}

.button,
.menu-button,
.global-stat-button,
.home-matchday-button,
.standings-switch button,
.standings-scope-switch button,
.fantasy-main-toggle,
.fantasy-reset,
.fantasy-row-actions button,
.fantasy-strategy-tabs button,
.fantasy-recommendation-actions button,
.fantasy-excluded button,
.referee-card-action,
.referee-season-nav a,
.team-calendar-actions a{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:.42em;
  min-height:38px;
  padding:8px 14px;
  border:1px solid var(--button-border);
  border-radius:999px;
  background:linear-gradient(145deg,rgba(255,255,255,.82),var(--button-surface));
  box-shadow:var(--button-shadow);
  color:var(--button-blue);
  font-family:var(--font-body);
  font-size:.75rem;
  font-weight:800;
  line-height:1;
  letter-spacing:.005em;
  text-align:center;
  text-decoration:none;
  cursor:pointer;
  user-select:none;
  -webkit-tap-highlight-color:transparent;
  transition:color .2s ease,border-color .2s ease,background .2s ease,box-shadow .2s ease,transform .2s cubic-bezier(.22,.8,.22,1);
}

.button:hover,
.menu-button:hover,
.global-stat-button:hover,
.home-matchday-button:hover:not(:disabled),
.standings-switch button:hover,
.standings-scope-switch button:hover,
.fantasy-main-toggle:hover,
.fantasy-reset:hover,
.fantasy-row-actions button:hover,
.fantasy-strategy-tabs button:hover,
.fantasy-recommendation-actions button:hover,
.fantasy-excluded button:hover,
.referee-card-action:hover,
.referee-season-nav a:hover,
.team-calendar-actions a:hover{
  border-color:rgba(16,68,112,.62);
  background:linear-gradient(135deg,#276da8,var(--button-blue-strong));
  box-shadow:0 11px 24px rgba(22,76,130,.22),inset 0 1px 0 rgba(255,255,255,.22);
  color:#fff;
  text-decoration:none;
  transform:translateY(-1px);
}

.button:active,
.menu-button:active,
.global-stat-button:active,
.home-matchday-button:active:not(:disabled),
.standings-switch button:active,
.standings-scope-switch button:active,
.fantasy-main-toggle:active,
.fantasy-reset:active,
.fantasy-row-actions button:active,
.fantasy-strategy-tabs button:active,
.fantasy-recommendation-actions button:active,
.fantasy-excluded button:active,
.referee-card-action:active,
.referee-season-nav a:active,
.team-calendar-actions a:active{
  box-shadow:0 3px 9px rgba(40,58,59,.09),inset 0 1px 2px rgba(40,58,59,.08);
  transform:translateY(0) scale(.98);
}

.button:focus-visible,
.menu-button:focus-visible,
.global-stat-button:focus-visible,
.home-matchday-button:focus-visible,
.standings-switch button:focus-visible,
.standings-scope-switch button:focus-visible,
.fantasy-main-toggle:focus-visible,
.fantasy-reset:focus-visible,
.fantasy-row-actions button:focus-visible,
.fantasy-strategy-tabs button:focus-visible,
.fantasy-recommendation-actions button:focus-visible,
.fantasy-excluded button:focus-visible,
.referee-card-action:focus-visible,
.referee-season-nav a:focus-visible,
.team-calendar-actions a:focus-visible{
  outline:3px solid rgba(167,116,22,.28);
  outline-offset:3px;
}

.button-primary{
  border-color:rgba(122,86,21,.34);
  background:linear-gradient(135deg,#f7e5aa,#d8ae53);
  box-shadow:0 9px 20px rgba(122,86,21,.16),inset 0 1px 0 rgba(255,255,255,.72);
  color:#4e360c;
}

.button-primary:hover{
  border-color:rgba(122,86,21,.48);
  background:linear-gradient(135deg,#fff0bd,#dfb75f);
  color:#3f2b09;
}

.match.fixture-card .button{
  border-color:var(--button-border);
  background:linear-gradient(145deg,rgba(255,255,255,.82),rgba(232,243,247,.76));
  box-shadow:var(--button-shadow);
  color:var(--button-blue);
}

.match.fixture-card .button:hover,
.match.fixture-card .button:focus-visible{
  border-color:rgba(122,86,21,.46);
  background:linear-gradient(135deg,#f5dfa3,#d5aa50);
  box-shadow:0 10px 22px rgba(122,86,21,.19),inset 0 1px 0 rgba(255,255,255,.5);
  color:#493309;
}

.home-matchday-button,
.standings-switch button.active,
.standings-scope-switch button.active,
.fantasy-strategy-tabs button.active,
.fantasy-squad-action.is-selected,
.referee-season-nav a.active{
  border-color:rgba(17,71,121,.5);
  background:linear-gradient(135deg,#2b76b9,var(--button-blue-strong));
  box-shadow:0 8px 19px rgba(22,76,130,.22),inset 0 1px 0 rgba(255,255,255,.24);
  color:#fff;
}

.standings-switch,
.standings-scope-switch{
  gap:6px;
  padding:6px;
  border-radius:18px;
}

.standings-switch button,
.standings-scope-switch button{
  border-color:transparent;
  background:transparent;
  box-shadow:none;
  color:#526266;
}

.standings-switch button:hover,
.standings-scope-switch button:hover{
  border-color:rgba(30,95,157,.28);
  background:linear-gradient(145deg,rgba(224,242,247,.96),rgba(196,226,235,.82));
  box-shadow:0 6px 15px rgba(31,78,116,.11),inset 0 1px 0 rgba(255,255,255,.7);
  color:var(--button-blue-strong);
}

/* Home: selettori compatti in vetro, senza intervenire sul tabellone. */
.home-standings .standings-switch,
.home-standings .standings-scope-switch{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  padding:0;
  border:0;
  border-radius:0;
  background:transparent;
  box-shadow:none;
}

.home-standings .standings-switch button,
.home-standings .standings-scope-switch button{
  flex:0 0 auto;
  min-height:36px;
  padding:8px 16px;
  border:1px solid rgba(255,255,255,.68);
  border-radius:999px;
  background:#eaf1f4;
  box-shadow:0 4px 12px rgba(20,43,59,.06),inset 0 1px rgba(255,255,255,.6);
  color:#283e4b;
  font-size:.86rem;
  line-height:1.2;
  font-weight:700;
  text-decoration:none;
  transform:none;
  transition:background-color .2s ease,box-shadow .2s ease,color .2s ease;
}

@supports ((backdrop-filter:blur(14px)) or (-webkit-backdrop-filter:blur(14px))){
  .home-standings .standings-switch button,
  .home-standings .standings-scope-switch button{
    background:linear-gradient(115deg,rgba(255,255,255,.38),rgba(255,255,255,.16)),rgba(225,238,243,.76);
    backdrop-filter:blur(14px) saturate(135%);
    -webkit-backdrop-filter:blur(14px) saturate(135%);
  }
}

.home-standings .standings-switch button:hover,
.home-standings .standings-scope-switch button:hover{
  background-color:#e0ebf0;
  color:#152e42;
  box-shadow:0 5px 14px rgba(20,43,59,.1),inset 0 1px rgba(255,255,255,.6);
  text-decoration:none;
  transform:none;
}

.home-standings .standings-switch button.active,
.home-standings .standings-scope-switch button.active{
  border-color:rgba(255,255,255,.24);
  background:#142c40;
  color:#fff;
  box-shadow:0 4px 12px rgba(20,43,59,.14),inset 0 1px rgba(255,255,255,.1);
  text-decoration:none;
  transform:none;
}

.home-standings .standings-switch button:focus-visible,
.home-standings .standings-scope-switch button:focus-visible{
  outline:2px solid #9a6912;
  outline-offset:3px;
}

.global-stat-button.active,
.fantasy-main-toggle.active,
.fantasy-main-action.is-main{
  border-color:rgba(155,108,23,.34);
  background:linear-gradient(135deg,#fff3c8,#e1bd68);
  box-shadow:0 7px 17px rgba(122,86,21,.15),inset 0 1px 0 rgba(255,255,255,.72);
  color:#66470f;
}

.fantasy-remove,
.player-detail-close,
.referee-profile-close{
  display:grid;
  place-items:center;
  border:1px solid rgba(36,90,120,.16);
  border-radius:50%;
  background:rgba(255,255,255,.72);
  box-shadow:0 6px 16px rgba(40,58,59,.1),inset 0 1px 0 #fff;
  color:#526266;
  cursor:pointer;
  transition:color .2s ease,border-color .2s ease,background .2s ease,box-shadow .2s ease,transform .2s ease;
}

.fantasy-remove:hover,
.player-detail-close:hover,
.referee-profile-close:hover{
  border-color:rgba(158,38,48,.24);
  background:#fff;
  box-shadow:0 9px 20px rgba(92,45,49,.13),inset 0 1px 0 #fff;
  color:#9e2630;
  transform:translateY(-1px);
}

.home-matchday-button:disabled,
.button[aria-disabled="true"],
button:disabled{
  box-shadow:none;
  cursor:not-allowed;
  opacity:.48;
  transform:none;
}

.menu-button{display:none}

@media(max-width:900px){.menu-button{display:inline-flex}}

@media(max-width:580px){
  .button,.menu-button,.home-matchday-button,.standings-switch button,.standings-scope-switch button,.fantasy-strategy-tabs button,.referee-season-nav a,.team-calendar-actions a{min-height:42px}
  .standings-switch{flex-direction:row}
  .team-calendar-actions a{flex:1}
  .home-standings .standings-switch button,.home-standings .standings-scope-switch button{min-height:36px;padding:8px 14px}
}

@media(prefers-reduced-motion:reduce){
  .button,.menu-button,.global-stat-button,.home-matchday-button,.standings-switch button,.standings-scope-switch button,.fantasy-main-toggle,.fantasy-reset,.fantasy-row-actions button,.fantasy-strategy-tabs button,.fantasy-recommendation-actions button,.fantasy-excluded button,.referee-card-action,.referee-season-nav a,.team-calendar-actions a,.fantasy-remove,.player-detail-close,.referee-profile-close{transition:none}
}

css/champions.css:
body[data-page="champions"]{
  --champions-blue:#041a57;
  --champions-blue-bright:#0d55cb;
  --champions-sky:#71b8ff;
  /* Regola visiva: nella sezione Champions i fondini restano sempre blu, mai bianchi. */
  --champions-surface:rgba(1,17,55,.56);
  --champions-surface-hover:rgba(15,86,171,.44);
  min-height:100vh;
  background:
    radial-gradient(circle at 82% 12%,rgba(43,133,255,.42),transparent 28rem),
    radial-gradient(circle at 8% 58%,rgba(21,72,190,.44),transparent 34rem),
    linear-gradient(155deg,#06143f 0%,#052b78 48%,#03143f 100%);
  color:#f7faff;
}

body[data-page="champions"]::before{
  display:block;
  background-image:radial-gradient(rgba(255,255,255,.28) 1px,transparent 1px);
  background-size:42px 42px;
  opacity:.2;
}

body[data-page="champions"] .site-header{--glass-text:#eaf4ff;--glass-color:#0a399b5e;border-color:rgba(147,200,255,.24)}
body[data-page="champions"] .brand strong,
body[data-page="champions"] .brand small,
body[data-page="champions"] .page-link{color:#eaf4ff}
body[data-page="champions"] .menu-button{color:#fff}
/* The original pale mobile dropdown needs the original dark navigation ink. */
@media(max-width:900px){body[data-page="champions"] .site-nav.open .page-link:not(.active){color:#283a3b}}
/* Static page marker: white from the first paint, with the original alpha channel. */
body[data-page="champions"] .site-header .brand-mark img{filter:brightness(0) invert(1)}
body[data-page="champions"] .page-link.active{background:rgba(15,86,171,.62);color:#fff}
body[data-page="champions"] .footer-brand-mark{background:#71b8ff}
body[data-page="champions"] main{padding-top:38px}

.champions-hero{
  position:relative;
  isolation:isolate;
  min-height:560px;
  padding:clamp(34px,6vw,72px);
  overflow:hidden;
  border:1px solid rgba(151,205,255,.34);
  border-radius:38px;
  background:linear-gradient(120deg,rgba(2,13,54,.94),rgba(7,57,148,.72));
  box-shadow:0 34px 90px rgba(0,6,36,.42),inset 0 1px rgba(255,255,255,.18);
}

.champions-hero::before{
  position:absolute;
  z-index:-1;
  inset:0;
  background:radial-gradient(circle at 78% 46%,rgba(86,171,255,.32),transparent 23rem),linear-gradient(110deg,transparent 58%,rgba(255,255,255,.07));
  content:"";
}

.champions-status{display:inline-flex;align-items:center;gap:9px;margin-bottom:62px;padding:8px 13px;border:1px solid rgba(144,206,255,.38);border-radius:999px;background:rgba(3,22,68,.58);color:#fff;font-size:11px;font-weight:850;letter-spacing:.12em;text-transform:uppercase;backdrop-filter:blur(10px)}
.champions-status span{width:7px;height:7px;border-radius:50%;background:#71b8ff;box-shadow:0 0 0 5px rgba(113,184,255,.14),0 0 18px #71b8ff}
.champions-hero .eyebrow{color:#91c9ff}
.champions-hero h1{max-width:780px;color:#fff;font-size:clamp(54px,7.2vw,94px);line-height:.94;text-shadow:0 10px 40px rgba(0,5,34,.34)}
.champions-hero .lead{max-width:690px;margin:26px 0 0;color:#c9ddf7;font-size:clamp(16px,1.6vw,20px)}
.champions-hero-stats{position:absolute;right:clamp(34px,6vw,72px);top:clamp(34px,6vw,72px);display:flex;gap:28px;z-index:1}
.champions-hero-stats div{display:grid;text-align:right}
.champions-hero-stats strong{color:#fff;font-family:var(--font-display);font-size:34px;font-weight:400;line-height:1}
.champions-hero-stats span{margin-top:4px;color:#8fc7ff;font-size:9px;font-weight:850;letter-spacing:.12em;text-transform:uppercase}

.champions-orbit{position:absolute;right:clamp(-80px,2vw,30px);bottom:-120px;display:grid;width:390px;height:390px;place-items:center;border:1px solid rgba(159,214,255,.22);border-radius:50%;box-shadow:0 0 0 54px rgba(106,181,255,.045),0 0 0 108px rgba(106,181,255,.025)}
.champions-orbit span{display:grid;width:126px;height:126px;place-items:center;border:1px solid rgba(190,225,255,.45);border-radius:50%;background:rgba(9,69,169,.68);color:#fff;font-size:58px;box-shadow:0 0 54px rgba(88,170,255,.5)}

.champions-strength-panel{margin-top:34px;overflow:hidden;border:1px solid rgba(137,194,255,.24);border-radius:24px;background:rgba(3,23,70,.62);box-shadow:0 20px 60px rgba(0,7,39,.2)}
.champions-strength-panel>summary{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:22px 26px;cursor:pointer;list-style:none}
.champions-strength-panel>summary::-webkit-details-marker{display:none}
.champions-strength-panel>summary>span:first-child{display:grid}
.champions-strength-panel>summary small{color:#82c0ff;font-size:9px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}
.champions-strength-panel>summary strong{margin-top:2px;color:#fff;font-size:24px}
.champions-strength-panel>summary>span:last-child{color:#a9c3e6;font-size:11px;font-weight:800}
.champions-strength-panel>summary::after{content:"+";display:grid;width:30px;height:30px;flex:0 0 30px;place-items:center;border:1px solid rgba(145,201,255,.22);border-radius:50%;color:#fff}
.champions-strength-panel[open]>summary::after{content:"−"}
.champions-completed-round-body{padding:0 clamp(14px,3vw,26px) 24px}
.champions-strength-intro{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:18px 26px;border-top:1px solid rgba(145,201,255,.12);background:rgba(2,16,54,.46)}
.champions-strength-intro p{max-width:800px;margin:0;color:#a9c3e6;font-size:13px}
.champions-strength-intro a{flex:none;color:#91c9ff;font-size:11px;font-weight:850;text-decoration:none}
.champions-source-links{display:flex;flex:none;flex-wrap:wrap;justify-content:flex-end;gap:10px 14px}
.champions-strength-table-wrap{overflow-x:auto}
.champions-strength-table{width:100%;min-width:850px;border-collapse:collapse}
.champions-strength-table th,.champions-strength-table td{padding:11px 14px;border-top:1px solid rgba(145,201,255,.1);color:#b7cae5;font-size:11px;text-align:left}
.champions-strength-table thead th{background:#0d4a9d;color:#c4e5ff;font-size:9px;letter-spacing:.09em;text-transform:uppercase}
.champions-strength-table tbody th{background:#0a3479;color:#fff;font-size:12px}
.champions-strength-table tbody th small{display:block;margin-top:2px;color:#a9d8ff;font-size:8px}
.champions-strength-table td:nth-child(5) strong{color:#fff;font-size:16px}
.champions-history-panel{margin-top:12px}
.champions-history-table{min-width:1080px}
.champions-history-table tbody th small{letter-spacing:0;text-transform:none}
.champions-history-table td:nth-child(2) strong{color:#fff;font-size:16px}
.champions-model-panel{border-color:rgba(113,184,255,.42);background:linear-gradient(135deg,rgba(8,53,139,.82),rgba(2,22,69,.86))}
.champions-model-body{padding:18px 26px 24px;border-top:1px solid rgba(145,201,255,.14)}
.champions-model-body>p{margin:0;color:#c9ddf7;font-size:13px}
.champions-model-metrics{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin:18px 0}
.champions-model-metrics>div{display:grid;gap:3px;padding:14px;border:1px solid rgba(145,201,255,.16);border-radius:14px;background:rgba(2,18,59,.52)}
.champions-model-metrics small{color:#91c9ff;font-size:8px;font-weight:900;letter-spacing:.09em;text-transform:uppercase}
.champions-model-metrics strong{color:#fff;font-family:var(--font-display);font-size:25px;font-weight:400}
.champions-model-metrics span{color:#a9c3e6;font-size:9px;font-weight:700}
.champions-model-note{color:#91aaca!important;font-size:11px!important}
.champions-team-logo-directory{margin-top:34px;padding:18px;border:1px solid rgba(100,220,255,.32);border-radius:24px;background:linear-gradient(135deg,rgba(4,74,145,.72),rgba(2,28,78,.84));box-shadow:0 20px 60px rgba(0,7,39,.2)}
.champions-team-logo-scroll{overflow-x:auto;padding:2px 2px 7px;scrollbar-color:rgba(126,218,255,.42) transparent;scrollbar-width:thin}
.champions-team-logo-grid{display:grid;grid-template-columns:repeat(12,minmax(48px,1fr));gap:8px;min-width:720px}
.champions-team-logo-grid a{display:grid;min-width:0;aspect-ratio:1;place-items:center;border:1px solid rgba(145,201,255,.18);border-radius:16px;background:var(--champions-surface);transition:border-color .18s ease,background .18s ease,transform .18s ease}
.champions-team-logo-grid a:hover,.champions-team-logo-grid a:focus-visible{border-color:rgba(127,224,255,.7);background:var(--champions-surface-hover);outline:none;transform:translateY(-2px)}
.champions-team-logo-grid img{display:block;width:58%;height:58%;object-fit:contain;filter:drop-shadow(0 7px 9px rgba(0,5,30,.34))}

.champions-pilot{margin-top:34px;padding:30px;border:1px solid rgba(100,220,255,.4);border-radius:30px;background:linear-gradient(145deg,rgba(8,69,151,.88),rgba(2,20,63,.92));box-shadow:0 24px 70px rgba(0,7,39,.28)}
.champions-pilot>header{display:flex;align-items:end;justify-content:space-between;gap:28px;margin-bottom:20px}
.champions-pilot>header>div{max-width:820px}
.champions-pilot .eyebrow{margin:0 0 5px;color:#7fe0ff}
.champions-pilot h2{margin:0;color:#fff}
.champions-pilot>header p:last-child{margin:8px 0 0;color:#bad8ef;font-size:13px}
.champions-pilot>header>span{flex:none;color:#83dfff;font-size:10px;font-weight:850;line-height:1.55;text-align:right;text-transform:uppercase}
.champions-pilot-validation{display:grid;grid-template-columns:1.35fr repeat(4,minmax(0,1fr));gap:8px;margin:0 0 18px;padding:10px;border:1px solid rgba(126,218,255,.18);border-radius:16px;background:rgba(1,18,58,.42)}
.champions-pilot-validation>p,.champions-pilot-validation>div{display:grid;align-content:center;gap:2px;margin:0;padding:8px 10px}
.champions-pilot-validation>p strong{color:#fff;font-size:11px}
.champions-pilot-validation>p span{color:#85a8c7;font-size:8px}
.champions-pilot-validation>div{border-left:1px solid rgba(126,218,255,.13)}
.champions-pilot-validation small{color:#7fdcff;font-size:7px;font-weight:900;text-transform:uppercase}
.champions-pilot-validation strong{color:#eaf8ff;font-size:10px}
.champions-pilot-validation>div span{color:#86b8d9;font-size:7px}
.champions-pilot-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
.champions-pilot-card{overflow:hidden;border:1px solid rgba(139,211,255,.22);border-radius:20px;background:rgba(1,15,52,.56)}
.champions-pilot-card.match.fixture-card .team-name,.champions-fixture.match.fixture-card .team-name{color:#fff}
.champions-reading-link{display:block;color:inherit;text-decoration:none;transition:border-color .18s ease,box-shadow .18s ease,transform .18s ease}
.champions-reading-link:hover,.champions-reading-link:focus-visible{border-color:rgba(127,224,255,.58);box-shadow:0 16px 34px rgba(0,8,37,.28);outline:none;transform:translateY(-2px)}
.champions-pilot-card>header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 18px;border-bottom:1px solid rgba(139,211,255,.15)}
.champions-pilot-card>header small{color:#83dfff;font-size:8px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}
.champions-pilot-card h3{margin:3px 0 0;color:#fff;font-size:17px}
.champions-pilot-card h3 span{color:#6bb9f4}
.champions-pilot-result{display:grid;flex:none;gap:3px;text-align:right}
.champions-pilot-result b{color:#eaf8ff;font-size:10px}
.champions-pilot-result small{color:#79bfe9;font-size:8px;font-weight:800}
.champions-pilot-fixture-teams{min-height:166px}
.champions-pilot-card .champions-pilot-result{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:10px 18px;border-top:1px solid rgba(139,211,255,.12);border-bottom:1px solid rgba(139,211,255,.12);background:var(--champions-surface-hover);text-align:left}
.champions-pilot-card .champions-pilot-result b{color:#eaf8ff;font-size:10px}
.champions-pilot-card .champions-pilot-result small{color:#9bcff1;font-size:8px;font-weight:900;letter-spacing:.06em;text-transform:uppercase}
.champions-pilot-card .champions-reading-preview{background:rgba(18,64,119,.28)}
.champions-pilot-card .champions-reading-preview>span{background:var(--champions-surface)}
.champions-pilot-card .champions-reading-preview small{color:#9bcff1}
.champions-pilot-card .champions-reading-preview strong{color:#eaf8ff}
.champions-pilot-card.champions-reading-link>footer{border-top-color:rgba(139,211,255,.12);background:rgba(8,58,145,.48);color:#9bdcff}
.champions-pilot-score{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:13px 18px;background:rgba(15,86,171,.24)}
.champions-pilot-score>div{display:grid}
.champions-pilot-score small,.champions-pilot-markets>div>small{color:#83b6da;font-size:8px;font-weight:800;text-transform:uppercase}
.champions-pilot-score strong{color:#fff;font-family:var(--font-display);font-size:25px;font-weight:400}
.champions-pilot-score p{margin:0;color:#a9d5f5;font-size:9px;text-align:right}
.champions-reading-preview{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;background:rgba(139,211,255,.1)}
.champions-reading-preview>span{display:grid;gap:3px;padding:13px 16px;background:rgba(1,15,52,.8)}
.champions-reading-preview small{color:#7eb8df;font-size:7px;font-weight:900;letter-spacing:.07em;text-transform:uppercase}
.champions-reading-preview strong{overflow:hidden;color:#eaf8ff;font-size:10px;text-overflow:ellipsis;white-space:nowrap}
.champions-pilot-teams{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));border-top:1px solid rgba(139,211,255,.1);border-bottom:1px solid rgba(139,211,255,.1)}
.champions-pilot-team{padding:15px 18px}
.champions-pilot-team+ .champions-pilot-team{border-left:1px solid rgba(139,211,255,.12)}
.champions-pilot-team h4,.champions-pilot-markets h4{margin:0 0 9px;color:#fff;font-size:11px}
.champions-pilot-team dl{display:grid;gap:6px;margin:0}
.champions-pilot-team dl div{display:flex;align-items:center;justify-content:space-between;gap:8px}
.champions-pilot-team dt{color:#82b5d9;font-size:8px}
.champions-pilot-team dd{margin:0;color:#e7f7ff;font-size:9px;font-weight:800}
.champions-pilot-markets{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0}
.champions-pilot-markets>div{padding:15px 18px}
.champions-pilot-markets>div+div{border-left:1px solid rgba(139,211,255,.12)}
.champions-pilot-markets>div>div{display:flex;flex-wrap:wrap;gap:6px}
.champions-pilot-markets span{display:grid;min-width:70px;padding:6px 8px;border:1px solid rgba(130,202,255,.15);border-radius:9px;background:rgba(11,57,124,.42);color:#e8f7ff;font-size:9px}
.champions-pilot-markets span b{color:#8edfff;font-size:8px}
.champions-pilot-markets span small{color:#809fbd;font-size:7px}
.champions-pilot-markets>div>small{display:block;margin-top:8px}
.champions-pilot-card>footer{padding:9px 18px;border-top:1px solid rgba(139,211,255,.1);color:#7899b8;font-size:8px;font-weight:800;text-transform:uppercase}
.champions-reading-link>footer{display:flex;align-items:center;justify-content:space-between;color:#86dfff}
.champions-reading-link>footer b{font-size:16px;transition:transform .18s ease}
.champions-reading-link:hover>footer b{transform:translateX(3px)}
.champions-pilot-note{margin:16px 0 0;color:#8fb1cd;font-size:10px}
.champions-reading-back{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:10px 0 18px}
.champions-reading-back a{color:#8bdfff;font-size:10px;font-weight:900;text-decoration:none;text-transform:uppercase}
.champions-reading-back span{color:#779bbd;font-size:9px;font-weight:850;text-transform:uppercase}
.champions-reading-hero{display:flex;align-items:center;justify-content:space-between;gap:32px;padding:38px 42px;border:1px solid rgba(121,207,255,.35);border-radius:30px;background:radial-gradient(circle at 80% 20%,rgba(29,122,214,.36),transparent 40%),linear-gradient(145deg,#073d8e,#02143f);box-shadow:0 24px 70px rgba(0,7,39,.3)}
.champions-reading-hero .eyebrow{margin:0 0 7px;color:#83dfff}
.champions-reading-hero h1{margin:0;color:#fff;font-family:var(--font-display);font-size:clamp(42px,6vw,74px);font-weight:400;letter-spacing:-.02em;line-height:.95;text-transform:uppercase}
.champions-reading-hero h1 span{color:#6dbdf6}
.champions-reading-hero>div:first-child>p:last-child{margin:14px 0 0;color:#a7c9e6;font-size:12px;text-transform:capitalize}
.champions-reading-hero-result{display:grid;grid-template-columns:repeat(3,auto);gap:8px;flex:none;padding:14px;border:1px solid rgba(127,224,255,.18);border-radius:18px;background:rgba(1,17,55,.5)}
.champions-reading-hero-result small{grid-column:1/-1;color:#77badf;font-size:8px;font-weight:900;text-transform:uppercase}
.champions-reading-hero-result strong{padding:8px 10px;border-radius:9px;background:rgba(18,91,168,.35);color:#fff;font-size:11px}
.champions-reading-warning{margin:14px 0 0;padding:14px 17px;border:1px solid rgba(127,224,255,.18);border-radius:15px;background:rgba(3,31,82,.66);color:#9fc2df;font-size:10px;line-height:1.55}
.champions-reading-warning strong{color:#83e0ff}
.champions-reading-analysis{margin-top:18px}
.champions-pilot-card-detail{background:linear-gradient(145deg,rgba(8,69,151,.78),rgba(2,20,63,.92))}
.champions-pilot-card-detail>header{padding:20px 22px}
.champions-pilot-card-detail .champions-pilot-team{padding:20px 22px}
.champions-pilot-card-detail .champions-pilot-markets>div{padding:20px 22px}
.champions-reading-method{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:12px}
.champions-reading-method>div{display:grid;gap:3px;padding:13px 15px;border:1px solid rgba(132,199,255,.18);border-radius:12px;background:rgba(2,28,76,.72)}
.champions-reading-method small{color:#79b7df;font-size:7px;font-weight:900;text-transform:uppercase}
.champions-reading-method strong{color:#e8f7ff;font-size:11px}
.champions-reading-match-hero{border-color:rgba(121,207,255,.35);background:radial-gradient(circle at 84% 8%,rgba(35,131,225,.3),transparent 34%),linear-gradient(145deg,rgba(7,61,142,.96),rgba(2,20,63,.98));box-shadow:0 24px 70px rgba(0,7,39,.3)}
.champions-reading-match-hero h1,.champions-reading-match-hero h2,.champions-reading-match-hero h3{color:#fff}
.champions-reading-match-hero .eyebrow,.champions-reading-info .eyebrow,.champions-reading-volume .eyebrow,.champions-reading-validation .eyebrow{color:#83dfff}
.champions-reading-match-hero>div:first-child>p:not(.eyebrow){color:#a7c9e6}
.champions-reading-matchup{grid-template-columns:minmax(100px,1fr) auto minmax(100px,1fr)}
.champions-reading-matchup>span{display:grid;align-content:center;min-height:110px;padding:18px;border:1px solid rgba(127,224,255,.18);border-radius:20px;background:rgba(1,17,55,.5);text-align:center}
.champions-reading-matchup>span small{color:#77badf;font-size:8px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}
.champions-reading-matchup>span strong{margin-top:8px;color:#fff;font-size:16px;line-height:1.15}
.champions-reading-matchup>b{color:#83dfff}
