body[data-page="champions"] .champions-reading-referee-profile>.champions-reading-referee-stats strong{font-size:16px}
body[data-page="champions"] .champions-reading-referee-sample{margin:0;padding:0 2px;color:#aac3dd;font-size:9px;line-height:1.45}
