  body[data-page="champions"] .champions-reading-hero-referee>dl{grid-column:2}
  body[data-page="champions"] .champions-reading-hero-referee>.champions-reading-referee-stats,body[data-page="champions"] .champions-reading-hero-referee:not(:has(>dl))>.champions-reading-referee-stats{grid-column:1/-1}
  body[data-page="champions"] .champions-reading-referee-detail{grid-template-columns:1fr}
