  body[data-page="champions"] .champions-reading-hero-referee.reading-referee-assignment,body[data-page="champions"] .champions-reading-hero-referee:not(:has(>dl)){grid-template-columns:1fr;gap:8px;padding:12px}
  body[data-page="champions"] .champions-reading-hero-referee>header,body[data-page="champions"] .champions-reading-hero-referee>dl,body[data-page="champions"] .champions-reading-hero-referee>.champions-reading-referee-stats,body[data-page="champions"] .champions-reading-hero-referee:not(:has(>dl))>.champions-reading-referee-stats{grid-column:1}
  body[data-page="champions"] .champions-reading-hero-referee>dl{grid-template-columns:repeat(2,minmax(0,1fr))}
  body[data-page="champions"] .champions-reading-hero-referee>.champions-reading-referee-stats{grid-template-columns:repeat(2,minmax(0,1fr))}
  body[data-page="champions"] .champions-reading-referee-profile>.champions-reading-referee-stats{grid-template-columns:repeat(2,minmax(0,1fr))}
  body[data-page="champions"] .champions-reading-referee-detail>section{padding:8px}
  body[data-page="champions"] .champions-selected-forecasts .champions-published-forecasts li{grid-template-columns:1fr;padding:13px}
  body[data-page="champions"] .champions-published-metrics{grid-template-columns:repeat(3,minmax(0,1fr))}
  body[data-page="champions"] .champions-reading-tactical-analysis .prediction-channels>div{grid-template-columns:48px minmax(0,1fr) 42px}
}
.champions-published-forecasts li[data-settlement="won"] { border-left: 4px solid #34d399; background: rgba(16,185,129,.10); }
.champions-published-forecasts li[data-settlement="lost"] { border-left: 4px solid #f87171; background: rgba(239,68,68,.10); }
.champions-published-forecasts li[data-settlement="won"] .champions-published-result { color: #34d399; font-weight: 700; }
.champions-published-forecasts li[data-settlement="lost"] .champions-published-result { color: #f87171; font-weight: 700; }
.champions-published-result { font-weight: 700; }

/* Shared Champions canvas for overview and all team pages; match readings stay separate. */
body[data-page="champions"]:has(#app > :is(.champions-overview,.champions-team-detail)){
  background-color:#07152c;
  background-image:radial-gradient(ellipse 90vw 80vh at 88% 6%,rgba(29,71,119,.46),transparent 80%),radial-gradient(ellipse 85vw 100vh at -12% 64%,rgba(20,49,88,.42),transparent 82%),radial-gradient(ellipse 75vw 75vh at 80% 112%,rgba(18,38,75,.36),transparent 82%);
  background-repeat:no-repeat;
  background-attachment:fixed;
  color:#f7faff;
  color-scheme:dark;
}
/* Use the original shared navbar/footer rules above, including Champions colours. */
.champions-overview{min-width:0}
.champions-overview .champions-round-summary>summary strong{font-size:18px}
.champions-overview .champions-round-summary>summary{gap:12px;flex-wrap:wrap}
.champions-overview .champions-round-summary table{width:100%;min-width:480px;border-collapse:collapse;color:#c9ddf7}
.champions-overview .champions-round-summary :is(th,td){padding:10px 14px;border-top:1px solid #304762;text-align:left}
.champions-overview .champions-round-summary th{color:#f2f6ff}
.champions-overview .champions-archive-title{margin:30px 0 12px;color:#afc3dc;font-size:13px;font-weight:650;letter-spacing:.03em}
.champions-overview .champions-completed-round{margin-top:10px;border-radius:15px;box-shadow:none}
.champions-overview .champions-completed-round>summary{gap:12px;padding:13px 18px}
.champions-overview .champions-completed-round>summary strong{font-size:17px}
.champions-overview .champions-completed-round>summary small{font-size:9px;letter-spacing:.05em}
.champions-overview .champions-completed-round>summary>span:first-child{min-width:0}
.champions-overview .champions-completed-round>summary>span:last-of-type{margin-left:auto;white-space:nowrap}
.champions-overview .champions-controls :is(select,button):focus-visible{outline:2px solid #9edbff;outline-offset:3px}
