css/components.css:
/* components.css - modulo del sistema grafico condiviso. */
.eyebrow{margin:0 0 8px;color:var(--accent);font-size:12px;font-weight:900;letter-spacing:.13em;text-transform:uppercase}

.lead{max-width:720px;color:#c8d5d0;font-size:18px}

.card{padding:21px;border:1px solid var(--line);border-radius:15px;background:var(--surface)}

.card p:last-child{margin-bottom:0}

.status{display:inline-flex;padding:4px 8px;border-radius:999px;background:#24352f;color:#b8c7c2;font-size:11px;font-weight:800;text-transform:uppercase}

.status.finished,.status.won{background:rgba(39,209,127,.14);color:#65e7a4}

.status.live{background:rgba(255,107,107,.14);color:#ff8d8d}

.status.postponed,.status.lost{background:rgba(242,193,78,.13);color:#f2c14e}

.score{font-size:22px}

.button{display:inline-flex;padding:8px 11px;border:1px solid var(--line);border-radius:8px;color:var(--text);font-size:12px;text-decoration:none}

.button:hover{border-color:var(--accent)}

.selector{display:flex;gap:10px;align-items:center;margin-bottom:18px}

select{padding:10px 36px 10px 12px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--text)}

.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:14px}

table{width:100%;border-collapse:collapse;background:var(--surface)}

th,td{padding:12px 14px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}

th{color:var(--muted);font-size:11px;text-transform:uppercase}

th:nth-child(2),td:nth-child(2){text-align:left}

tr:last-child td{border:0}

.source-list li{margin:10px 0}

.sources-hero{margin-bottom:0}
.sources-directory{padding:clamp(22px,3vw,34px);border:1px solid rgba(36,90,120,.12);border-radius:30px;background:rgba(255,255,255,.58);box-shadow:0 18px 50px rgba(32,49,73,.08)}
.source-team-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:14px}
.source-team-card{align-self:start;border:1px solid rgba(36,90,120,.14);border-radius:22px;background:rgba(255,255,255,.72);box-shadow:0 10px 28px rgba(32,49,73,.06);overflow:hidden}
.source-team-card>summary{display:flex;align-items:center;gap:13px;padding:16px 18px;cursor:pointer;list-style:none}
.source-team-card>summary::-webkit-details-marker{display:none}
.source-team-card>summary::after{margin-left:auto;color:var(--gold-dark);font-size:20px;content:"+"}
.source-team-card[open]>summary::after{content:"−"}
.source-team-card>summary img{width:44px;height:44px;object-fit:contain}
.source-team-card>summary span{display:grid;gap:2px}
.source-team-card>summary strong{color:var(--ink)}
.source-team-card>summary small{color:var(--muted)}
.source-directory-list{display:grid;gap:0;margin:0;padding:0 18px 16px;list-style:none}
.source-directory-list li{display:grid;gap:5px;padding:14px 0;border-top:1px solid rgba(36,90,120,.1)}
.source-directory-list li>strong{color:var(--ink)}
.source-directory-list li>span,.source-directory-list li>small{color:var(--muted);line-height:1.5}
.source-directory-list li>a{width:max-content;color:var(--blue);font-weight:750}

footer{padding:24px 20px;border-top:1px solid var(--line);color:var(--muted);text-align:center;font-size:13px}

.empty{padding:32px;border:1px dashed var(--line);border-radius:14px;color:var(--muted);text-align:center}

/* Palette Serie A: blu profondo, blu reale, oro e bianco caldo. */
:root{--bg:#031234;--surface:#081d48;--surface2:#102d68;--line:#294b87;--text:#fffaf0;--muted:#b7c7e2;--accent:#e5b94f;--gold:#f4cf72;--danger:#ff7c7c;--royal:#174fa5;--ivory:#fffaf0}

.lead{color:#dbe4f3}

.card{background:linear-gradient(155deg,rgba(16,45,104,.98),rgba(8,29,72,.98));box-shadow:inset 0 1px rgba(255,255,255,.035)}

.status{background:#17376d;color:#d5e0f1}

.status.finished,.status.won{background:rgba(229,185,79,.17);color:#ffe39a}

.status.live{background:rgba(255,124,124,.15);color:#ff9d9d}

.status.postponed,.status.lost{background:rgba(244,207,114,.13);color:#f4cf72}

table{background:var(--surface)}

tbody tr:hover{background:rgba(23,79,165,.18)}

.button:hover{border-color:var(--gold);color:#fff4ce}

.eyebrow{color:var(--gold)}

.status.provisional{margin-left:6px;background:rgba(229,185,79,.16);color:#ffe39a}

.day-link{display:grid;place-items:center;min-width:0;height:30px;border:1px solid transparent;border-radius:7px;color:var(--muted);font-size:12px;font-weight:800;text-decoration:none}

.day-link:hover,.day-link.active{border-color:var(--accent);background:rgba(39,209,127,.13);color:var(--text)}

/* Logo Serie A fornito per l'identità del sito. */
.ranking-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:18px 0}

.ranking-card ol{margin:14px 0 0;padding-left:22px}

.ranking-card li{padding:7px 0;border-bottom:1px solid var(--line)}

.ranking-card li:last-child{border:0}

.ranking-card li span{padding-left:4px}

.ranking-card li strong{float:right;color:var(--gold)}

.standing-logo{display:grid;place-items:center;flex:0 0 30px;width:30px;height:30px}

.standing-logo img{width:100%;height:100%;object-fit:contain}

.standing-logo.fallback{border:1px solid var(--line);border-radius:50%;background:var(--surface2)}

.sample-label{display:inline-flex;padding:4px 8px;border-radius:999px;font-size:10px;font-weight:800}

.sample-low{background:rgba(255,107,107,.12);color:#ff9d9d}

.sample-medium{background:rgba(242,193,78,.12);color:#ffe39a}

.sample-strong{background:rgba(39,209,127,.12);color:#65e7a4}

.method-note{margin-top:42px;padding:20px;border:1px solid rgba(242,193,78,.38);border-radius:14px;background:rgba(242,193,78,.07)}

.method-note p{margin:6px 0 0;color:#d5dfef}

.pilot-section{padding:25px;border:1px solid rgba(67,119,205,.45);border-radius:20px;background:linear-gradient(145deg,rgba(23,79,165,.16),rgba(8,24,43,.76))}

.lead-small{max-width:780px;color:#d5dfef}

.pilot-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}

.pilot-summary article{padding:16px;border:1px solid var(--line);border-radius:13px;background:rgba(5,17,37,.5)}

.pilot-summary span{display:block;color:var(--muted);font-size:11px;font-weight:900;letter-spacing:.06em;text-transform:uppercase}

.pilot-summary strong{display:block;margin-top:5px;color:#fff;font-size:26px}

.pilot-summary .pilot-warning strong{color:var(--gold)}

.pilot-missing{margin:18px 0 26px;padding:16px;border:1px solid rgba(242,193,78,.38);border-radius:12px;background:rgba(242,193,78,.07)}

.pilot-missing p{margin:4px 0 0;color:#f1dfae}

.pilot-subtitle{margin:30px 0 12px;font-size:21px}

.competition-chip{display:inline-flex;padding:4px 8px;border-radius:999px;background:rgba(23,79,165,.3);color:#bad2ff;font-size:10px;font-weight:900}

.source-id{display:inline-block;margin:1px;padding:3px 6px;border:1px solid var(--line);border-radius:6px;color:#bad2ff;font-size:10px;text-decoration:none}

.source-id:hover{border-color:var(--gold);color:#fff}

.competition-chip{display:inline-flex;padding:4px 9px;border-radius:999px;background:#eaf2ff;color:#143a79;font-size:.75rem;font-weight:800}

.updated,.muted{color:var(--muted,#667085)}

.competition-warning,.data-warning{max-width:1132px;margin:0 auto 24px;padding:18px 20px;border-radius:14px;background:#fff7dd;border:1px solid #e8ca68}

.detail-section{padding-top:18px}

.split-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}

.source-list{padding-left:20px}

.source-list li{margin:8px 0}

.subpage-header{display:flex;justify-content:space-between;padding-bottom:0}

.subpage-header a{font-weight:800}

.detail-section code{padding:2px 5px;border-radius:5px;background:#eef1f5}

.mini-avatar{display:grid;place-items:center;flex:0 0 34px;width:34px;height:34px;border-radius:50%;background:#171717;color:#fff;font-size:.72rem;font-weight:900}

.status-badge{display:inline-flex;align-items:center;padding:4px 8px;border-radius:999px;background:#f0f2f5;color:#343a46;font-size:.72rem;font-weight:800;white-space:nowrap}

.competition-selector{display:block;margin:22px 0;font-size:.78rem;font-weight:800}

.competition-selector select{display:block;width:100%;margin-top:5px;padding:10px;border:1px solid var(--line,#ccd2dc);border-radius:9px;background:var(--card,#fff);color:inherit}

.quality-complete{color:#08783e!important}

.quality-partial{color:#946100!important}

.quality-unavailable{color:#a12828!important}

.mini-avatar{object-fit:cover;object-position:top}

.mini-avatar.is-fallback{object-fit:contain;object-position:center;background:#fff}

.competition-selector select{background:var(--surface);color:var(--text)}

.competition-chip{border:1px solid rgba(244,207,114,.42);background:rgba(229,185,79,.15);color:#ffe59a}

.competition-warning,.data-warning{border-color:rgba(229,185,79,.55);background:linear-gradient(135deg,rgba(229,185,79,.13),rgba(8,29,72,.98));color:var(--text)}

.detail-section code{background:var(--surface2);color:#ffe59a}

.global-stat-group{display:grid;grid-template-columns:96px minmax(0,1fr);align-items:start;gap:8px}

.global-stat-group>strong{padding-top:6px;color:#dbe6f8;font-size:.7rem;letter-spacing:.05em;text-transform:uppercase}

.global-stat-group>div{display:flex;flex-wrap:wrap;gap:5px}

