css/fantasy.css:
/* fantasy.css - modulo del sistema grafico condiviso. */
/* Fantacalcio: configuratore budget, slot e board d'asta. */
.fantasy-config{display:grid;grid-template-columns:260px 1fr;gap:20px;margin-top:28px;padding:22px;border:1px solid var(--line);border-radius:24px;background:linear-gradient(135deg,rgba(243,201,105,.12),rgba(18,27,48,.78))}

.fantasy-config label{display:block;margin-bottom:8px;font-weight:700}

.fantasy-budget-input{display:flex;align-items:center;gap:10px}

.fantasy-budget-input input{width:130px;height:52px;padding:0 14px;border:1px solid rgba(243,201,105,.45);border-radius:14px;background:rgba(5,8,18,.7);color:#fff;font-size:24px;font-weight:750}

.fantasy-budget-input span{color:var(--muted);font-size:12px}

.fantasy-plan{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}

.fantasy-plan article{padding:14px;border:1px solid var(--line);border-radius:15px;background:rgba(255,255,255,.035)}

.fantasy-plan span,.fantasy-plan small{display:block;color:var(--muted);font-size:10px}

.fantasy-plan strong{display:block;margin:5px 0 1px;color:var(--gold);font-size:22px}

.fantasy-slots>div{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}

.fantasy-slots article{display:flex;gap:12px;align-items:flex-start;padding:17px;border:1px solid var(--line);border-radius:17px;background:var(--surface)}

.fantasy-slots p{margin:0;color:var(--muted);font-size:12px}

.fantasy-slot{display:grid;place-items:center;flex:0 0 30px;width:30px;height:30px;border-radius:9px;font-weight:900}

.fantasy-board>.section-heading>p{max-width:260px;color:var(--muted);font-size:12px;text-align:right}

.fantasy-controls{position:sticky;z-index:9;top:92px;display:grid;grid-template-columns:1fr 180px 150px auto;gap:10px;align-items:end;margin-bottom:14px;padding:14px;border:1px solid var(--line-strong);border-radius:18px;background:rgba(8,14,29,.92);backdrop-filter:blur(18px)}

.fantasy-controls label span{display:block;margin-bottom:5px;color:var(--muted);font-size:10px;font-weight:800;text-transform:uppercase}

.fantasy-controls input,.fantasy-controls select{width:100%;height:42px;padding:0 12px;border:1px solid var(--line);border-radius:11px;background:#111c32;color:#fff}

.fantasy-controls>strong{align-self:center;color:var(--gold);font-size:12px}

.fantasy-table th:nth-child(n),.fantasy-table td:nth-child(n){text-align:left}

.fantasy-table td{vertical-align:middle}

.fantasy-player{display:flex;flex-direction:column;color:#fff;text-decoration:none}

.fantasy-player:hover strong{color:var(--gold)}

.fantasy-player small,.fantasy-index{color:var(--muted);font-size:10px}

.fantasy-team{display:flex;align-items:center;gap:8px}

.fantasy-team img{width:28px;height:28px;object-fit:contain}

.fantasy-price{color:var(--gold);font-size:18px}

.fantasy-method{margin-top:16px;padding:18px;border-left:3px solid var(--gold);border-radius:0 14px 14px 0;background:rgba(243,201,105,.07)}

.fantasy-method p{margin:4px 0;color:var(--muted);font-size:12px}

.goalkeeper-rotation{margin-top:28px}

.goalkeeper-rotation>.section-heading>p{max-width:330px;color:var(--muted);font-size:12px;text-align:right}

.goalkeeper-trios{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}

.goalkeeper-trios>article{padding:18px;border:1px solid var(--line);border-radius:18px;background:var(--surface)}

.goalkeeper-trio-head,.goalkeeper-list>div{display:flex;align-items:center;justify-content:space-between;gap:12px}

.goalkeeper-trio-head{padding-bottom:12px;border-bottom:1px solid var(--line)}

.goalkeeper-trio-head span{color:var(--muted);font-size:11px;font-weight:800;text-transform:uppercase}

.goalkeeper-trio-head strong{color:var(--gold)}

.goalkeeper-list{display:grid;gap:9px;padding:14px 0}

.goalkeeper-list span,.goalkeeper-list small{display:block}

.goalkeeper-list small{margin-top:2px;color:var(--muted);font-size:10px}

.goalkeeper-list>div>strong{color:var(--gold)}

.goalkeeper-trios dl{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin:0}

.goalkeeper-trios dl div{padding:9px;border-radius:10px;background:rgba(255,255,255,.035)}

.goalkeeper-trios dt{color:var(--muted);font-size:9px;text-transform:uppercase}

.goalkeeper-trios dd{margin:2px 0 0;font-weight:800}

.goalkeeper-note{margin:12px 0 0;color:var(--muted);font-size:11px}

.fantasy-slots>div{grid-template-columns:repeat(5,1fr)}

.fantasy-role{display:grid;place-items:center;width:32px;height:32px;margin-bottom:6px;border-radius:9px;color:#fff;font-weight:950}

.fantasy-stars{display:block;color:#f3c969;font-size:15px;font-weight:900;letter-spacing:1px;white-space:nowrap;text-shadow:0 1px 8px rgba(243,201,105,.2)}

.fantasy-slots .fantasy-stars{font-size:18px}

.fantasy-controls #fantasy-search{background:#071326;color:#fff;caret-color:#f3c969;border-color:rgba(243,201,105,.48)}

.fantasy-controls #fantasy-search::placeholder{color:#aebbd0;opacity:1}

.fantasy-controls #fantasy-search:-webkit-autofill,.fantasy-controls #fantasy-search:-webkit-autofill:hover,.fantasy-controls #fantasy-search:-webkit-autofill:focus{-webkit-text-fill-color:#fff;box-shadow:0 0 0 1000px #071326 inset;caret-color:#f3c969}

.fantasy-table{min-width:1150px;table-layout:fixed}

.fantasy-table th:nth-child(1){width:132px}

.fantasy-table th:nth-child(2){width:285px}

.fantasy-table th:nth-child(3){width:150px}

.fantasy-table th:nth-child(4){width:88px}

.fantasy-table th:nth-child(5){width:135px}

.fantasy-table th:nth-child(6){width:90px}

.fantasy-table th:nth-child(7){width:90px}

.fantasy-table th:nth-child(8){width:112px}

.fantasy-table th:nth-child(9){width:105px}

.fantasy-sort{display:inline-grid;grid-template-columns:1fr 12px;align-items:center;width:100%;gap:4px;padding:0;border:0;background:transparent;color:inherit;font:inherit;font-weight:800;text-align:left;cursor:pointer;white-space:nowrap}

.fantasy-sort span{display:block;width:12px;color:var(--muted);opacity:.55;text-align:center}

.fantasy-sort:hover,.fantasy-sort:focus-visible,.fantasy-sort.active{color:var(--gold)}

.fantasy-sort.active span{opacity:1}

.fantasy-controls select{color-scheme:dark;background-color:#111c32;color:#f7f9fc}

.fantasy-controls select option{background:#111c32;color:#f7f9fc}

.fantasy-controls select option:checked{background:#274266;color:#fff}

.fantasy-player-button{padding:0;border:0;background:none;text-align:left;cursor:pointer}

.lineup-calendar{scroll-margin-top:110px}

.lineup-calendar>header{display:flex;align-items:end;justify-content:space-between;gap:18px;margin-bottom:18px}

.lineup-calendar>header h2{margin-bottom:4px}

.lineup-calendar>header p:last-child{margin:0;color:var(--muted)}

.lineup-calendar-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}

.fantasy-player-stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin:0 0 20px}

.fantasy-player-stats article{padding:16px;border:1px solid var(--line);border-radius:16px;background:var(--surface)}

.fantasy-player-stats span,.fantasy-player-stats small{display:block;color:var(--muted);font-size:10px}

.fantasy-player-stats strong{display:block;margin:5px 0;color:var(--gold);font-size:20px}

.fantasy-controls #fantasy-search{background:#071326!important;color:#fff!important;-webkit-text-fill-color:#fff!important;caret-color:#f3c969}

.fantasy-controls #fantasy-search::placeholder{color:#aebbd0!important;opacity:1}

.card,.home-next,.home-rail a,.day-nav,.referee-controls,.editorial-empty,.cup-stage,.objective-card,.squad-leader-card,.pilot-section,.goalkeeper-trios>article,.fantasy-slots article{border-color:rgba(111,172,244,.25);background:linear-gradient(145deg,rgba(18,72,148,.78),rgba(7,39,89,.78));box-shadow:inset 0 1px rgba(160,202,255,.09),0 18px 48px rgba(0,18,60,.22)}

