/* Costruttore rosa Fantacalcio */
.fantasy-composition{margin-bottom:14px;padding:16px;border:1px solid #d9e0e8;border-radius:18px;background:rgba(255,255,255,.62)}

.fantasy-composition header{display:flex;justify-content:space-between;gap:18px;align-items:end;margin-bottom:13px}

.fantasy-composition header span,.fantasy-composition header strong{display:block}

.fantasy-composition header span,.fantasy-composition-controls label span{color:#647086;font-size:.66rem;font-weight:850;text-transform:uppercase}

.fantasy-composition header strong{margin-top:3px;color:#172033}

.fantasy-composition header p{margin:0;color:#3f6e55;font-size:.72rem;font-weight:800;text-align:right}

.fantasy-composition header p.is-alert{color:#b52631}

.fantasy-composition-controls{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px}

.fantasy-composition-controls label{display:block}

.fantasy-composition-controls label span{display:block;margin-bottom:5px}

.fantasy-composition-controls input{width:100%;height:42px;padding:0 11px;border:1px solid #cbd4df;border-radius:10px;background:#fff;color:#172033;font-weight:800}

.fantasy-total-control{padding-right:9px;border-right:1px solid #d9e0e8}

.fantasy-squad-builder,.fantasy-recommendations{scroll-margin-top:96px}

.fantasy-squad-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}

.fantasy-squad-summary article{padding:16px;border:1px solid rgba(255,255,255,.86);border-radius:16px;background:rgba(255,255,255,.7);box-shadow:0 12px 32px rgba(28,39,55,.06)}

.fantasy-squad-summary span,.fantasy-squad-summary strong{display:block}

.fantasy-squad-summary span{color:#647086;font-size:.68rem;font-weight:800;text-transform:uppercase}

.fantasy-squad-summary strong{margin-top:4px;color:#172033;font-size:1.55rem}

.fantasy-squad-summary .is-alert{border-color:#d74b55;background:#fff1f2}

.fantasy-squad-summary .is-alert strong{color:#b52631}

.fantasy-role-progress{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:10px}

.fantasy-role-progress article{padding:12px 14px;border:1px solid #d9e0e8;border-radius:14px;background:rgba(255,255,255,.54)}

.fantasy-role-progress span,.fantasy-role-progress strong{display:block;color:#172033}

.fantasy-role-progress span{font-size:.68rem}

.fantasy-role-progress strong{margin-top:2px}

.fantasy-role-progress i{display:block;height:4px;margin-top:8px;overflow:hidden;border-radius:999px;background:#dfe5ec}

.fantasy-role-progress b{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#1459a6,#e0a72d)}

.fantasy-squad-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin-top:14px}

.fantasy-squad-player{display:grid;grid-template-columns:minmax(0,1fr) 88px auto 34px;gap:10px;align-items:center;padding:12px;border:1px solid #d9e0e8;border-radius:15px;background:rgba(255,255,255,.76)}

.fantasy-squad-player.is-main{border-color:#dfad3c;box-shadow:inset 3px 0 #dfad3c}

.fantasy-squad-player>div{display:flex;align-items:center;gap:9px;min-width:0}

.fantasy-squad-player .fantasy-role{flex:0 0 32px;margin:0}

.fantasy-squad-player>div button,.fantasy-recommendation-role article>div button{min-width:0;padding:0;border:0;background:none;color:#172033;text-align:left;cursor:pointer}

.fantasy-squad-player>div strong,.fantasy-squad-player>div small,.fantasy-recommendation-role article>div strong,.fantasy-recommendation-role article>div small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

.fantasy-squad-player>div small,.fantasy-recommendation-role article>div small{color:#647086;font-size:.66rem}

.fantasy-squad-player label span{display:block;color:#647086;font-size:.6rem;font-weight:800;text-transform:uppercase}

