css/home.css:
/* home.css - modulo del sistema grafico condiviso. */
/* Classifiche: selettore stagione, punti prioritari e stemmi. */
.standings-switch{display:flex;gap:10px;margin:24px 0 8px;padding:7px;border:1px solid var(--line);border-radius:14px;background:rgba(8,24,43,.82)}

.standings-switch button{flex:1;padding:11px 16px;border:1px solid transparent;border-radius:9px;background:transparent;color:var(--muted);font-weight:800;cursor:pointer}

.standings-switch button:hover,.standings-switch button.active{border-color:rgba(67,119,205,.55);background:rgba(23,79,165,.3);color:#fff}

.standings-table{min-width:800px;table-layout:fixed}

.standings-table th:first-child,.standings-table td:first-child{width:54px}

.standings-table th:nth-child(2),.standings-table td:nth-child(2){text-align:left}

.standings-table th:nth-child(n+3),.standings-table td:nth-child(n+3){width:72px;padding-right:12px;padding-left:12px;text-align:center}

.standings-table th:nth-child(3),.standings-table td:nth-child(3){color:var(--gold)}

/* Hero fotografica della Home. */
body[data-page="home"] .hero{min-height:360px;border-color:rgba(255,255,255,.18);background:linear-gradient(90deg,rgba(3,10,25,.97) 0%,rgba(3,10,25,.82) 43%,rgba(3,10,25,.28) 72%,rgba(3,10,25,.12) 100%),url("../assets/images/home-hero.jpg") center/cover no-repeat;box-shadow:inset 0 0 80px rgba(0,0,0,.2)}

.hero{position:relative;isolation:isolate;min-height:390px;align-items:center;overflow:hidden;padding:clamp(30px,5vw,58px);border-color:rgba(111,153,218,.42);border-radius:var(--radius-lg);background:linear-gradient(100deg,rgba(3,12,34,.97) 0,rgba(5,18,43,.88) 43%,rgba(8,29,72,.28) 72%),url("../assets/images/home-hero.jpg") center/cover;box-shadow:var(--shadow-lg)}

.hero-season{justify-self:end;align-self:end;display:grid;min-width:190px;padding:22px;border:1px solid rgba(244,203,105,.32);border-radius:22px;background:rgba(2,11,34,.68);backdrop-filter:blur(12px)}

.hero-season>span{color:var(--gold);font-size:11px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}

.hero-season strong{font-size:55px;line-height:1}

.hero-season strong span{color:var(--gold)}

.hero-season small{margin-top:8px;color:var(--muted)}

.home-dashboard-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(270px,.65fr);gap:18px}

.home-next{padding:22px;border:1px solid var(--line);border-radius:22px;background:rgba(5,22,54,.72)}

.home-next h3{margin:0;color:var(--muted);font-size:12px;letter-spacing:.1em;text-transform:uppercase}

.home-next-head{display:grid;grid-template-columns:minmax(140px,.72fr) minmax(280px,1.55fr);align-items:center;gap:18px;margin-bottom:16px}

.home-matchday-nav{display:flex;grid-column:2;justify-self:center;gap:8px}

.home-matchday-button{padding:9px 13px;border:1px solid rgba(23,79,145,.22);border-radius:999px;background:#174f91;color:#fff;font:800 11px/1 Inter,sans-serif;cursor:pointer;box-shadow:0 5px 14px rgba(23,79,145,.18);transition:transform .18s ease,box-shadow .18s ease,opacity .18s ease}

.home-matchday-button:hover:not(:disabled),.home-matchday-button:focus-visible:not(:disabled){transform:translateY(-1px);box-shadow:0 7px 17px rgba(23,79,145,.26)}

.home-matchday-button:disabled{cursor:default;opacity:.45}

.home-match-score{min-width:42px;color:#173d68;font-size:15px;text-align:center}

.home-match-row.is-finished .home-match-score{font-weight:900}

.home-rail{display:grid;gap:10px}

.home-rail a{display:flex;flex-direction:column;justify-content:center;min-height:126px;padding:18px;border:1px solid var(--line);border-radius:18px;background:linear-gradient(145deg,rgba(18,54,118,.62),rgba(5,22,54,.82));text-decoration:none;transition:.2s ease}

.home-rail a:hover{border-color:var(--gold);transform:translateX(3px)}

.home-rail span{color:var(--gold);font-size:10px;font-weight:900;letter-spacing:.1em;text-transform:uppercase}

.home-rail strong{margin:4px 0;font-size:17px}

.home-rail small{color:var(--muted)}

.editorial-empty{display:grid;grid-template-columns:130px minmax(0,1fr) 250px;gap:30px;align-items:center;min-height:330px;padding:clamp(24px,5vw,54px);border:1px solid var(--line);border-radius:var(--radius-lg);background:radial-gradient(circle at 88% 20%,rgba(244,203,105,.13),transparent 22rem),linear-gradient(135deg,rgba(17,51,111,.72),rgba(4,17,43,.94));box-shadow:var(--shadow-lg)}

.editorial-empty-mark{display:grid;place-items:center;width:112px;height:112px;border:1px solid rgba(244,203,105,.5);border-radius:32px;background:rgba(244,203,105,.08);color:var(--gold);font-family:Georgia,serif;font-size:68px}

.editorial-empty h2{margin-bottom:10px}

.editorial-empty p:not(.eyebrow){max-width:600px;color:var(--muted)}

.editorial-empty ol{margin:0;padding:0;list-style:none}

.editorial-empty li{display:flex;gap:14px;padding:12px 0;border-bottom:1px solid var(--line)}

.editorial-empty li:last-child{border:0}

.editorial-empty li strong{color:var(--gold);font-size:11px}

.editorial-empty li span{font-weight:800}

.standings-table tbody tr:nth-child(-n+4) td:first-child{box-shadow:inset 3px 0 #4e9cff}

.standings-table tbody tr:nth-last-child(-n+3) td:first-child{box-shadow:inset 3px 0 #ff7c7c}

.standings-table tbody tr{transition:background .16s ease}

.standings-table tbody tr:hover td{background:rgba(29,79,164,.3)}

.card,.home-rail a{border-radius:22px}

.home-rail a:hover{border-color:rgba(255,255,255,.22);box-shadow:inset 0 1px rgba(255,255,255,.08),0 22px 56px rgba(0,0,0,.22);transform:translateY(-2px)}

.home-rail a:hover{border-color:rgba(125,190,255,.5);box-shadow:inset 0 1px rgba(178,215,255,.12),0 24px 58px rgba(0,20,68,.3)}

.hero-season{border-color:rgba(167,116,22,.24);background:rgba(255,255,255,.62)}

.hero-season>span,.hero-season strong span,.eyebrow{color:#9a6912}

.home-rail a:hover{
  border-color:rgba(35,93,161,.2);
  box-shadow:inset 0 1px #fff,0 22px 48px rgba(32,49,73,.13);
}

.home-rail a:hover{
  border-color:rgba(40,58,59,.2);
  background:linear-gradient(115deg,rgba(255,255,255,.62),transparent 40%),rgba(181,250,255,.24);
  box-shadow:0 8px 4px #00000012,0 22px 28px #0000000e,inset 0 1px 4px #ffffff8a;
}

.home-next h3{text-transform:none}

.home-next h3>span{text-transform:uppercase}

/* Selettori classifica compatti: link testuali separati da una barra. */
.standings-switch{
  justify-content:flex-start;
  margin:18px 0 10px;
}

.standings-switch-separator{color:rgba(77,95,105,.55);font-weight:700}

/* Home: prossime partite più compatte, senza colonna Lettura. */
.home-next{
  padding:18px 20px;
}

.home-next-head{
  margin-bottom:12px;
}

/* Classifiche ordinabili: le colonne esistenti mantengono la stessa larghezza. */
.standings-table{width:calc(100% + 288px);min-width:1088px}

.standings-sort{display:block;width:100%;padding:0;border:0;background:transparent;color:inherit;font:inherit;font-weight:inherit;letter-spacing:inherit;text-align:inherit;text-transform:inherit;white-space:nowrap;cursor:pointer}

.standings-sort:focus-visible{outline:2px solid var(--gold);outline-offset:3px;border-radius:3px}

.standings-table tbody tr:nth-child(-n+4) td:first-child,.standings-table tbody tr:nth-last-child(-n+3) td:first-child{box-shadow:none}

/* Archivio 2025/26: cambio vista senza scorrimento e colonna ordinata ben riconoscibile. */
.standings-scope-switch{display:flex;align-items:center;justify-content:flex-start;gap:10px;margin:12px 0 10px}

.home-standings [data-standings-scope-panel]{margin-top:0}

.home-standings [data-standings-scope-panel="general"]{padding-top:10px}

.standings-table th.standings-column-active{background:#174f91;color:#fff;box-shadow:inset 1px 0 rgba(255,255,255,.16),inset -1px 0 rgba(255,255,255,.16)}

.standings-table td.standings-column-active{background:rgba(47,117,197,.13);color:#123f70;box-shadow:inset 1px 0 rgba(47,117,197,.12),inset -1px 0 rgba(47,117,197,.12)}

.standings-table tbody tr:hover td.standings-column-active{background:rgba(47,117,197,.22)}

.standings-table tbody tr.standing-zone-champion td:first-child{box-shadow:inset 3px 0 var(--gold)}

.standings-table tbody tr.standing-zone-top td:first-child{box-shadow:inset 3px 0 #4e9cff}

.standings-table tbody tr.standing-zone-europa td:first-child{box-shadow:inset 3px 0 #27d17f}

.standings-table tbody tr.standing-zone-conference td:first-child{box-shadow:inset 3px 0 #f59e0b}

.standings-table tbody tr.standing-zone-bottom td:first-child{box-shadow:inset 3px 0 #dc2626}

/* Mantiene la resa finale della hero dopo la separazione dei moduli. */
body[data-page="home"] .hero{
  border:1px solid rgba(255,255,255,.42);
  box-shadow:0 1px 0 rgba(255,255,255,.78),0 12px 22px rgba(31,39,52,.16),0 34px 64px rgba(31,39,52,.18),inset 0 0 0 1px rgba(2,8,20,.5),inset 0 16px 26px rgba(0,4,14,.42),inset 0 -12px 22px rgba(0,4,14,.3);
}
/* Dentro la stagione: stili confinati al solo dashboard della homepage. */
.home-dashboard .home-dashboard-grid{grid-template-columns:minmax(0,68fr) minmax(0,32fr);gap:18px;align-items:stretch}
.home-dashboard .home-next,.home-dashboard .home-rail a{border:1px solid rgba(255,255,255,.58);border-radius:22px;box-shadow:0 8px 20px rgba(20,43,59,.07),0 22px 48px rgba(20,43,59,.08),inset 0 1px 1px rgba(255,255,255,.5)}
.home-dashboard .home-next{min-width:0;padding:22px 24px 10px;background:#f0f5f8}
.home-dashboard .home-next-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px}
.home-dashboard .home-next h3{color:#142b3b;letter-spacing:0;text-transform:none}
.home-dashboard .home-next h3>span{display:block;margin-bottom:5px;color:#526777;font-size:10px;letter-spacing:.12em}
.home-dashboard .home-next h3>strong{display:block;font-family:Inter,system-ui,sans-serif;font-size:clamp(20px,1.6vw,22px);line-height:1.35;font-weight:700;letter-spacing:normal;white-space:nowrap}
.home-dashboard .home-matchday-nav{display:flex;flex-shrink:0;gap:8px}
.home-dashboard .home-matchday-button{display:grid;place-items:center;width:34px;height:34px;min-height:34px;padding:0;border:1px solid #cbd6dc;border-radius:50%;background:transparent;color:#142b3b;font:500 18px/1 Inter,sans-serif;box-shadow:none;transform:none;transition:background .15s ease}
.home-dashboard .home-matchday-button:hover:not(:disabled){background:#e7edf0;box-shadow:none;transform:none}
.home-dashboard .home-matchday-button:disabled{opacity:.35}
.home-dashboard .home-match-list{border-top:1px solid #dce4e8}
.home-dashboard .home-match-row{grid-template-columns:minmax(110px,.65fr) minmax(0,1.8fr) 34px;gap:14px;padding:12px 0;border-bottom:1px solid #e3e9ed}
.home-dashboard .home-match-row:last-child{border-bottom:0}
.home-dashboard .home-match-meta time{color:#526777;font-size:11px}
.home-dashboard .home-match-teams{gap:8px;min-width:0}
.home-dashboard .home-match-teams .team-name{color:#142b3b;font-size:13px;font-weight:650;white-space:normal;overflow:visible;text-overflow:clip;line-height:1.3;overflow-wrap:anywhere}
.home-dashboard .home-match-teams .team-logo{width:28px;height:28px;flex-basis:28px}
.home-dashboard .home-match-teams .home-match-score{color:#142b3b;font-size:14px;font-variant-numeric:tabular-nums}
.home-dashboard .home-match-row:has(a):hover{background:#edf2f4}
.home-dashboard .home-rail{grid-template-columns:1fr;grid-template-rows:repeat(2,minmax(0,1fr));gap:18px;min-width:0}
.home-dashboard .home-rail a{position:relative;display:flex;justify-content:flex-end;align-items:flex-start;min-height:210px;min-width:0;padding:26px 26px 54px;overflow:hidden;transform:none;cursor:pointer;transition:transform .2s ease,box-shadow .2s ease}
.home-dashboard .home-rail .home-editorial-readings{background:#122938;color:#fff;border-color:rgba(255,255,255,.18);box-shadow:0 8px 20px rgba(8,22,37,.12),0 22px 48px rgba(8,22,37,.14),inset 0 1px 1px rgba(255,255,255,.08)}
.home-dashboard .home-rail .home-editorial-teams{background:#dce8e3;color:#142b3b}
/* Solid surfaces above are the fallback; translucent layers require blur support. */
@supports ((backdrop-filter:blur(14px)) or (-webkit-backdrop-filter:blur(14px))){
 .home-dashboard .home-next,.home-dashboard .home-rail a{backdrop-filter:blur(14px) saturate(135%);-webkit-backdrop-filter:blur(14px) saturate(135%)}
 .home-dashboard .home-next{background:linear-gradient(115deg,rgba(255,255,255,.3),rgba(255,255,255,0) 48%),rgba(232,241,247,.84)}
 .home-dashboard .home-rail .home-editorial-teams{background:linear-gradient(115deg,rgba(255,255,255,.28),rgba(255,255,255,0) 48%),rgba(210,229,219,.84)}
 .home-dashboard .home-rail .home-editorial-readings{background:linear-gradient(135deg,rgba(64,87,111,.18),rgba(6,20,36,.16)),rgba(12,30,47,.91)}
}
.home-dashboard .home-rail a>span{position:absolute;top:24px;left:26px;color:#d4a43b;font-size:10px;font-weight:800;letter-spacing:.16em}
.home-dashboard .home-rail .home-editorial-teams>span{color:#245a55}
.home-dashboard .home-rail strong{max-width:100%;margin:16px 0 7px;color:inherit;font-size:clamp(23px,2.4vw,32px);line-height:1.1;letter-spacing:-.04em}
.home-dashboard .home-rail small{color:inherit;font-size:13px;opacity:.85}
.home-dashboard .home-editorial-icon{width:52px;height:52px;margin-top:28px;color:#d4a43b}
.home-dashboard .home-editorial-teams .home-editorial-icon{color:#245a55}
.home-dashboard .home-editorial-arrow{position:absolute;right:24px;bottom:22px;width:25px;height:25px}
.home-dashboard .home-rail a:hover{transform:translateY(-2px);box-shadow:0 10px 24px rgba(20,43,59,.1),0 26px 52px rgba(20,43,59,.12),inset 0 1px 1px rgba(255,255,255,.32)}
.home-dashboard .home-rail .home-editorial-readings:hover{box-shadow:0 10px 24px rgba(8,22,37,.15),0 26px 52px rgba(8,22,37,.18),inset 0 1px 1px rgba(255,255,255,.08)}
.home-dashboard :is(a,button):focus-visible{outline:3px solid #b2811d;outline-offset:4px}
@media(max-width:1000px){
 .home-dashboard .home-dashboard-grid{grid-template-columns:1fr}
 .home-dashboard .home-rail{grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:auto}
 .home-dashboard .home-rail a{min-height:240px}
}
@media(max-width:580px){
 .home-dashboard .home-dashboard-grid,.home-dashboard .home-rail{gap:12px}
 .home-dashboard .home-next{padding:18px 14px 6px}
 .home-dashboard .home-next h3>strong{font-size:20px}
 .home-dashboard .home-match-row{grid-template-columns:minmax(0,1fr) 34px;gap:7px 8px;padding:10px 0}
 .home-dashboard .home-match-meta{grid-column:1}
 .home-dashboard .home-match-teams{grid-column:1}
 .home-dashboard .home-match-reading,.home-dashboard .home-match-reading-placeholder{grid-column:2;grid-row:1 / span 2}
 .home-dashboard .home-match-meta time{font-size:11px}
 .home-dashboard .home-match-teams .team-name{font-size:12px}
 .home-dashboard .home-rail a{padding:18px 16px 46px;min-height:230px;border-radius:22px}
 .home-dashboard .home-rail a>span{top:18px;left:16px;font-size:9px}
 .home-dashboard .home-rail strong{font-size:23px}
 .home-dashboard .home-rail small{font-size:12px}
 .home-dashboard .home-editorial-icon{width:38px;height:38px;margin-top:26px}
 .home-dashboard .home-editorial-arrow{right:16px;bottom:16px;width:22px;height:22px}
}
@media(max-width:350px){.home-dashboard .home-rail{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){.home-dashboard .home-rail a,.home-dashboard .home-matchday-button{transition:none}}

/* Colonna Lettura sempre visibile, anche senza hover e su touch. */
.home-dashboard .home-match-row>.home-match-reading{display:grid;place-items:center;align-self:center;width:34px;min-height:44px;color:#245a55;font-size:20px;font-weight:500;line-height:1;text-decoration:none;opacity:1;visibility:visible}
.home-dashboard .home-match-reading:hover{color:#142b3b}
.home-dashboard .home-match-reading-placeholder{width:34px}
.home-dashboard .home-matchday-button::before,.home-dashboard .home-matchday-button::after{content:none}
@media(prefers-reduced-motion:reduce){.home-dashboard .home-rail a:hover{transform:none}}
.home-dashboard .home-match-reading>span{margin:0;color:inherit}
.home-dashboard .home-match-reading>svg{display:block;width:20px;height:20px;opacity:1;visibility:visible}
.home-dashboard .home-matchday-button>svg{display:block;width:18px;height:18px}
.home-dashboard [data-home-previous-matchday]>svg{transform:rotate(180deg)}

/* Solo intestazione della classifica in homepage. */
.home-standings>.section-heading{margin-bottom:18px}
.home-standings>.section-heading .eyebrow{margin:0 0 10px}
.home-standings>.section-heading h2{font-size:clamp(24px,2.6vw,34px);line-height:1.18}
.home-standings>.standings-switch{margin:0 0 10px}
.home-standings .standings-scope-switch{margin:0 0 14px}

/* Ripristino della densita del calendario precedente al restyling.
   La griglia mobile conserva il target Lettura da 44px sulle due righe. */
.home-dashboard .home-next{padding-top:18px}
.home-dashboard .home-next-head{margin-bottom:12px}
@media(min-width:761px){
 .home-dashboard .home-match-row>.home-match-reading{min-height:28px}
}
/* Compact desktop calendar: preserve text sizes and mobile touch targets. */
@media(min-width:761px){
 .home-dashboard .home-match-row{padding-block:10px}
 body[data-page="home"] .hero{min-height:320px}
}

css/layout.css:
/* layout.css - modulo del sistema grafico condiviso. */
.site-header{position:sticky;top:0;z-index:20;display:flex;align-items:center;gap:24px;padding:16px max(20px,calc((100vw - var(--max))/2));border-bottom:1px solid var(--line);background:rgba(7,17,15,.94);backdrop-filter:blur(14px)}

.brand{display:flex;align-items:center;gap:11px;text-decoration:none;white-space:nowrap}

.brand-mark{display:grid;place-items:center;width:42px;height:42px;border-radius:13px;background:linear-gradient(145deg,var(--accent),#087845);color:#03150d;font-size:24px;font-weight:950}

.brand strong,.brand small{display:block}

.brand small{color:var(--muted);font-size:11px}

.site-nav{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:3px;margin-left:auto}

.page-link{padding:8px 9px;border-radius:7px;color:var(--muted);font-size:13px;text-decoration:none}

.page-link:hover,.page-link.active{background:var(--surface2);color:var(--text)}

.menu-button{display:none;margin-left:auto;padding:9px 13px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--text)}

main{width:min(var(--max),calc(100% - 40px));min-height:75vh;margin:auto;padding:54px 0 80px}

.hero{display:grid;grid-template-columns:1.5fr .7fr;gap:28px;align-items:end;padding:36px;border:1px solid var(--line);border-radius:24px;background:linear-gradient(135deg,rgba(39,209,127,.12),rgba(16,27,24,.95))}

.hero-stat strong{display:block;font-size:46px}

.hero-stat span,.muted{color:var(--muted)}

.section{margin-top:48px}

.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}

.hero{border-color:#365b98;background:linear-gradient(135deg,rgba(23,79,165,.7),rgba(8,29,72,.96) 55%,rgba(181,126,27,.2));box-shadow:inset 0 1px rgba(255,255,255,.08),0 24px 70px rgba(0,8,35,.24)}

body[data-page="home"] .hero .lead{color:#eef3f7;text-shadow:0 2px 14px rgba(0,0,0,.65)}

main{padding-top:44px}

.hero::after{content:"";position:absolute;z-index:-1;inset:0;background:linear-gradient(180deg,transparent 50%,rgba(0,7,28,.4)),radial-gradient(circle at 88% 18%,rgba(244,203,105,.18),transparent 28%)}

.hero h1{max-width:760px;font-size:clamp(44px,6.4vw,82px);letter-spacing:-.055em;text-wrap:balance}

.hero .lead{max-width:690px;margin-bottom:0;color:#e0e8f5;font-size:clamp(16px,1.6vw,20px)}

.section{margin-top:72px}

.section-heading{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:22px}

.section-heading h2{margin:0}

/* La hero fotografica appartiene solo alla home. */
body:not([data-page="home"]) .hero{display:flex;min-height:0;padding:32px 0 28px;overflow:visible;border:0;border-bottom:1px solid var(--line);border-radius:0;background:none;box-shadow:none}

body:not([data-page="home"]) .hero::after{display:none}

body:not([data-page="home"]) .hero>div:first-child{width:100%}

body:not([data-page="home"]) .hero h1{max-width:920px;font-size:clamp(40px,5vw,68px)}

body:not([data-page="home"]) .hero .lead{max-width:780px;color:var(--muted);font-size:16px}

body:not([data-page="home"]) .hero-stat{display:flex;align-items:baseline;gap:10px;margin-left:auto;padding-left:32px}

body:not([data-page="home"]) .hero-stat strong{font-size:38px}

main{padding-top:38px}

.hero{border-color:rgba(255,255,255,.14);border-radius:34px;box-shadow:0 34px 90px rgba(0,0,0,.32),inset 0 1px rgba(255,255,255,.09)}

.hero h1{font-weight:720;letter-spacing:-.065em}

.hero .lead{font-weight:430;line-height:1.48}

body:not([data-page="home"]) .hero{padding:40px 4px 30px;border-bottom-color:rgba(255,255,255,.1)}

body:not([data-page="home"]) .hero h1{font-weight:710;letter-spacing:-.055em}

.section{margin-top:82px}

.section-heading{margin-bottom:26px}

.hero{border-color:rgba(119,178,248,.27);background:radial-gradient(circle at 86% 12%,rgba(59,133,231,.26),transparent 25rem),linear-gradient(145deg,rgba(16,67,139,.82),rgba(5,34,80,.92));box-shadow:0 34px 90px rgba(0,17,57,.34),inset 0 1px rgba(157,201,255,.12)}

body[data-page="home"] .hero h1{color:#fff}

.hero{
  border-color:rgba(255,255,255,.86);
  background:
    radial-gradient(circle at 86% 12%,rgba(28,99,183,.1),transparent 25rem),
    linear-gradient(145deg,rgba(255,255,255,.9),rgba(247,249,252,.72));
  box-shadow:0 30px 70px rgba(30,47,70,.12),inset 0 1px #fff;
}

.hero .lead{color:#566276}

.hero-stat span,.muted{color:var(--muted)}

/* Navbar condivisa: unica definizione per tutte le pagine */
.site-header{
  --glass-color:#b5faff31;
  --glass-text:#283a3b;
  isolation:isolate;
  top:12px;
  align-items:center;
  gap:24px;
  width:var(--container-width);
  min-height:68px;
  margin:12px auto 0;
  padding:9px 12px;
  overflow:visible;
  border:1px solid #00000015;
  border-radius:999px;
  background:linear-gradient(115deg,rgba(255,255,255,.38),transparent 34%),linear-gradient(295deg,rgba(255,255,255,.16),transparent 48%),var(--glass-color);
  box-shadow:0 6px 2px #00000020,0 14px 8px #00000016,0 32px 22px #00000013,0 56px 36px #0000000d,inset 0 1px 4px 1px #ffffff70;
  backdrop-filter:blur(22px) saturate(135%);
  -webkit-backdrop-filter:blur(22px) saturate(135%);
}

.site-header::after{
  content:"";
  position:absolute;
  z-index:-1;
  left:8%;
  right:8%;
  bottom:-28px;
  height:30px;
  border-radius:50%;
  background:#0000001c;
  filter:blur(20px);
  pointer-events:none;
}

.site-header>.brand,.site-header>.menu-button,.site-header>.site-nav{position:relative;z-index:1}

.brand{gap:10px}

.brand-mark{width:44px;height:44px;border:0;background:transparent;box-shadow:none}

.brand-mark img{display:block;width:100%;height:100%;object-fit:contain;filter:none}

.brand strong{color:var(--glass-text);font-size:13px;font-weight:650;letter-spacing:-.01em}

.brand small{margin-top:2px;color:var(--glass-text);font-size:9px;font-weight:600;letter-spacing:.02em;text-transform:uppercase}

.site-nav{gap:2px}

.page-link{
  position:relative;
  padding:9px 11px;
  border:1px solid transparent;
  border-radius:12px;
  background:transparent;
  color:var(--glass-text);
  font-size:12px;
  font-weight:580;
  letter-spacing:-.01em;
  text-shadow:none;
  transform:none;
  transition:background-color .2s ease,border-color .2s ease,box-shadow .2s ease;
}

.page-link.active{
  border-color:#ffffff52;
  background:rgba(255,255,255,.22);
  color:var(--glass-text);
  box-shadow:inset 0 1px 3px #fff8;
}

.page-link:focus-visible{
  border-color:rgba(40,58,59,.3);
  background:rgba(255,255,255,.34);
  color:var(--glass-text);
  box-shadow:0 0 0 2px rgba(255,255,255,.7);
  outline:none;
}

.menu-button{border-color:#00000015;background:rgba(255,255,255,.2);color:var(--glass-text);box-shadow:inset 0 1px 3px #fff8}

body[data-page="home"] .hero h1,
body[data-page="home"] .hero .lead{color:#fff}

/* Home hero: foto incassata sotto un vetro protettivo. */
body[data-page="home"] .hero{
  border:1px solid rgba(255,255,255,.42);
  box-shadow:
    0 1px 0 rgba(255,255,255,.78),
    0 12px 22px rgba(31,39,52,.16),
    0 34px 64px rgba(31,39,52,.18),
    inset 0 0 0 1px rgba(2,8,20,.5),
    inset 0 16px 26px rgba(0,4,14,.42),
    inset 0 -12px 22px rgba(0,4,14,.3);
}

body[data-page="home"] .hero::before{
  content:"";
  position:absolute;
  z-index:0;
  inset:0;
  border-radius:inherit;
  background:
    linear-gradient(118deg,rgba(255,255,255,.2) 0%,rgba(255,255,255,.07) 14%,transparent 31%),
    linear-gradient(180deg,rgba(255,255,255,.1),transparent 18%,transparent 78%,rgba(0,0,0,.12));
  box-shadow:
    inset 0 0 0 5px rgba(2,8,20,.16),
    inset 0 0 0 6px rgba(255,255,255,.12);
  pointer-events:none;
}

body[data-page="home"] .hero::after{
  z-index:0;
  background:
    linear-gradient(180deg,rgba(255,255,255,.05),transparent 23%,transparent 72%,rgba(0,4,14,.34)),
    radial-gradient(ellipse at 82% 4%,rgba(255,255,255,.17),transparent 33%),
    radial-gradient(circle at 88% 18%,rgba(244,203,105,.14),transparent 28%);
  pointer-events:none;
}

body[data-page="home"] .hero>*{
  position:relative;
  z-index:1;
}

/* Evita il flash del template provvisorio mentre JavaScript carica i JSON.
   La sezione resta nel flusso per mantenere stabile l'altezza; gli stati di
   errore che la sostituiscono continuano invece a essere visibili. */
main > .loading{
  visibility:hidden;
}

/* Footer condiviso */
.site-footer{position:relative;isolation:isolate;margin-top:40px;padding:0;overflow:hidden;border-top:1px solid rgba(244,207,114,.42);background:radial-gradient(circle at 12% -20%,rgba(44,112,202,.5),transparent 28rem),radial-gradient(circle at 88% 120%,rgba(180,126,30,.2),transparent 24rem),linear-gradient(145deg,#071d49,#03112f 72%);color:#dce7f7;text-align:left;font-size:14px}

.site-footer::before{content:"";position:absolute;z-index:-1;inset:0 0 auto;height:1px;background:linear-gradient(90deg,transparent,var(--gold),transparent)}

.site-footer-inner{width:min(var(--max),calc(100% - 40px));margin:auto;padding:54px 0 24px}

.site-footer-top{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(360px,.85fr);gap:clamp(48px,8vw,110px);align-items:start;padding-bottom:44px}

.site-footer-intro{max-width:540px}

.footer-brand{display:inline-flex;align-items:center;gap:13px;color:#fff;text-decoration:none}

.footer-brand-mark{display:grid;place-items:center;width:50px;height:50px;padding:7px;border:1px solid rgba(255,255,255,.18);border-radius:16px;background:rgba(255,255,255,.94);box-shadow:0 12px 30px rgba(0,5,22,.24)}

.footer-brand-mark img{display:block;width:100%;height:100%;object-fit:contain}

.footer-brand strong,.footer-brand small{display:block;color:inherit}

.footer-brand strong{font-size:17px;letter-spacing:-.01em}

.footer-brand small{margin-top:1px;color:#9fb3d2;font-size:11px}

.site-footer-intro>p{max-width:480px;margin:22px 0 18px;color:#adbed7;font-size:15px;line-height:1.7}

.footer-season{display:inline-flex;align-items:center;gap:8px;padding:7px 11px;border:1px solid rgba(244,207,114,.24);border-radius:999px;background:rgba(244,207,114,.08);color:#f7d98e;font-size:11px;font-weight:850;letter-spacing:.07em;text-transform:uppercase}

.footer-season::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--gold);box-shadow:0 0 0 4px rgba(244,207,114,.1)}

.footer-nav{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:36px}

.footer-nav>div{display:grid;align-content:start;gap:10px}

.footer-nav strong{margin-bottom:5px;color:#f7d98e;font-size:11px;letter-spacing:.11em;text-transform:uppercase}

.footer-nav a{width:max-content;max-width:100%;color:#dce7f7;text-decoration:none;transition:color .18s ease,transform .18s ease}

.footer-nav a:hover,.footer-nav a:focus-visible{color:#fff;transform:translateX(3px)}

.site-footer-bottom{display:flex;align-items:center;justify-content:space-between;gap:24px;padding-top:22px;border-top:1px solid rgba(255,255,255,.11);color:#8fa4c3;font-size:12px}

.site-footer-bottom p{margin:0}

.site-footer-bottom>a{display:inline-flex;align-items:center;gap:7px;flex:none;padding:8px 11px;border:1px solid rgba(255,255,255,.13);border-radius:999px;color:#dce7f7;text-decoration:none}

.site-footer-bottom>a:hover,.site-footer-bottom>a:focus-visible{border-color:rgba(244,207,114,.42);color:#fff}
/* Il solo glass della navbar nelle due pagine interessate. */
body:is([data-page="home"],[data-page="team-stats"]) .site-header{
 background:var(--glass-light-bg);border-color:var(--glass-light-border);
 box-shadow:var(--glass-shadow);color:var(--glass-light-text);
 backdrop-filter:var(--glass-blur);-webkit-backdrop-filter:var(--glass-blur);
}
/* Shared outer alignment; specialised layouts retain their internal grids. */
:is(.site-header,main,.site-footer-inner){width:var(--container-width)}
body[data-page="home"] main{padding-top:24px;padding-bottom:48px}
body[data-page="home"] main>.section{margin-top:48px}
body[data-page="home"] main>.section>.section-heading{margin-bottom:20px}
body[data-page="home"] .site-footer{margin-top:24px}

css/matches.css:
/* matches.css - modulo del sistema grafico condiviso. */
.match{display:grid;grid-template-columns:150px 1fr auto;gap:18px;align-items:center;margin-bottom:10px}

.match-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}

.match-date{max-width:60%;color:#c9d7d2;font-size:12px;text-align:right}

.fixture-teams{display:grid;gap:5px}

.fixture-score{display:grid;grid-template-columns:1fr auto 1fr;gap:10px;align-items:center;color:var(--gold)}

.fixture-score span{height:1px;background:var(--line)}

.fixture-score .score{min-width:35px;font-size:12px;letter-spacing:.08em;text-align:center}

.match .actions{margin-top:auto;padding-top:12px;border-top:1px solid var(--line)}

.match .button{background:rgba(255,255,255,.025)}

/* Card partita moderna e identica in ogni calendario. */
.match.fixture-card{position:relative;display:flex;flex-direction:column;align-items:stretch;gap:0;min-width:0;margin:0;padding:0;overflow:hidden;border:1px solid rgba(72,112,176,.48);border-radius:18px;background:linear-gradient(155deg,rgba(19,39,70,.96),rgba(8,24,43,.98));box-shadow:0 12px 30px rgba(0,8,28,.24);transition:border-color .2s ease,transform .2s ease,box-shadow .2s ease}

.match.fixture-card:hover{border-color:rgba(242,193,78,.72);transform:translateY(-2px);box-shadow:0 17px 38px rgba(0,8,28,.34)}

.match.fixture-card::before{display:none}

.match.fixture-card .match-head{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;width:100%;gap:12px;padding:14px 16px;border-bottom:1px solid rgba(88,126,181,.28);background:rgba(9,25,51,.66)}

.match-badges{display:flex;align-items:center;flex-wrap:wrap;gap:6px}

.matchday-chip{display:inline-flex;align-items:center;padding:4px 9px;border:1px solid rgba(242,193,78,.38);border-radius:999px;background:rgba(242,193,78,.1);color:#ffe29a;font-size:10px;font-weight:900;letter-spacing:.06em;text-transform:uppercase}

.match.fixture-card .status{padding:4px 9px;background:rgba(65,116,202,.2);color:#bad2ff;font-size:10px}

.match.fixture-card .match-date{max-width:260px;color:#d5dfef;font-size:12px;line-height:1.35;text-align:right}

.match.fixture-card .fixture-teams{display:grid;width:100%;gap:9px;padding:16px}

.match.fixture-card .fixture-score{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:12px;padding:0 5px}

.match.fixture-card .fixture-score span{height:1px;background:linear-gradient(90deg,transparent,rgba(100,145,213,.55))}

.match.fixture-card .fixture-score span:last-child{background:linear-gradient(90deg,rgba(100,145,213,.55),transparent)}

.match.fixture-card .fixture-score .score{display:grid;place-items:center;min-width:34px;height:25px;border:1px solid rgba(242,193,78,.32);border-radius:999px;background:rgba(242,193,78,.08);color:var(--gold);font-size:10px;letter-spacing:.08em}

.match.fixture-card>.muted{padding:0 16px 12px}

.match.fixture-card .actions{display:flex;width:100%;gap:8px;margin-top:auto;padding:12px 16px;border-top:1px solid rgba(88,126,181,.24);background:rgba(5,17,37,.42)}

.match.fixture-card .button{padding:7px 12px;border-color:rgba(92,133,195,.38);border-radius:999px;background:rgba(65,116,202,.08);color:#dfe9fa}

.match.fixture-card .button:hover{border-color:var(--gold);background:rgba(242,193,78,.1);color:#fff}

.fixture-card-link{text-decoration:none}

.fixture-card-link:focus-visible{outline:3px solid var(--glass-blue);outline-offset:4px}

/* Confronto visivo: stemmi grandi, club contrapposti e area eventi predisposta. */
.match.fixture-card .fixture-teams{position:relative;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:center;column-gap:82px;padding:24px 20px 10px}

.match.fixture-card .fixture-score{position:absolute;left:50%;top:50%;display:grid;grid-template-columns:1fr;place-items:center;width:max-content;padding:0;transform:translate(-50%,-50%)}

.match.fixture-card .fixture-score .score{min-width:46px;height:46px;padding:0 10px;border-color:rgba(242,193,78,.48);background:rgba(242,193,78,.11);font-size:13px;font-weight:950}

.match.fixture-card .fixture-score .score-versus{width:auto;height:auto;min-width:0;padding:0;border:0;border-radius:0;background:transparent;color:var(--glass-muted);font-size:13px;font-weight:800;letter-spacing:.08em;text-transform:lowercase}

.match.fixture-card .match-events{display:grid;grid-template-columns:1fr 1fr;gap:0;margin:0 16px 14px;border:1px solid rgba(88,126,181,.24);border-radius:10px;background:rgba(5,17,37,.28)}

.match.fixture-card .match-events>div{min-width:0;padding:8px 10px}

.match.fixture-card .match-events>div+div{border-left:1px solid rgba(88,126,181,.24)}

.match.fixture-card .match-events span,.match.fixture-card .match-events small{display:block}

.match.fixture-card .match-events span{margin-bottom:2px;color:#8fa9cf;font-size:9px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}

.match.fixture-card .match-events small{min-height:17px;overflow-wrap:anywhere;color:#cbd8ea;font-size:11px}

.match.fixture-card .fixture-official{display:flex;align-items:center;justify-content:center;gap:7px;margin:0;padding:10px 16px;border-top:1px solid rgba(88,126,181,.24);background:rgba(5,17,37,.3);font-size:11px}

.match.fixture-card .fixture-official span{color:#8fa9cf;font-size:9px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}

.match.fixture-card .fixture-official strong{color:#eef5ff;font-size:12px}

/* Le due metà della card riprendono i doppi colori dei club, con taglio centrale diagonale. */
.match.fixture-card{isolation:isolate;border-color:rgba(190,215,255,.34);background:linear-gradient(145deg,rgba(20,42,76,.7),rgba(4,17,38,.62));box-shadow:0 16px 38px rgba(0,8,28,.3),inset 0 1px 0 rgba(255,255,255,.16),inset 0 -1px 0 rgba(255,255,255,.04);backdrop-filter:blur(14px) saturate(125%)}

.match.fixture-card::before,.match.fixture-card::after{content:"";position:absolute;inset:0;display:block;width:100%;z-index:0;pointer-events:none;opacity:.56}

.match.fixture-card::before{background:linear-gradient(145deg,var(--home-color-1),var(--home-color-2));-webkit-mask-image:linear-gradient(100deg,#000 0,#000 43%,transparent 58%);mask-image:linear-gradient(100deg,#000 0,#000 43%,transparent 58%)}

.match.fixture-card::after{background:linear-gradient(145deg,var(--away-color-1),var(--away-color-2));-webkit-mask-image:linear-gradient(100deg,transparent 42%,#000 57%,#000 100%);mask-image:linear-gradient(100deg,transparent 42%,#000 57%,#000 100%)}

.match.fixture-card>*{position:relative;z-index:1}

.match.fixture-card .match-head,.match.fixture-card .actions{background:linear-gradient(100deg,rgba(5,17,37,.5),rgba(12,30,57,.34));backdrop-filter:blur(11px) saturate(130%)}

.match.fixture-card .match-events{border-color:rgba(190,215,255,.2);background:rgba(7,20,43,.38);box-shadow:inset 0 1px 0 rgba(255,255,255,.07);backdrop-filter:blur(12px) saturate(125%)}

/* Organico arbitri CAN. */
.referee-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}

.referee-card{display:grid;grid-template-columns:38px minmax(0,1fr) auto;align-items:center;gap:14px;padding:17px 18px}

.referee-number{display:grid;place-items:center;width:34px;height:34px;border:1px solid rgba(242,193,78,.38);border-radius:50%;background:rgba(242,193,78,.08);color:var(--gold);font-size:12px;font-weight:900}

.referee-card h3{margin:0;font-size:16px}

.referee-card p{margin:2px 0 0;color:var(--muted);font-size:13px}

.referee-card .status{white-space:nowrap}

.referee-note{margin:18px 0 0;color:var(--muted);font-size:13px}

.referee-stats-table{min-width:920px}

.referee-stats-table th:first-child,.referee-stats-table td:first-child{text-align:left}

.referee-nav{position:sticky;top:85px;z-index:10;display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:22px 0 8px;padding:9px;border:1px solid var(--line);border-radius:16px;background:rgba(8,24,43,.94);backdrop-filter:blur(12px)}

.referee-nav a{display:grid;grid-template-columns:38px 1fr;align-items:center;gap:9px;padding:10px 12px;border:1px solid transparent;border-radius:11px;color:#e3ebf7;text-decoration:none}

.referee-nav a:hover{border-color:rgba(242,193,78,.48);background:rgba(242,193,78,.1)}

.referee-nav strong{display:grid;place-items:center;width:34px;height:34px;border-radius:9px;background:rgba(23,79,165,.35);color:var(--gold)}

.referee-nav span{font-size:13px;font-weight:800}

.referee-section{scroll-margin-top:175px}

.pilot-referee-table{min-width:1180px}

.referee-nav{grid-template-columns:repeat(4,1fr)}

.referee-section details{margin-top:1rem;border:1px solid var(--line);border-radius:16px;background:var(--surface);overflow:hidden}

.referee-section summary{cursor:pointer;padding:1rem 1.2rem;font-weight:800}

.referee-section details[open] summary{border-bottom:1px solid var(--line)}

.home-match-list{margin:0;padding:0;list-style:none;border-top:1px solid var(--line)}

.home-match-row{display:grid;grid-template-columns:minmax(150px,.8fr) minmax(280px,1.5fr) auto;align-items:center;gap:18px;padding:15px 2px;border-bottom:1px solid var(--line)}

.home-match-meta{display:flex;flex-direction:column;gap:3px}

.home-match-meta span{color:var(--gold);font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}

.home-match-meta time{color:var(--muted);font-size:12px;line-height:1.35}

.home-match-teams{display:grid;grid-template-columns:minmax(0,1fr) minmax(42px,auto) minmax(0,1fr);align-items:center;gap:8px}

.home-match-teams>b{text-align:center;color:var(--muted);font-weight:500}

.home-match-row>a{color:var(--text);font-size:12px;font-weight:800;text-decoration:none;white-space:nowrap}

.home-match-row>a span{margin-left:5px;color:var(--gold)}

.home-match-row>a:hover{color:var(--gold)}

.cup-stage{padding:26px;border:1px solid rgba(244,203,105,.28);border-radius:var(--radius-lg);background:linear-gradient(145deg,rgba(80,45,7,.16),rgba(5,20,50,.74))}

.cup-badge{padding:6px 10px;border:1px solid rgba(244,203,105,.34);border-radius:999px;color:var(--gold);font-size:11px;font-weight:900;text-transform:uppercase}

.cup-match-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}

/* Seconda fase: ricerca, ordinamento e indicatori comparativi */
.referee-controls{position:sticky;z-index:9;top:92px;display:grid;grid-template-columns:minmax(240px,1fr) minmax(180px,.45fr) auto;gap:12px;align-items:end;max-width:var(--max);margin:0 auto 18px;padding:14px 16px;border:1px solid var(--line-strong);border-radius:18px;background:rgba(4,18,46,.94);box-shadow:0 14px 38px rgba(0,5,24,.34);backdrop-filter:blur(18px)}

.referee-controls label>span{display:block;margin-bottom:5px;color:var(--muted);font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}

.referee-controls input,.referee-controls select{width:100%;height:42px;padding:0 12px;border:1px solid var(--line);border-radius:11px;background:#0a2557;color:var(--text);font:inherit}

.referee-controls input::placeholder{color:#8fa5c7}

.referee-controls>strong{align-self:center;min-width:92px;color:var(--gold);font-size:12px;text-align:right}

.referee-controls{position:static;margin:18px 0}

.referee-card{min-width:0}

.referee-card h3,.referee-card p{overflow:hidden;text-overflow:ellipsis}

.referee-controls{grid-template-columns:1fr}

.match.fixture-card{border-color:rgba(255,255,255,.1);border-radius:24px;background:linear-gradient(155deg,rgba(255,255,255,.07),rgba(255,255,255,.025));box-shadow:inset 0 1px rgba(255,255,255,.055),0 18px 48px rgba(0,0,0,.2)}

.match.fixture-card:hover{border-color:rgba(255,255,255,.22);box-shadow:inset 0 1px rgba(255,255,255,.08),0 24px 58px rgba(0,0,0,.25)}

.match.fixture-card .match-head{background:rgba(3,8,18,.34)}

.match.fixture-card{border-color:rgba(110,172,245,.25);background:linear-gradient(155deg,rgba(20,72,144,.74),rgba(6,34,79,.86));box-shadow:inset 0 1px rgba(160,203,255,.09),0 18px 48px rgba(0,17,57,.27)}

.match.fixture-card .match-head{background:rgba(3,27,66,.5)}

/* Coppa Italia · tabellone vuoto */
body[data-page="cup"]{
  --cup-line:rgba(132,167,224,.58);
  --cup-glass-strong:rgba(5,21,52,.97);
}

.cup-stage{position:relative}

.cup-stage-heading{align-items:end}

.cup-stage-heading>div>p:last-child{
  max-width:670px;
  margin:8px 0 0;
  color:var(--muted);
}

.cup-badge{
  display:inline-flex;
  align-items:center;
  gap:9px;
  padding:8px 13px;
  border:1px solid rgba(242,193,78,.34);
  border-radius:999px;
  background:rgba(242,193,78,.08);
  color:#f8d77f;
  font-size:12px;
  font-weight:850;
  letter-spacing:.04em;
  white-space:nowrap;
}

.cup-badge i{
  width:9px;
  height:9px;
  border-radius:50%;
  background:linear-gradient(90deg,#279d64 0 33%,#fff 33% 66%,#db4056 66%);
  box-shadow:0 0 0 3px rgba(255,255,255,.08);
}

body[data-page="cup"] .cup-badge{
  border-color:rgba(242,193,78,.34);
  background:rgba(242,193,78,.08);
  color:#805b16;
}

.cup-stage-note{
  display:flex;
  align-items:baseline;
  gap:15px;
  margin-top:14px;
  padding:0 5px;
  color:var(--muted);
  font-size:12px;
}

.cup-stage-note span{
  color:#38546a;
  font-size:10px;
  font-weight:900;
  letter-spacing:.09em;
  text-transform:uppercase;
  white-space:nowrap;
}

.cup-stage-note p{margin:0}

.cup-stage-note a{color:#385d78;font-weight:800}

.cup-stage-note a:hover{text-decoration:none}

.match.fixture-card{
  border-color:rgba(255,255,255,.9);
  background:linear-gradient(155deg,rgba(255,255,255,.92),rgba(248,250,253,.68));
  box-shadow:inset 0 1px #fff,0 18px 44px rgba(30,47,70,.1);
}

.match.fixture-card .match-head,.match.fixture-card .actions{background:rgba(20,89,166,.045)}

.match.fixture-card .match-events{border-color:rgba(18,64,119,.1);background:rgba(255,255,255,.56)}

body[data-page="referees"] .referee-nav a{color:var(--glass-text)}

body[data-page="referees"] .referee-nav span{color:var(--glass-text)}

body[data-page="referees"] .referee-nav strong{background:rgba(36,90,120,.2);color:var(--glass-gold)}

body[data-page="referees"] .referee-nav a:hover,
body[data-page="referees"] .referee-nav a:focus-visible{border-color:rgba(36,90,120,.28);background:rgba(255,255,255,.46)}

.match.fixture-card{
  border-color:var(--glass-border);
  background:linear-gradient(115deg,rgba(255,255,255,.5),transparent 40%),var(--glass-surface);
  color:var(--glass-text);
