}

.match.fixture-card .match-head,.match.fixture-card .actions,.match.fixture-card .match-events{background:rgba(255,255,255,.3);color:var(--glass-text)}

.competition-chip,.matchday-chip,.cup-badge{border-color:rgba(36,90,120,.2);background:rgba(36,90,120,.08);color:var(--glass-blue)}

/* Card giornate: stessa superficie in vetro delle card Statistiche squadre */
.match.fixture-card,
.readings-index .ri-glass{
  border-color:#00000015;
  background:
    radial-gradient(circle at 12% 28%,color-mix(in srgb,var(--home-color-1) 10%,transparent),transparent 44%),
    radial-gradient(circle at 88% 72%,color-mix(in srgb,var(--away-color-1) 10%,transparent),transparent 44%),
    linear-gradient(115deg,rgba(255,255,255,.46),transparent 34%),
    linear-gradient(295deg,rgba(255,255,255,.18),transparent 50%),
    #b5faff31;
  box-shadow:
    0 6px 2px #00000012,
    0 14px 12px #0000000d,
    0 28px 28px #0000000a,
    inset 0 1px 4px 1px #ffffff78;
  backdrop-filter:blur(22px) saturate(135%);
  -webkit-backdrop-filter:blur(22px) saturate(135%);
}

.match.fixture-card::before,
.match.fixture-card::after{display:none}

/* Card calendario chiare: contrasto esplicito per ogni livello informativo. */
.match.fixture-card .match-head{
  border-bottom-color:rgba(34,67,76,.15);
  color:#24373c;
}

.match.fixture-card .matchday-chip{
  padding:0;
  border:0;
  border-radius:0;
  background:transparent;
  color:#194d70;
  box-shadow:none;
}

.match.fixture-card .status{
  background:rgba(59,113,181,.14);
  color:#315f91;
}

.match.fixture-card .match-date{color:#3f555b}

.match.fixture-card .fixture-score .score-versus{color:#536568}

.match.fixture-card .match-events{
  border-color:rgba(34,67,76,.16);
  background:rgba(255,255,255,.52);
}

.match.fixture-card .match-events span{color:#3c6692}

.match.fixture-card .match-events small{color:#3f5054}

.match.fixture-card .fixture-official{border-top-color:rgba(34,67,76,.14);background:rgba(255,255,255,.28)}

.match.fixture-card .fixture-official span{color:#3c6692}

.match.fixture-card .fixture-official strong{color:#263f46}

.match.fixture-card .actions{border-top-color:rgba(34,67,76,.14)}

.match.fixture-card .button{
  border-color:rgba(25,79,127,.3);
  background:rgba(230,243,248,.66);
  color:#174f79;
}

.match.fixture-card .button:hover,
