/* Home: il separatore resta centrato tra due colonne squadra simmetriche. */
.home-match-teams{column-gap:12px}

.home-match-row{
  grid-template-columns:minmax(140px,.72fr) minmax(280px,1.55fr);
  padding-block:10px;
}

/* Letture: indice delle partite e scheda editoriale modulare. */
.reading-detail .section-heading>p,.section-heading>p{color:var(--muted);font-size:13px}

.reading-fixture-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}

.reading-fixture{position:relative;display:flex;flex-direction:column;gap:0;min-width:0;text-decoration:none}

