.reading-fixture-teams{position:relative;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:center;column-gap:82px;width:100%;padding:24px 20px 20px}

.reading-fixture-teams>b{position:absolute;left:50%;top:50%;display:grid;place-items:center;min-width:40px;height:28px;padding:0 9px;border:1px solid rgba(122,86,21,.24);border-radius:999px;background:rgba(255,248,230,.72);color:var(--glass-gold);font-size:10px;transform:translate(-50%,-50%)}

.reading-fixture-preview{display:grid;grid-template-columns:minmax(0,1.55fr) repeat(2,minmax(72px,.65fr));gap:1px;margin:0 16px 14px;overflow:hidden;border:1px solid rgba(36,90,120,.11);border-radius:15px;background:rgba(36,90,120,.09)}

.reading-fixture-preview>span{display:flex;min-width:0;padding:10px 11px;background:rgba(255,255,255,.76);flex-direction:column;justify-content:center}

.reading-fixture-preview small{color:var(--muted);font-size:9px;font-weight:850;letter-spacing:.06em;text-transform:uppercase}

.reading-fixture-preview strong{margin-top:3px;overflow:hidden;color:#243f56;font-size:12px;line-height:1.25;text-overflow:ellipsis;white-space:nowrap}

.reading-fixture-preview>span:first-child strong{display:-webkit-box;white-space:normal;-webkit-box-orient:vertical;-webkit-line-clamp:2}

.reading-fixture-preview-text{grid-template-columns:1fr}

.reading-fixture-preview-text strong{display:-webkit-box;overflow:hidden;white-space:normal;-webkit-box-orient:vertical;-webkit-line-clamp:2}

.reading-referee-assignment{border-color:rgba(36,90,120,.18);background:linear-gradient(135deg,rgba(255,255,255,.82),rgba(225,244,248,.58))}
.round16-formations>span:first-child{display:none}
.reading-surprise-bar{height:7px;margin-top:10px;overflow:hidden;border-radius:999px;background:rgba(18,55,71,.14)}
.reading-surprise-bar b{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#25a96b 0%,#f2bc3f 58%,#ef5a59 100%)}
.reading-referee-designation{display:grid;grid-template-columns:1.35fr repeat(3,minmax(0,1fr));gap:10px;margin:20px 0}
.reading-referee-designation article{display:grid;gap:6px;padding:14px;border:1px solid rgba(36,90,120,.13);border-radius:14px;background:rgba(255,255,255,.72)}
.reading-referee-designation article:nth-child(2){grid-column:span 2}
.reading-referee-designation span{color:var(--muted);font-size:9px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}
.reading-referee-designation strong{color:#173f51;font-size:13px;line-height:1.4}
.reading-referee-designation .is-main{background:linear-gradient(135deg,#194d70,#267e8f)}
.reading-referee-designation .is-main span,.reading-referee-designation .is-main strong{color:#fff}

.reading-referee-assignment dl{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:20px 0}

.reading-referee-assignment dl>div{padding:13px 14px;border:1px solid rgba(36,90,120,.13);border-radius:14px;background:rgba(255,255,255,.66)}

.reading-referee-assignment dt{color:var(--muted);font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}

.reading-referee-assignment dd{margin:5px 0 0;color:#263f46;font-size:13px;font-weight:850}

.reading-referee-assignment>a{color:#194d70;font-weight:850}
.reading-referee-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:20px 0}
.reading-referee-stats article{padding:14px;border:1px solid rgba(36,90,120,.13);border-radius:14px;background:rgba(255,255,255,.76)}
.reading-referee-stats span,.reading-referee-stats small{display:block;color:var(--muted);font-size:11px;font-weight:750}
.reading-referee-stats strong{display:block;margin:5px 0;color:#173f51;font-size:20px}
.reading-referee-tendencies{margin-top:18px;padding:18px;border-radius:16px;background:rgba(20,72,96,.07)}
.reading-referee-tendencies h3{margin:0 0 12px;color:#173f51;font-size:16px}
.reading-referee-tendencies ul{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:0;padding:0;list-style:none}
.reading-referee-tendencies li{display:grid;gap:4px;padding:12px 14px;border-radius:12px;background:rgba(255,255,255,.7)}
.reading-referee-tendencies li span,.reading-referee-tendencies p,.reading-referee-method{color:var(--muted);font-size:12px;line-height:1.55}
.reading-referee-tendencies p{margin:12px 0 0}
.reading-referee-sources{display:flex;flex-wrap:wrap;gap:14px}
.reading-referee-sources a{color:#194d70;font-weight:850}

.reading-back{display:flex;justify-content:space-between;margin-bottom:18px}

.reading-back a,.reading-back span{color:var(--muted);font-size:12px;font-weight:750;text-decoration:none}

.reading-back a:hover{color:var(--glass-gold)}

.reading-match-hero{display:grid;grid-template-columns:minmax(0,1fr) minmax(320px,.7fr);gap:36px;align-items:center;padding:clamp(26px,5vw,48px);border:1px solid rgba(255,255,255,.9);border-radius:34px;background:linear-gradient(145deg,rgba(255,255,255,.9),rgba(244,247,251,.62));box-shadow:inset 0 1px #fff,0 24px 58px rgba(32,49,73,.12)}

.reading-match-hero h1{font-size:clamp(38px,6vw,68px)}

.reading-match-hero>div>p:not(.eyebrow){color:var(--muted)}

.reading-progress{display:inline-flex;padding:6px 10px;border-radius:999px;background:rgba(167,116,22,.1);color:var(--glass-gold);font-size:11px;font-weight:850}

.reading-matchup{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:14px}

.reading-matchup>b{color:var(--glass-gold);font-size:12px}

.reading-summary{margin-top:18px;padding:18px 22px;border-left:3px solid var(--glass-gold);border-radius:0 18px 18px 0;background:rgba(255,255,255,.55)}

.reading-summary span{color:var(--glass-gold);font-size:10px;font-weight:900;text-transform:uppercase}

.reading-summary p{margin:5px 0 0}

.prediction-engine-panel{margin-top:18px}

.prediction-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,.55fr)) repeat(2,minmax(0,1fr));gap:12px}

.prediction-metrics article{display:grid;gap:4px;padding:18px;border:1px solid rgba(36,90,120,.11);border-radius:18px;background:rgba(255,255,255,.55)}

.prediction-metrics span{color:var(--muted);font-size:10px;font-weight:850;text-transform:uppercase}

.prediction-metrics strong{font-size:clamp(22px,3vw,34px)}

.prediction-metrics small{color:var(--muted);font-size:10px;line-height:1.4}

.prediction-metrics .prediction-surprise{border-color:rgba(167,116,22,.28);background:rgba(255,244,220,.62)}

.prediction-volume-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}

.prediction-match-volume{display:grid;grid-template-columns:minmax(190px,.55fr) minmax(0,1.45fr);gap:18px;align-items:center;margin-bottom:14px;padding:18px 22px;border:1px solid rgba(27,58,75,.18);border-radius:20px;background:linear-gradient(135deg,rgba(255,255,255,.92),rgba(225,237,242,.78))}

.prediction-match-volume h3{margin:3px 0 4px;font-family:"Anton",sans-serif;font-size:26px;font-weight:400}

.prediction-match-volume small{color:var(--muted);font-size:10px}

.prediction-match-volume dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:0}

.prediction-match-volume dl div{padding:12px;border-radius:14px;background:rgba(255,255,255,.75)}

.prediction-match-volume dt{color:var(--muted);font-size:9px;font-weight:850;text-transform:uppercase}

.prediction-match-volume dd{margin:5px 0 0;color:var(--ink);font-size:22px;font-weight:900}

.prediction-match-volume dd small{font-size:9px;font-weight:800}

.prediction-volume-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:18px 0}

.prediction-volume-metrics>div{display:grid;gap:5px;padding:12px;border:1px solid rgba(36,90,120,.1);border-radius:14px;background:rgba(255,255,255,.44)}

.prediction-volume-metrics span,.prediction-channels>span{color:var(--muted);font-size:10px;font-weight:850;text-transform:uppercase}

.prediction-volume-metrics strong{font-size:22px}

.prediction-volume-metrics strong small{display:block;color:var(--muted);font-size:9px;font-weight:750}

.prediction-channels{display:grid;gap:8px}

.prediction-channels>div{display:grid;grid-template-columns:55px 1fr 38px;align-items:center;gap:8px}

.prediction-channels>div small{color:var(--muted);font-size:10px}

.prediction-channels i{height:7px;overflow:hidden;border-radius:999px;background:rgba(36,90,120,.09)}

.prediction-channels i b{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--glass-gold),#d7b96e)}

.prediction-channels>div strong{font-size:10px;text-align:right}

.prediction-channels em{color:#7a6740;font-size:10px;font-style:normal;font-weight:800}

.prediction-players-grid{display:grid;grid-template-columns:1fr;gap:14px;margin-top:18px}

.prediction-booked-panel{padding:22px;border:1px solid var(--glass-border);border-radius:24px;background:rgba(255,255,255,.58)}

.prediction-booked-panel>header{display:flex;justify-content:space-between;gap:18px}

.prediction-booked-panel h2{margin:3px 0}

.prediction-booked-panel>header>p{max-width:360px;color:var(--muted);font-size:11px}

.prediction-booked-panel ol{display:grid;gap:7px;margin:16px 0 0;padding:0;list-style:none}

.prediction-booked-panel li{display:grid;grid-template-columns:28px 1fr auto;align-items:center;gap:10px;padding:10px;border:1px solid rgba(36,90,120,.08);border-radius:13px;background:rgba(255,255,255,.4)}

.prediction-booked-panel li>span{display:grid;width:27px;height:27px;place-items:center;border-radius:50%;background:#edf1f5;color:#36516d;font-size:11px;font-weight:900}

.prediction-booked-panel li>div{display:grid;gap:2px}

.prediction-booked-panel li>div strong{font-size:13px}

.prediction-booked-panel li small,.prediction-booked-panel li em{color:var(--muted);font-size:9px;font-style:normal}

.prediction-booked-panel li>b{color:#8e6112;font-size:12px}

.prediction-booked-panel li.possible-first-booked{border-color:rgba(167,116,22,.32);background:rgba(255,244,220,.62)}

.prediction-booked-panel li.possible-first-booked>span{background:var(--glass-gold);color:#fff}

.serie-a-shooters>div{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}

.serie-a-shooters article{padding:18px;border:1px solid rgba(36,90,120,.1);border-radius:18px;background:rgba(255,255,255,.52);box-shadow:inset 0 1px rgba(255,255,255,.82)}

.serie-a-shooters article h3{margin:0;color:#183c54;font-size:20px}

.serie-a-shooters article>p{margin:3px 0 12px;color:var(--muted);font-size:9px}

.serie-a-shooters ol{display:grid;gap:5px;margin:0;padding:0;list-style:none}

.serie-a-shooters li{display:grid;grid-template-columns:24px minmax(0,1fr) auto;gap:9px;align-items:center;padding:8px 0;border-top:1px solid rgba(36,90,120,.09)}

.serie-a-shooters li>span{display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:var(--glass-blue);color:#fff;font-size:9px;font-weight:900}

.serie-a-shooters li>div{display:grid;gap:2px;min-width:0}

.serie-a-shooters li strong{overflow:hidden;color:#213b46;font-size:11px;text-overflow:ellipsis;white-space:nowrap}

.serie-a-shooters li small,.serie-a-shooters li em{color:var(--muted);font-size:8px;font-style:normal}

.serie-a-shooters li>b{display:grid;gap:2px;color:#176b8f;font-size:16px;text-align:right}

.serie-a-shooters li>b small{font-size:7px;font-weight:800}

.serie-a-shooters>.objective-method{margin-bottom:0}

.prediction-market-section details{margin-top:14px}

.prediction-market-section summary{cursor:pointer;color:#244b72;font-size:12px;font-weight:850}

.prediction-market-table{min-width:900px}

.prediction-market-table td:first-child{display:grid;gap:2px;min-width:150px}

.prediction-market-table td:first-child small{color:var(--muted);font-size:10px}

.prediction-market-table .positive{color:#087a4b;font-weight:850}

.prediction-market-table .negative{color:#a53a31;font-weight:800}

.prediction-combos{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));align-items:start;gap:10px}

.prediction-combo-card{display:grid;gap:7px;padding:14px;border:1px solid rgba(167,116,22,.22);border-radius:15px;background:rgba(255,247,228,.55)}
.prediction-combo-risk{display:grid;gap:2px;padding:8px 10px;border-radius:10px;background:rgba(30,126,81,.08)}.prediction-combo-risk[data-risk-status="outside"]{background:rgba(177,54,54,.09)}.prediction-combo-risk strong{font-size:10px}.prediction-combo-risk span,.prediction-combo-risk small{color:var(--muted);font-size:9px;line-height:1.35}
.prediction-combo-card-nd{min-height:0;align-content:start;padding:12px;background:rgba(255,255,255,.5)}
.prediction-combo-card-nd>div{display:flex;gap:8px;align-items:baseline}
.prediction-combo-card-nd>div strong{font-size:13px}
.prediction-combo-card-nd>div small{color:var(--muted);font-size:9px;line-height:1.35}

.prediction-combos span{color:#8e6112;font-size:9px;font-weight:900;text-transform:uppercase}

.prediction-combos strong{font-size:14px}

.prediction-combo-legs{display:grid;gap:4px;margin:4px 0;padding:0;list-style:none}

.prediction-combo-legs li{display:flex;justify-content:space-between;gap:12px;padding:5px 0;border-bottom:1px solid rgba(167,116,22,.12);font-size:11px;line-height:1.35}

.prediction-combo-legs li:last-child{border-bottom:0}

.prediction-combo-legs b{white-space:nowrap;color:#6f4a0d}

.prediction-combos small,.prediction-combos p{margin:0;color:var(--muted);font-size:10px;line-height:1.45}
.prediction-combo-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px;margin:2px 0}
.prediction-combo-metrics>div{padding:7px 5px;border-radius:9px;background:rgba(255,255,255,.68);text-align:center}
.prediction-combo-metrics dt{color:var(--muted);font-size:8px;text-transform:uppercase}
.prediction-combo-metrics dd{margin:3px 0 0;color:#6f4a0d;font-size:11px;font-weight:850}
.prediction-combo-weakest{padding-top:6px;border-top:1px solid rgba(167,116,22,.14)}
.reading-panel-empty-compact{display:flex;gap:8px;align-items:baseline;padding:9px 11px}
.reading-panel-empty-compact span{color:var(--muted);font-size:10px}

.reading-module-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}

.reading-module{display:flex;flex-direction:column;min-height:260px;padding:22px;border:1px solid var(--glass-border);border-radius:24px;background:linear-gradient(145deg,rgba(255,255,255,.86),rgba(255,255,255,.58));box-shadow:inset 0 1px #fff,0 14px 36px rgba(32,49,73,.08)}

.reading-module:last-child{grid-column:1/-1}

.reading-module header{display:grid;grid-template-columns:36px 1fr;gap:12px;padding-bottom:16px;border-bottom:1px solid rgba(36,90,120,.12)}

.reading-module header>span{color:var(--glass-gold);font-size:11px;font-weight:900}

.reading-module h3{margin:0 0 5px}

.reading-module header p{margin:0;color:var(--muted);font-size:12px}

.reading-module>p{font-size:14px}

.reading-module footer{margin-top:auto;padding-top:14px;border-top:1px solid rgba(36,90,120,.12);font-size:11px}

.reading-module footer a{color:var(--glass-gold)}

.reading-missing{display:flex;flex-direction:column;justify-content:center;flex:1;margin-top:16px;padding:18px;border:1px dashed rgba(36,90,120,.2);border-radius:16px;background:rgba(255,255,255,.25)}

.reading-missing strong{color:var(--glass-gold);font-size:22px}

.reading-missing span{color:var(--muted);font-size:12px}

.reading-content{font-size:14px}

.reading-content ul{margin:14px 0 0;padding-left:20px}

.reading-content li{margin:6px 0;color:var(--muted)}

/* Prototipo letture · prima giornata */
.reading-summary-prototype{display:grid;grid-template-columns:minmax(0,2fr) minmax(240px,1fr);gap:1px;margin-top:16px;overflow:hidden;border:1px solid var(--glass-border);border-radius:22px;background:rgba(255,255,255,.7);box-shadow:0 14px 34px rgba(32,49,73,.08)}

.reading-summary-prototype>div{display:flex;flex-direction:column;min-height:116px;padding:18px;background:rgba(255,255,255,.52)}

.reading-summary-prototype span,.reading-data-panel>span{color:var(--glass-gold);font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}

.reading-summary-prototype strong{margin:7px 0 3px;font-size:20px}

.reading-summary-prototype small{margin-top:auto;color:var(--muted)}

.reading-score-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:12px}

.reading-score-list>div{display:flex;align-items:center;justify-content:center;flex-direction:column;min-height:72px;padding:10px;border:1px solid rgba(36,90,120,.12);border-radius:14px;background:rgba(255,255,255,.38)}

