.reading-score-list strong{margin:0;font-size:22px}

.reading-score-list small{margin-top:3px;font-size:10px;font-weight:850;letter-spacing:.05em;text-transform:uppercase}

.reading-score-list .is-central small{color:var(--glass-gold)}

.reading-score-note{display:block;margin-top:8px;color:var(--muted);font-size:10px;line-height:1.45}

.reading-prototype-banner{display:flex;align-items:center;gap:18px;margin-top:16px;padding:16px 20px;border:1px solid rgba(167,116,22,.22);border-radius:18px;background:rgba(255,248,229,.62)}

.reading-prototype-banner strong{flex:0 0 auto;color:var(--glass-gold)}

.reading-prototype-banner p{margin:0;color:var(--muted);font-size:13px}

.reading-archive-banner{border-color:rgba(36,90,120,.2);background:rgba(238,244,249,.78)}

