.reading-match-events-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:16px}

.reading-match-events-grid>article{padding:20px;border:1px solid rgba(36,90,120,.1);border-radius:20px;background:rgba(255,255,255,.62)}

.reading-match-events-grid h3{margin:0 0 12px}

.reading-match-events-grid ol{display:grid;gap:2px;margin:0;padding:0;list-style:none}

.reading-match-events-grid li{display:grid;grid-template-columns:35px minmax(0,1fr);align-items:start;gap:9px;padding:9px 0;border-top:1px solid rgba(36,90,120,.08)}

