.reading-match-events-grid li>div{display:grid;gap:2px;min-width:0}

.reading-match-events-grid li strong{font-size:12px}

.reading-match-events-grid li small{color:var(--muted);font-size:10px;line-height:1.4}

.reading-booking-card{display:block!important;width:11px;height:15px;border-radius:2px;background:#efc62b;box-shadow:0 1px 2px rgba(0,0,0,.18)}

.reading-booking-card.is-red{background:#d92d20}
.reading-booking-card.is-unknown{background:#77869b;border:1px dashed currentColor}

.reading-post-match-empty{margin:0;color:var(--muted);font-size:11px}

