.reading-team-comparison thead th{background:rgba(23,61,104,.06);font-size:12px}

.reading-team-comparison tbody th{color:var(--muted);font-size:10px;font-weight:800;text-transform:uppercase}

.reading-team-comparison tbody td{width:28%;color:#173d68;font-size:15px;font-weight:900}

.reading-player-stats-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:16px}

.reading-player-team{min-width:0;overflow:hidden;border:1px solid rgba(36,90,120,.1);border-radius:20px;background:rgba(255,255,255,.66)}

.reading-player-team>header{display:flex;align-items:center;gap:12px;padding:16px 18px;border-bottom:1px solid rgba(36,90,120,.09)}

.reading-player-team>header img{width:38px;height:38px;object-fit:contain}

.reading-player-team h3{margin:0}

.reading-player-team header small{color:var(--muted)}

.reading-player-table-scroll{max-width:100%;overflow-x:auto}

.reading-player-table{width:100%;min-width:650px;border-collapse:collapse}

.reading-player-table th,.reading-player-table td{padding:9px 10px;border-bottom:1px solid rgba(36,90,120,.07);font-size:10px;text-align:center;white-space:nowrap}

.reading-player-table th{background:rgba(23,61,104,.04);color:var(--muted);font-size:9px;text-transform:uppercase}

.reading-player-table th:first-child,.reading-player-table td:first-child{text-align:left}

.reading-player-table td:first-child{font-size:11px}

.reading-post-match-source{display:inline-block;margin-top:18px;color:#8e6112;font-size:11px;font-weight:850;text-decoration:underline;text-underline-offset:3px}

.reading-match-hero.is-finished .reading-matchup b{min-width:92px;font-size:34px}

.reading-result-summary>div{justify-content:center}
.reading-result-summary{grid-template-columns:repeat(3,minmax(0,1fr))}
.reading-result-summary>div+div{border-left:1px solid rgba(36,90,120,.11)}

.reading-info-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
.reading-info-grid>.reading-referee-assignment{min-width:0;margin-top:0;align-self:start}
.reading-info-grid>.reading-referee-assignment .section-heading{align-items:flex-start;flex-direction:column;gap:6px}

.reading-base-shape{margin-top:12px;padding:14px;border:1px solid rgba(36,90,120,.12);border-radius:15px;background:rgba(255,255,255,.32)}

.reading-base-shape strong{display:block}

.reading-base-shape p{margin:4px 0 0;color:var(--muted);font-size:12px}

.reading-unavailable{display:flex;flex-direction:column;justify-content:center;min-height:108px;padding:15px;border:1px dashed rgba(36,90,120,.2);border-radius:15px;background:rgba(255,255,255,.24)}

.reading-unavailable span{color:var(--muted);font-size:11px}

.reading-unavailable strong{margin:4px 0;color:var(--glass-gold);font-size:24px}

.reading-unavailable small{color:var(--muted)}

.reading-context-rail{display:grid;align-content:start;gap:14px;min-width:0}

.reading-evidence-card{padding:20px;border:1px solid var(--glass-border);border-radius:24px;background:linear-gradient(145deg,rgba(255,255,255,.86),rgba(255,255,255,.58));box-shadow:inset 0 1px #fff,0 14px 36px rgba(32,49,73,.08)}

.reading-evidence-card dl{display:grid;gap:8px;margin:14px 0 0}

.reading-evidence-card dl>div{display:flex;justify-content:space-between;gap:16px;padding-top:9px;border-top:1px solid rgba(36,90,120,.1)}

.reading-evidence-card dt{color:var(--muted);font-size:11px}

.reading-evidence-card dd{margin:0;text-align:right;font-size:12px;font-weight:800}

.reading-panel-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}

.reading-data-panel{min-height:220px;padding:22px;border:1px solid var(--glass-border);border-radius:24px;background:linear-gradient(145deg,rgba(255,255,255,.86),rgba(255,255,255,.58));box-shadow:inset 0 1px #fff,0 14px 36px rgba(32,49,73,.08)}

.reading-data-panel-wide{grid-column:1/-1}

.reading-stat-list{display:grid;gap:0;margin:14px 0 0}

.reading-stat-list>div{display:flex;justify-content:space-between;gap:16px;padding:9px 0;border-bottom:1px solid rgba(36,90,120,.1)}

.reading-stat-list dt{color:var(--muted)}

.reading-stat-list dd{margin:0;font-weight:800}

.reading-panel-empty{display:flex;min-height:150px;flex-direction:column;justify-content:center}

.reading-panel-empty strong{color:var(--glass-gold);font-size:24px}

.reading-panel-empty p{margin:5px 0 0;color:var(--muted)}

.reading-pilot-evidence>div{display:grid;gap:14px}

.reading-pilot-card{padding:24px;border:1px solid var(--glass-border);border-radius:24px;background:linear-gradient(145deg,rgba(255,255,255,.9),rgba(255,255,255,.62));box-shadow:inset 0 1px #fff,0 14px 36px rgba(32,49,73,.08)}

.reading-pilot-card header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-bottom:13px;border-bottom:1px solid rgba(36,90,120,.1)}

.reading-pilot-card header span{font-size:18px;font-weight:850}

.reading-pilot-card header strong{padding:5px 9px;border-radius:999px;background:rgba(25,131,78,.1);color:#167047;font-size:10px;text-transform:uppercase}

.reading-pilot-card>p{max-width:940px;font-size:14px;line-height:1.7}

.reading-pilot-card ul{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 24px;margin:16px 0;padding-left:20px}

.reading-pilot-card li{color:var(--muted);font-size:12px}

.reading-pilot-card footer{padding-top:13px;border-top:1px solid rgba(36,90,120,.1);font-size:11px}

.reading-pilot-card footer a{color:var(--glass-gold)}

/* Probabili formazioni compatte nelle Letture */
.reading-lineup-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:14px 0}

.reading-lineup-card{overflow:hidden;border:1px solid rgba(14,42,105,.13);border-radius:16px;background:#101923;box-shadow:0 10px 24px rgba(19,31,50,.1)}

.reading-lineup-card>header{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;background:linear-gradient(115deg,var(--reading-lineup-primary),var(--reading-lineup-secondary));color:var(--reading-lineup-head-ink,#fff)}

.reading-lineup-card>header span{min-width:0;overflow:hidden;font-size:.8rem;font-weight:900;text-overflow:ellipsis;white-space:nowrap}

.reading-lineup-card>header strong{flex:none;color:inherit;font-size:.75rem}

.reading-lineup-field{position:relative;isolation:isolate;display:flex;min-height:250px;margin:8px;padding:18px 7px;overflow:hidden;border:1px solid rgba(255,255,255,.68);border-radius:11px;background:repeating-linear-gradient(0deg,rgba(255,255,255,.035) 0,rgba(255,255,255,.035) 42px,rgba(0,0,0,.035) 42px,rgba(0,0,0,.035) 84px),linear-gradient(150deg,#176b45,#0a4b35);flex-direction:column;justify-content:space-between}

.reading-lineup-field::before{content:"";position:absolute;z-index:-1;top:50%;left:0;width:100%;border-top:1px solid rgba(255,255,255,.62)}

.reading-lineup-field::after{content:"";position:absolute;z-index:-1;left:50%;bottom:-1px;width:46%;height:44px;border:1px solid rgba(255,255,255,.62);border-bottom:0;transform:translateX(-50%)}

.reading-lineup-centre{position:absolute;z-index:-1;top:50%;left:50%;width:68px;height:68px;border:1px solid rgba(255,255,255,.62);border-radius:50%;transform:translate(-50%,-50%)}

.reading-lineup-row{display:flex;align-items:center;justify-content:space-evenly;width:min(calc(var(--reading-lineup-count) * 70px),100%);margin:0 auto;gap:2px}

.reading-lineup-row strong{flex:1 1 0;max-width:70px;color:#fff;font-size:clamp(.55rem,.78vw,.67rem);font-weight:900;line-height:1.05;text-align:center;text-shadow:0 1px 2px #000,0 0 7px rgba(0,0,0,.7)}

.reading-lineup-card>footer{padding:0 10px 9px;color:#c3ccd5;font-size:.62rem}
.reading-lineup-substitutes{margin:5px 0 0;line-height:1.35}
.reading-lineup-substitutes strong{color:#fff}

.reading-tactical-baseline>div{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}

.reading-tactical-card{position:relative;padding:24px;border:1px solid var(--glass-border);border-radius:24px;background:linear-gradient(145deg,rgba(255,255,255,.9),rgba(255,255,255,.62));box-shadow:inset 0 1px #fff,0 14px 36px rgba(32,49,73,.08)}

.reading-tactical-card>.sample-label{position:absolute;right:22px;top:22px}

.reading-tactical-card dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:18px 0}

.reading-tactical-card dl>div{padding:10px;border:1px solid rgba(36,90,120,.09);border-radius:13px;background:rgba(255,255,255,.35)}

.reading-tactical-card dt{color:var(--muted);font-size:10px}

.reading-tactical-card dd{margin:4px 0 0;font-weight:800}

.reading-tactical-traits{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}

.reading-tactical-traits>div{padding:13px;border-top:1px solid rgba(36,90,120,.1)}

.reading-tactical-traits strong{font-size:12px}

.reading-tactical-traits ul{margin:8px 0 0;padding-left:17px}

.reading-tactical-traits li{margin:6px 0;color:var(--muted);font-size:11px}

.reading-tactical-note{padding:12px;border-radius:12px;background:#fff4dc;color:#744a00;font-size:11px}

.reading-tactical-card>a{display:inline-block;margin-top:12px;color:var(--glass-gold);font-size:11px;font-weight:800}

.reading-fixture{position:relative}

.reading-completed-matchday{border:1px solid var(--glass-border);border-radius:20px;background:rgba(255,255,255,.58);overflow:hidden}

.reading-completed-matchday>summary{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:17px 20px;cursor:pointer;list-style:none}

.reading-completed-matchday>summary::-webkit-details-marker{display:none}

.reading-completed-matchday>summary span{font-family:"Anton",sans-serif;font-size:20px}

.reading-completed-matchday>summary small{color:var(--muted);font-size:10px}

.reading-completed-matchday[open]>summary{border-bottom:1px solid rgba(36,90,120,.1)}

.reading-completed-matchday>.reading-fixture-grid{padding:14px}

.reading-h2h-matchdays{display:grid;gap:10px}

.reading-h2h-matchday{border:1px solid var(--glass-border);border-radius:20px;background:rgba(255,255,255,.5);overflow:hidden}

.reading-h2h-matchday>summary{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:17px 20px;cursor:pointer;list-style:none}

.reading-h2h-matchday>summary::-webkit-details-marker{display:none}

.reading-h2h-matchday>summary span{font-family:"Anton",sans-serif;font-size:20px}

.reading-h2h-matchday>summary small{color:var(--muted);font-size:10px}

.reading-h2h-matchday[open]>summary{border-bottom:1px solid rgba(36,90,120,.1)}

.reading-h2h-matchday>.reading-fixture-grid{padding:14px}

.reading-h2h-list{display:grid;gap:10px}

.reading-h2h-match{border:1px solid var(--glass-border);border-radius:18px;background:rgba(255,255,255,.56);overflow:hidden}

.reading-h2h-match>summary{display:grid;grid-template-columns:minmax(180px,.45fr) 1fr;align-items:center;gap:20px;padding:16px 18px;cursor:pointer;list-style:none}

.reading-h2h-match>summary::-webkit-details-marker{display:none}

.reading-h2h-match>summary span{color:var(--muted);font-size:10px;font-weight:800;text-transform:uppercase}

.reading-h2h-match>summary strong{font-size:15px}

.reading-h2h-events{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;padding:16px 18px;border-top:1px solid rgba(36,90,120,.1)}

.reading-h2h-events section{padding:14px;border-radius:14px;background:rgba(241,245,248,.7)}

.reading-h2h-events h3{margin:0 0 10px;font-size:12px}

.reading-h2h-events ul{display:grid;gap:7px;margin:0;padding:0;list-style:none}

.reading-h2h-events li{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding-bottom:6px;border-bottom:1px solid rgba(36,90,120,.08)}

.reading-h2h-events li strong{font-size:11px}

.reading-h2h-events li small{color:var(--muted);font-size:9px;text-align:right}

.reading-h2h-match>a{display:inline-block;margin:0 18px 16px;color:var(--glass-gold);font-size:10px;font-weight:850}

.reading-h2h-empty{margin:0;color:var(--muted);font-size:11px}

.reading-h2h-warning{display:block;margin-top:10px;color:#875d11;font-size:9px}

.reading-h2h-model{margin-top:14px;padding:16px 18px;border:1px solid rgba(167,116,22,.24);border-radius:17px;background:rgba(255,247,228,.55)}

.reading-h2h-model strong{color:#875d11;font-size:11px;text-transform:uppercase}

.reading-h2h-model p{margin:6px 0 0;color:var(--muted);font-size:11px;line-height:1.5}

/* Dettaglio Letture: gerarchia editoriale senza modificare le card dell'indice. */
.reading-back{align-items:center;padding:0 4px}

.reading-back a,.reading-back span{display:inline-flex;align-items:center;min-height:34px;padding:7px 11px;border:1px solid rgba(36,90,120,.1);border-radius:999px;background:rgba(255,255,255,.42);box-shadow:inset 0 1px rgba(255,255,255,.7)}

.reading-match-hero{position:relative;isolation:isolate;overflow:hidden;border-color:rgba(255,255,255,.96);background:radial-gradient(circle at 12% 18%,rgba(181,250,255,.42),transparent 38%),radial-gradient(circle at 88% 82%,rgba(244,207,114,.2),transparent 34%),linear-gradient(145deg,rgba(255,255,255,.94),rgba(239,247,248,.7));box-shadow:inset 0 1px #fff,0 28px 68px rgba(32,49,73,.14)}

.reading-match-hero::before{content:"";position:absolute;z-index:-1;top:-120px;right:23%;width:260px;height:260px;border:1px solid rgba(36,90,120,.08);border-radius:50%;box-shadow:0 0 0 42px rgba(255,255,255,.16),0 0 0 84px rgba(36,90,120,.025)}

.reading-match-hero h1{max-width:760px;line-height:.98;text-wrap:balance}

.reading-match-hero>div>p:not(.eyebrow){font-size:15px}

.reading-progress{border:1px solid rgba(167,116,22,.16);background:rgba(255,249,231,.72);box-shadow:inset 0 1px rgba(255,255,255,.8)}

.reading-matchup{padding:12px;border:1px solid rgba(36,90,120,.09);border-radius:26px;background:rgba(255,255,255,.32);box-shadow:inset 0 1px rgba(255,255,255,.75)}

.reading-matchup>b{display:grid;width:38px;height:38px;place-items:center;border:1px solid rgba(167,116,22,.2);border-radius:50%;background:rgba(255,249,231,.8)}

.reading-match-hero~.section{margin-top:24px;padding:clamp(22px,3vw,32px);border:1px solid rgba(255,255,255,.78);border-radius:30px;background:linear-gradient(145deg,rgba(255,255,255,.7),rgba(244,249,250,.44));box-shadow:inset 0 1px rgba(255,255,255,.92),0 18px 48px rgba(32,49,73,.08)}

.reading-match-hero~.section>.section-heading{align-items:end;margin-bottom:22px;padding-bottom:17px;border-bottom:1px solid rgba(36,90,120,.1)}

.reading-match-hero~.section>.section-heading>div{position:relative;padding-left:16px}

.reading-match-hero~.section>.section-heading>div::before{content:"";position:absolute;left:0;top:4px;width:4px;height:calc(100% - 4px);border-radius:999px;background:linear-gradient(var(--glass-blue),var(--glass-gold))}

.reading-match-hero~.section>.section-heading h2{margin-bottom:0;text-wrap:balance}

.reading-match-hero~.reading-summary-prototype{gap:10px;padding:10px;border-color:rgba(36,90,120,.1);background:rgba(255,255,255,.46)}

.reading-match-hero~.reading-summary-prototype>div{border:1px solid rgba(36,90,120,.08);border-radius:20px;background:rgba(255,255,255,.64)}

.reading-match-hero~.reading-summary-prototype .reading-final-verdict{border-color:rgba(167,116,22,.16);background:linear-gradient(145deg,rgba(255,248,229,.78),rgba(255,255,255,.66))}

.reading-match-hero~.prediction-engine-panel .prediction-metrics{gap:10px}

.reading-match-hero~.prediction-engine-panel .prediction-metrics article{position:relative;overflow:hidden;border-color:rgba(36,90,120,.09);background:rgba(255,255,255,.64);box-shadow:inset 0 1px rgba(255,255,255,.85)}

.reading-match-hero~.prediction-engine-panel .prediction-metrics article:nth-child(-n+3)::after{content:"";position:absolute;right:-18px;bottom:-26px;width:74px;height:74px;border-radius:50%;background:rgba(181,250,255,.18)}

.reading-match-hero~.prediction-engine-panel .prediction-metrics article:nth-child(-n+3) strong{color:#183c54}

.reading-match-hero~.prediction-engine-panel .prediction-surprise{background:linear-gradient(145deg,rgba(255,244,220,.8),rgba(255,255,255,.58))}

/* Lettura compatta: riepilogo integrato nell'hero e pannello probabilita ridotto. */
.reading-matchup{padding:0;border:0;border-radius:0;background:transparent;box-shadow:none}

.reading-matchup>b{display:block;width:auto;height:auto;border:0;border-radius:0;background:transparent}

.reading-hero-summary{grid-column:1/-1;grid-template-columns:minmax(0,2.5fr) minmax(210px,.7fr);gap:0;margin:0;padding-top:14px;overflow:visible;border:0;border-top:1px solid rgba(36,90,120,.11);border-radius:0;background:transparent;box-shadow:none}

.reading-hero-summary>div{min-height:0;padding:0 14px;background:transparent}

.reading-hero-summary>div:first-child{padding-left:0}

.reading-hero-summary .reading-final-verdict{padding-right:0;border-left:1px solid rgba(36,90,120,.11)}

.reading-hero-summary .reading-final-verdict strong{margin:5px 0 2px;font-size:18px}

.reading-hero-summary .reading-final-verdict small{font-size:11px}

/* Risultato concluso: tabellone compatto e solo pronostico sotto la testata. */
.reading-match-hero.is-finished{grid-template-columns:minmax(0,1.18fr) minmax(360px,.82fr);gap:28px}

.reading-match-hero.is-finished .reading-matchup{padding:16px 18px;border:1px solid rgba(36,90,120,.1);border-radius:26px;background:linear-gradient(145deg,rgba(255,255,255,.7),rgba(239,247,248,.46));box-shadow:inset 0 1px rgba(255,255,255,.92),0 14px 34px rgba(32,49,73,.07)}

.reading-match-hero.is-finished .reading-matchup>b{display:grid;place-items:center;min-width:104px;height:60px;padding:0 16px;border:1px solid rgba(13,55,92,.35);border-radius:18px;background:linear-gradient(135deg,#244f73,#163a5a);box-shadow:0 10px 22px rgba(19,55,82,.2),inset 0 1px rgba(255,255,255,.18);color:#fff;font-family:var(--font-display);font-size:34px;font-weight:400;letter-spacing:.06em}

.reading-hero-summary.reading-result-summary{grid-template-columns:minmax(0,1.7fr) repeat(2,minmax(120px,.65fr));gap:10px;padding-top:18px}

.reading-hero-summary.reading-result-summary>div{--summary-accent:#245a78;position:relative;justify-content:flex-start;min-height:126px;overflow:hidden;padding:19px 20px 17px;border:1px solid rgba(36,90,120,.1);border-radius:20px;background:linear-gradient(145deg,rgba(255,255,255,.8),rgba(235,246,248,.62));box-shadow:inset 0 1px rgba(255,255,255,.92),0 10px 24px rgba(32,49,73,.07)}

.reading-hero-summary.reading-result-summary>div::before{content:"";position:absolute;top:0;left:20px;right:20px;height:3px;border-radius:0 0 999px 999px;background:var(--summary-accent);opacity:.72}

.reading-hero-summary.reading-result-summary>div+div{border-left:1px solid rgba(36,90,120,.1)}

.reading-hero-summary.reading-result-summary span{display:flex;align-items:center;gap:8px;color:var(--summary-accent);line-height:1.3}

.reading-hero-summary.reading-result-summary span::before{content:"";flex:0 0 7px;width:7px;height:7px;border-radius:50%;background:currentColor;box-shadow:0 0 0 4px color-mix(in srgb,currentColor 12%,transparent)}

.reading-hero-summary.reading-result-summary strong{margin:10px 0 5px;color:#213b46;font-family:var(--font-display);font-size:30px;font-weight:400;line-height:1;letter-spacing:.025em}

.reading-hero-summary.reading-result-summary small{margin-top:auto;color:#66778a;font-size:11px;line-height:1.4}

.reading-hero-summary .reading-prediction-card{--summary-accent:#9a6b16;background:linear-gradient(145deg,rgba(255,246,220,.9),rgba(255,255,255,.74))}

.reading-hero-summary .reading-prediction-card strong{color:#75500f}

.reading-hero-summary .reading-exact-scores{--summary-accent:#9a6b16;background:linear-gradient(145deg,rgba(255,246,220,.9),rgba(255,255,255,.74))}

.reading-hero-summary .reading-exact-scores>span{font-size:10px;font-weight:850;letter-spacing:.05em;text-transform:uppercase}

.reading-hero-summary .reading-hero-signal{justify-content:center}

.reading-hero-summary .reading-hero-signal strong{margin:8px 0 4px;font-size:clamp(23px,2.8vw,32px)}

.reading-hero-summary .reading-hero-surprise{--summary-accent:#9a6b16;background:linear-gradient(145deg,rgba(255,244,220,.82),rgba(255,255,255,.7))}

.reading-hero-summary .reading-score-list{gap:8px;margin-top:8px}

.reading-hero-summary .reading-score-list>div{min-height:54px;padding:6px 8px;border-radius:12px}

.reading-hero-summary .reading-score-list strong{font-size:19px}

.reading-hero-summary .reading-score-list small{font-size:9px}

.reading-score-caveat{display:block;margin-top:8px;color:rgba(18,47,67,.72);font-size:10px;font-weight:700;line-height:1.35}

.reading-match-hero~.prediction-engine-panel{padding:20px 22px}

.reading-match-hero~.prediction-engine-panel>.section-heading{margin-bottom:13px;padding-bottom:11px}

.reading-match-hero~.prediction-engine-panel .prediction-metrics{grid-template-columns:repeat(3,minmax(70px,.58fr)) repeat(2,minmax(120px,1fr)) repeat(2,minmax(140px,1.18fr));gap:7px}

.reading-match-hero~.prediction-engine-panel .prediction-metrics article{min-height:88px;padding:12px}

.reading-match-hero~.prediction-engine-panel .prediction-metrics strong{font-size:clamp(20px,2.2vw,27px)}

/* Prediction Engine V2: rappresentazione editoriale, senza calcoli lato client. */
.reading-hero-summary.reading-result-summary{grid-template-columns:minmax(0,1.65fr) repeat(3,minmax(118px,.62fr))}
.reading-formation-status{--summary-accent:#52717f;display:flex;flex-direction:column;justify-content:center}
