.prediction-v2-team-metrics strong,.prediction-v2-value{display:block;color:#173f58;font-size:22px;font-weight:900}
.prediction-v2-range-text{display:block;color:#5f7180!important;font-size:9px!important;font-weight:800!important;letter-spacing:0!important;text-transform:none!important}
.prediction-v2-range{position:relative;display:block;height:8px;margin-top:3px;border-radius:999px;background:linear-gradient(90deg,rgba(36,90,120,.14),rgba(36,90,120,.3));overflow:visible}
.prediction-v2-range i{position:absolute;top:50%;left:var(--range-position);width:10px;height:10px;border:2px solid #fff;border-radius:50%;background:#176b8f;box-shadow:0 1px 5px rgba(24,65,90,.3);transform:translate(-50%,-50%)}
.prediction-v2-channels{margin-top:12px;border-top:1px solid rgba(36,90,120,.09)}
.prediction-v2-channels>summary{padding:12px 0 0;cursor:pointer;color:#365766;font-size:10px;font-weight:850;list-style-position:inside}
.prediction-v2-channels .prediction-channels{margin-top:10px}
.prediction-v2-channels summary:focus-visible{outline:2px solid #176b8f;outline-offset:4px;border-radius:4px}
.prediction-v2-missing,.prediction-v2-empty{color:var(--muted);font-weight:750}
.prediction-v2-matchup-card>div{display:grid;gap:9px}
.prediction-v2-matchup-card section{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:5px 12px;padding:13px;border:1px solid rgba(36,90,120,.09);border-radius:14px;background:rgba(255,255,255,.58)}
.prediction-v2-matchup-card section>span{color:#405d6c;font-size:10px;font-weight:900;letter-spacing:.04em;text-transform:uppercase}
.prediction-v2-matchup-card section>strong{font-size:11px;text-transform:uppercase}
.prediction-v2-matchup-card section>p,.prediction-v2-matchup-card section>small{grid-column:1/-1;margin:0}
.prediction-v2-matchup-card section>p{color:#314b57;font-size:11px;line-height:1.45}
.prediction-v2-matchup-card section>small{color:var(--muted);font-size:9px}
.prediction-v2-own-signal{margin:0 0 12px;color:#365766;font-size:11px;font-weight:750}
.signal-favourable{color:#177453}.signal-neutral{color:#536b78}.signal-unfavourable{color:#9b573d}.signal-unknown{color:#7b6c58}
.prediction-v2-shooter-table{overflow:hidden;border:1px solid rgba(36,90,120,.12);border-radius:18px;background:rgba(255,255,255,.6)}
.prediction-v2-shooter-table table{width:100%;border-collapse:collapse;font-size:11px}
.prediction-v2-shooter-table th,.prediction-v2-shooter-table td{padding:11px 9px;border-bottom:1px solid rgba(36,90,120,.08);text-align:center;vertical-align:middle}
.prediction-v2-shooter-table thead th{background:rgba(226,239,242,.76);color:#43606e;font-size:9px;letter-spacing:.04em;text-transform:uppercase}
.prediction-v2-shooter-table tbody th{display:grid;gap:3px;min-width:190px;text-align:left}
.prediction-v2-shooter-table tbody th>strong{color:#1f3d4b;font-size:12px}.prediction-v2-shooter-table tbody th>small{color:var(--muted);font-size:8px;font-weight:650}
.prediction-v2-shooter-table td.is-key{background:rgba(225,244,248,.46);color:#126488;font-weight:900}
.reading-shared-forecast-table{overflow-x:auto}.reading-shared-forecast-table table{min-width:720px}.reading-shared-forecast-table td:first-child{display:grid;gap:3px;min-width:210px;text-align:left}.reading-shared-forecast-table td:first-child small,.reading-shared-forecast-table td:last-child small{display:block;color:var(--muted);font-size:8px}.reading-shared-forecast-table td:nth-child(3){min-width:300px;text-align:left}
.prediction-v2-tier{display:inline-flex;width:max-content;padding:3px 6px;border-radius:999px;background:#e8f0f5;color:#34566a;font-size:7px;font-weight:900;letter-spacing:.04em}
.serie-a-shooters>.prediction-v2-player-cards{display:none}
.prediction-v2-outsider-grid>article>h3{margin:0 0 12px;color:#183c54}
.prediction-v2-zero{padding:18px;border:1px dashed rgba(36,90,120,.22);border-radius:16px;background:rgba(255,255,255,.42)}
.prediction-v2-zero strong{color:#345360}.prediction-v2-zero p{margin:6px 0 0;color:var(--muted);font-size:11px;line-height:1.5}
.prediction-v2-outsider-list{display:grid;gap:9px}
.prediction-v2-outsider-list>section{padding:15px;border:1px solid rgba(36,90,120,.09);border-radius:15px;background:rgba(255,255,255,.6)}
.prediction-v2-outsider-list header{display:flex;justify-content:space-between;gap:12px}.prediction-v2-outsider-list header>div{display:grid;gap:3px}.prediction-v2-outsider-list header small{color:var(--muted);font-size:9px}.prediction-v2-outsider-list header>span{color:#176b8f;font-size:9px;font-weight:850;text-transform:uppercase}
.prediction-v2-outsider-list dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin:12px 0}
.prediction-v2-outsider-list dl>div{padding:9px;border-radius:10px;background:rgba(231,241,243,.7)}.prediction-v2-outsider-list dt{color:var(--muted);font-size:8px;text-transform:uppercase}.prediction-v2-outsider-list dd{margin:4px 0 0;color:#173f58;font-size:13px;font-weight:900}
.prediction-v2-outsider-list>section>p{margin:0;color:#526b78;font-size:9px;line-height:1.4}
.prediction-v2-discipline-teams{margin-bottom:14px}
.prediction-v2-discipline-teams>article>dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin:0}.prediction-v2-discipline-teams>article>dl>div{min-width:0;padding:11px;border-radius:13px;background:rgba(255,255,255,.6)}.prediction-v2-discipline-teams dd{margin:6px 0 0}.prediction-v2-discipline .prediction-booked-panel{margin-top:0}
.reading-official-mvp{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px 18px;align-items:center;margin-bottom:18px;padding:16px 18px;border:1px solid rgba(167,116,22,.24);border-radius:18px;background:linear-gradient(145deg,rgba(255,244,214,.72),rgba(255,255,255,.62))}

.reading-official-mvp>span{color:#8a5b0a;font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}

.reading-official-mvp>strong{grid-column:1;font-size:clamp(20px,2.5vw,28px)}

.reading-official-mvp>small{grid-column:1;color:var(--muted)}

.reading-official-mvp>a{grid-column:2;grid-row:1/4;color:var(--glass-blue);font-size:11px;font-weight:850}

.prediction-engine-notes{margin-top:10px;border-top:1px solid rgba(36,90,120,.09)}

.prediction-engine-notes summary{width:max-content;padding-top:10px;color:var(--glass-blue);font-size:.72rem;font-weight:850;cursor:pointer}

.prediction-engine-notes>div{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px;padding-top:4px}

/* Coppa Italia: percorso cronologico leggibile */
body[data-page="cup"] .cup-stage{overflow:hidden}

body[data-page="cup"] .cup-stage-heading{align-items:flex-end}

body[data-page="cup"] .cup-stage-heading h2{max-width:720px}

body[data-page="cup"] .cup-badge{flex:none;color:#805b16}

.cup-round-nav{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:8px;margin:26px 0 30px;padding:8px;border:1px solid rgba(36,90,120,.12);border-radius:18px;background:rgba(255,255,255,.44)}

.cup-round-nav a{display:flex;align-items:center;gap:8px;min-width:0;padding:10px 11px;border-radius:12px;color:#36516d;font-size:11px;font-weight:850;line-height:1.2;text-decoration:none;transition:background .18s ease,color .18s ease,transform .18s ease}

.cup-round-nav a:hover,.cup-round-nav a:focus-visible{background:#173d68;color:#fff;transform:translateY(-1px)}

.cup-round-nav a:focus-visible{outline:2px solid var(--gold);outline-offset:2px}

.cup-round-nav a span{display:grid;flex:0 0 25px;width:25px;height:25px;place-items:center;border:1px solid rgba(167,116,22,.25);border-radius:50%;background:rgba(244,207,114,.15);color:#9a6a17;font-size:9px}

.cup-round-nav a:hover span,.cup-round-nav a:focus-visible span{border-color:rgba(244,207,114,.44);color:#f7d98e}

.cup-round-list{display:grid;gap:18px}

.cup-round{position:relative;scroll-margin-top:92px;padding:24px;border:1px solid rgba(36,90,120,.13);border-radius:24px;background:linear-gradient(145deg,rgba(255,255,255,.78),rgba(244,248,251,.54));box-shadow:inset 0 1px #fff,0 16px 42px rgba(32,49,73,.07)}

.cup-round::before{position:absolute;top:26px;bottom:-19px;left:45px;width:1px;background:linear-gradient(rgba(167,116,22,.36),rgba(36,90,120,.1));content:""}

.cup-round:last-child::before{display:none}

.cup-round-heading{position:relative;z-index:1;display:grid;grid-template-columns:44px minmax(0,1fr) auto;align-items:center;gap:14px;margin-bottom:20px}

.cup-round-heading>span{display:grid;width:44px;height:44px;place-items:center;border:1px solid rgba(167,116,22,.27);border-radius:50%;background:#f8f2e4;color:#9a6a17;font-size:11px;font-weight:900;box-shadow:0 0 0 7px rgba(255,255,255,.74)}

.cup-round-heading p{margin:0 0 2px;color:#9a6a17;font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}

.cup-round-heading h3{margin:0;color:#183047;font-family:"Anton",sans-serif;font-size:clamp(25px,3vw,34px);font-weight:400;line-height:1.05}

.cup-round-heading>small{padding:6px 9px;border-radius:999px;background:rgba(36,90,120,.07);color:#526b80;font-size:10px;font-weight:850}

.cup-round-disclosure>.cup-round-heading{cursor:pointer;list-style:none}

.cup-round-disclosure>.cup-round-heading::-webkit-details-marker{display:none}

.cup-round-disclosure:not([open])>.cup-round-heading{margin-bottom:0}

.cup-round-disclosure>.cup-round-heading>small::after{display:inline-block;width:7px;height:7px;margin-left:8px;border-right:2px solid currentColor;border-bottom:2px solid currentColor;content:"";transform:translateY(-2px) rotate(45deg);transition:transform .18s ease}

.cup-round-disclosure[open]>.cup-round-heading>small::after{transform:translateY(2px) rotate(225deg)}

.cup-round-disclosure>.cup-round-heading:focus-visible{outline:2px solid var(--gold);outline-offset:7px;border-radius:12px}

.cup-match-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-left:58px}

.cup-match-card{overflow:hidden;border:1px solid rgba(36,90,120,.16);border-radius:16px;background:rgba(255,255,255,.86);box-shadow:0 10px 24px rgba(32,49,73,.055);transition:border-color .18s ease,box-shadow .18s ease,transform .18s ease}

.cup-match-card:hover{border-color:rgba(36,90,120,.3);box-shadow:0 14px 30px rgba(32,49,73,.09);transform:translateY(-1px)}

.cup-match-card>header{display:flex;align-items:center;justify-content:space-between;min-height:34px;padding:7px 13px;border-bottom:1px solid rgba(36,90,120,.1);background:rgba(36,90,120,.045)}

.cup-match-card>header span{color:#6d8294;font-size:9px;font-weight:900;letter-spacing:.1em;text-transform:uppercase}

.cup-match-card>header b{display:grid;width:25px;height:25px;place-items:center;border-radius:50%;background:linear-gradient(145deg,#cda340,#8f6616);color:#fff;font-size:9px}

.cup-match-card>header .cup-result{display:block;width:auto;height:auto;padding:0;border-radius:0;background:transparent;color:#9a5a08;font-size:16px;font-weight:900;letter-spacing:.02em;white-space:nowrap}

.cup-match-teams{display:grid}

.cup-match-card>footer{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:10px;align-items:center;margin:0;padding:9px 13px;border-top:1px solid rgba(36,90,120,.1);background:#f7f9fa;text-align:left}

.cup-match-card>footer span{color:#8a9aa7;font-size:9px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}

.cup-match-card>footer strong{color:#52687a;font-size:10px;font-weight:800;line-height:1.4;text-align:right}

.cup-result-source{color:#8a681f;font-size:9px;font-weight:900;text-decoration:none}

.cup-result-source:hover{text-decoration:underline}

.cup-round--semifinal{border-color:rgba(167,116,22,.2);background:linear-gradient(145deg,rgba(255,252,244,.9),rgba(244,248,251,.62))}

.cup-round--final{padding:28px;border-color:rgba(242,193,78,.34);background:radial-gradient(circle at 88% 0,rgba(242,193,78,.2),transparent 34%),linear-gradient(145deg,#173d68,#0c2346);box-shadow:0 22px 48px rgba(9,30,65,.2)}

.cup-round--final::after{position:absolute;right:38px;bottom:-52px;width:180px;height:180px;border:1px solid rgba(255,255,255,.06);border-radius:50%;box-shadow:0 0 0 34px rgba(255,255,255,.025),0 0 0 68px rgba(255,255,255,.018);content:""}

.cup-round--final .cup-round-heading>span{border-color:rgba(242,193,78,.4);background:#f2c14e;color:#17304d;box-shadow:0 0 0 7px rgba(255,255,255,.08)}

.cup-round--final .cup-round-heading p{color:#f3d17d}

.cup-round--final .cup-round-heading h3{color:#fff}

.cup-round--final .cup-round-heading>small{background:rgba(255,255,255,.1);color:#dce7f7}

.cup-round--final .cup-match-grid{position:relative;z-index:1;grid-template-columns:minmax(0,620px)}

.cup-round--final .cup-match-card{border-color:rgba(242,193,78,.34);background:rgba(255,255,255,.95)}

body[data-page="cup"] .cup-stage-note{margin-top:22px;padding:16px 18px;border:1px solid rgba(36,90,120,.11);border-radius:16px;background:rgba(255,255,255,.42)}

/* Coppa Italia e Lettura: distanza dall'hero coerente con le altre pagine interne. */
body[data-page="cup"] main>.hero+.cup-stage,
body[data-page="readings"] main>.hero+.section{margin-top:24px}

/* Arbitri: consultazione, confronto e profili */
body[data-page="referees"] .referee-section{scroll-margin-top:172px}

body[data-page="referees"] .lead-small,
body[data-page="referees"] .referee-note,
body[data-page="referees"] .method-note p,
body[data-page="referees"] .pilot-missing p{color:var(--glass-muted)}

body[data-page="referees"] .pilot-missing{border-color:rgba(122,86,21,.24);background:rgba(255,247,224,.58)}

body[data-page="referees"] .sample-low{background:#f7e5e5;color:#8d3037}

body[data-page="referees"] .sample-medium{background:#fff0c9;color:#79520b}

body[data-page="referees"] .sample-strong{background:#dff3e8;color:#17633f}

body[data-page="referees"] .source-check{background:rgba(40,58,59,.07);color:var(--glass-muted)}

body[data-page="referees"] .source-check.is-exact{background:#dff3e8;color:#17633f}

body[data-page="referees"] .source-check.is-different{background:#fff0c9;color:#79520b}

body[data-page="referees"] .referee-controls{position:static;top:auto;z-index:9;grid-template-columns:minmax(250px,1fr) minmax(190px,.45fr) auto;max-width:none;margin:18px 0 8px}

body[data-page="referees"] .referee-controls label>span,
.referee-table-controls label>span,
.referee-compare-controls label>span{display:block;margin-bottom:6px;color:var(--glass-muted);font-size:10px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}

body[data-page="referees"] .referee-controls>strong{color:var(--glass-gold)}

.referee-card{grid-template-columns:38px minmax(0,1fr) auto}

.referee-card-action,.referee-name-button{border:0;background:none;color:var(--glass-blue);font:inherit;font-weight:850;cursor:pointer}

.referee-card-action{padding:7px 10px;border:1px solid rgba(36,90,120,.16);border-radius:999px;background:rgba(255,255,255,.4);font-size:11px}

.referee-card-action:hover,.referee-card-action:focus-visible{border-color:rgba(36,90,120,.34);background:#fff}

.referee-empty{margin-top:16px;padding:24px;border:1px dashed rgba(36,90,120,.25);border-radius:17px;background:rgba(255,255,255,.36);text-align:center}

.referee-empty p{margin:5px 0 0;color:var(--glass-muted)}

.referee-table-controls,.referee-compare-controls{display:grid;grid-template-columns:repeat(2,minmax(0,240px));gap:12px;margin:22px 0 14px}

.referee-season-nav{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0}

.referee-season-nav a{padding:10px 16px;border:1px solid rgba(40,58,59,.15);border-radius:999px;background:rgba(255,255,255,.58);color:var(--glass-text);font-weight:850;text-decoration:none}

.referee-season-nav a:hover,.referee-season-nav a.active{border-color:rgba(36,90,120,.35);background:rgba(36,90,120,.14);color:var(--glass-strong)}

.referee-table-controls select,.referee-compare-controls select{width:100%;height:44px;padding:0 12px;border:1px solid rgba(40,58,59,.15);border-radius:12px;background:rgba(255,255,255,.78);color:var(--glass-text);font:inherit}

.referee-stats-result{display:flex;justify-content:flex-end;margin:0 0 8px;color:var(--glass-muted);font-size:12px}

.referee-stats-result p{margin:0}

.referee-stats-result strong{color:var(--glass-text)}

.referee-explorer-table{min-width:1180px}

.referee-explorer-table th:first-child,.referee-explorer-table td:first-child{text-align:left}

.referee-explorer-table th button{padding:0;border:0;background:none;color:inherit;font:inherit;font-weight:inherit;cursor:pointer;white-space:nowrap}

.referee-name-button{display:grid;gap:3px;text-align:left}

.referee-name-button strong{color:var(--glass-text)}

.referee-name-button small{color:var(--glass-muted);font-size:10px;font-weight:650}

.referee-stat-cards{display:none}

.referee-compare{margin-top:34px;padding:22px;border:1px solid var(--glass-border);border-radius:20px;background:rgba(255,255,255,.36)}

.referee-compare header h3{margin:3px 0 0}

.referee-compare-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}

.referee-compare-grid article{padding:20px;border:1px solid var(--glass-border);border-radius:16px;background:rgba(255,255,255,.58)}

.referee-compare-grid article>span:first-child{color:var(--glass-muted);font-size:11px;font-weight:800;text-transform:uppercase}

.referee-compare-grid h4{margin:5px 0 16px;font-size:20px}

.referee-compare-grid dl,.referee-profile-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:0 0 14px}

.referee-compare-grid dl div,.referee-profile-metrics div{padding:10px;border-radius:12px;background:rgba(232,239,240,.72)}

.referee-compare-grid dt,.referee-profile-metrics dt{color:var(--glass-muted);font-size:9px;text-transform:uppercase}

.referee-compare-grid dd,.referee-profile-metrics dd{margin:4px 0 0;color:var(--glass-text);font-size:18px;font-weight:900}

.referee-profile{position:relative;margin-top:26px;padding:24px;border:1px solid rgba(36,90,120,.22);border-radius:22px;background:linear-gradient(135deg,rgba(255,255,255,.78),rgba(223,245,246,.62));box-shadow:0 18px 40px rgba(32,49,73,.1);scroll-margin-top:110px}

.referee-profile[hidden]{display:none}

.referee-profile>header{display:flex;align-items:flex-start;justify-content:space-between;gap:20px}

.referee-profile h3{margin:3px 0;font-size:30px}

.referee-profile header p:last-child{margin:0;color:var(--glass-muted)}

.referee-profile-close{display:grid;place-items:center;width:38px;height:38px;border:1px solid rgba(36,90,120,.16);border-radius:50%;background:rgba(255,255,255,.72);color:var(--glass-text);font-size:24px;cursor:pointer}

.referee-profile-competitions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:22px 0 12px}

