.round16-formations:has(.reading-dual-lineup)>h2,.round16-formations:has(.reading-dual-lineup)>small,.round16-formations:has(.reading-dual-lineup)>small a{color:var(--glass-dark-text)}
.reading-dual-lineup{min-width:0;margin-block:20px}
.reading-dual-lineup>header,.reading-dual-lineup>footer{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;padding:14px 4px;color:var(--glass-dark-text)}
.reading-dual-lineup>header{border-bottom:1px solid var(--glass-dark-border);font-size:16px}
.reading-dual-lineup>header>div{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;min-width:0}
.reading-dual-lineup>header>div:last-child{justify-content:flex-end;text-align:right}
.reading-dual-lineup>header strong{color:inherit;font-size:12px;font-weight:650}
.reading-dual-lineup>header span{font-weight:800}
.reading-dual-lineup>footer{font-size:12px;line-height:1.5;border-top:1px solid var(--glass-dark-border)}
.reading-dual-lineup>footer>div:last-child{text-align:right}
.reading-field-scroll{max-width:100%;overflow-x:auto;overscroll-behavior-x:contain;scrollbar-color:#839f97 #183e33;scrollbar-width:thin;border-radius:12px}
.reading-field-scroll:focus-visible{outline:2px solid var(--glass-dark-text);outline-offset:3px}
.reading-horizontal-field{position:relative;isolation:isolate;width:100%;min-width:1040px;aspect-ratio:1080/600;background:repeating-linear-gradient(90deg,rgba(255,255,255,.025) 0 10%,transparent 10% 20%),#183e33;border-radius:12px;overflow:hidden}
.reading-field-markings{position:absolute;inset:0;width:100%;height:100%;color:rgba(255,255,255,.28);pointer-events:none}
.reading-horizontal-field .reading-kit-player{position:absolute;display:flex;align-items:center;flex-direction:column;gap:5px;width:94px;transform:translate(-50%,-50%)}
.reading-kit-shirt{width:36px;height:36px;flex:none;filter:drop-shadow(0 2px 2px #071e18)}
.reading-kit-shirt .kit-body{fill:var(--kit-primary,var(--reading-lineup-primary));stroke:rgba(255,255,255,.8);stroke-width:1}
.reading-kit-shirt .kit-panel{fill:var(--kit-secondary,var(--reading-lineup-secondary))}
.reading-kit-shirt .kit-trim{fill:none;stroke:#fff;stroke-width:2}
.reading-kit-player.is-goalkeeper .kit-body{fill:#e1b75d}
.reading-kit-player.is-goalkeeper .kit-panel{fill:#3e4937}
.reading-horizontal-field .reading-kit-player strong{box-sizing:border-box;width:100%;min-height:2.5em;padding:2px;color:#fff;font-size:12px;font-weight:650;line-height:1.25;overflow-wrap:anywhere;text-align:center;text-shadow:0 1px 3px #071e18}
.reading-field-scroll-hint{margin:8px 0;color:var(--glass-dark-text);font-size:12px;line-height:1.5}
@media(min-width:1280px){.reading-field-scroll-hint{display:none}}
@media(max-width:600px){.reading-dual-lineup>header{font-size:14px}.reading-dual-lineup>header,.reading-dual-lineup>footer{gap:12px}.reading-dual-lineup>header>div{align-content:start;flex-direction:column;align-items:flex-start;gap:4px}.reading-dual-lineup>header>div:last-child{align-items:flex-end}}

css/page-background.css:
/* Continuous token-driven canvas. The static competition marker selects the
   Champions theme before application modules or loading placeholders render. */
body,body[data-page="champions"]{
  --site-page-background:var(--ds-page-background);
  background-color:var(--ds-color-page);
  background-image:var(--site-page-background);
  background-repeat:no-repeat;
  background-attachment:fixed;
}
/* Retire the previous blue/gold veil and Champions dotted canvas only. */
body::before,body[data-page="champions"]::before{content:none}

