css/players.css:
/* players.css - modulo del sistema grafico condiviso. */
.squad-table td small{display:block;color:var(--muted,#667085)}

.squad-table .player-open{display:flex;align-items:center;gap:10px;min-width:205px;padding:0;border:0;background:transparent;color:inherit;text-align:left;cursor:pointer}

.squad-table .player-open:hover strong,.squad-table .player-open:focus-visible strong{text-decoration:underline}

.player-detail{width:min(980px,calc(100% - 32px));max-height:90vh;padding:0;border:0;border-radius:20px;background:var(--card,#fff);color:inherit;box-shadow:0 24px 70px rgba(0,0,0,.28)}

