.squad-table th:first-child,.squad-table td:first-child{text-align:left}

.squad-table thead th[rowspan]{vertical-align:middle}

.squad-table thead th[colspan]{border-left:1px solid var(--line);text-align:center}

.squad-table thead tr:nth-child(2) th{padding-top:6px;padding-bottom:8px;text-align:center;font-size:.68rem}

