.squad-leaders+.squad-leaders{margin-top:18px}

.squad-leaders-header{position:relative}

.squad-leaders-heading{display:flex;justify-content:space-between;gap:24px;align-items:end;margin-bottom:16px}

.squad-leaders-header .squad-leaders-heading{margin-bottom:0}

.squad-leaders-heading>span:first-child{display:grid;gap:3px}

.squad-leaders-heading>span:first-child>strong{font-family:"Anton",sans-serif;font-size:clamp(1.35rem,2.5vw,1.85rem);font-weight:400;letter-spacing:.01em}

.squad-leaders-heading>span:last-child{padding:6px 10px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:.72rem;font-weight:800;white-space:nowrap}

.squad-leaders-heading h3{margin:0;font-size:clamp(1.35rem,2.5vw,1.85rem)}

.squad-leaders-heading p:last-child{max-width:520px;margin:0;color:var(--muted);font-size:.88rem}

.squad-leaders-content{margin-top:16px;padding-top:16px;border-top:1px solid var(--line)}

.squad-leaders-content>p{max-width:760px;margin:0 0 16px;color:var(--muted);font-size:.88rem}

.squad-leader-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}

.squad-leader-card{padding:16px;border:1px solid var(--line);border-radius:14px;background:linear-gradient(145deg,rgba(23,79,165,.2),var(--surface));box-shadow:0 10px 24px rgba(0,7,31,.18)}

.squad-leader-card header{display:flex;justify-content:space-between;gap:12px;align-items:center;padding-bottom:11px;border-bottom:1px solid var(--line)}

.squad-leader-card h4{margin:0;color:#fff;font-size:1rem}

.squad-leader-card header span{color:var(--muted);font-size:.68rem;font-weight:900;text-transform:uppercase}

.squad-leader-card ol{margin:10px 0 0;padding:0;list-style:none}

.squad-leader-card li{display:grid;grid-template-columns:28px minmax(0,1fr) auto;gap:8px;align-items:center;padding:9px 0;border-bottom:1px solid rgba(65,104,165,.38)}

.squad-leader-card li:last-child{border:0;padding-bottom:0}

.leader-rank{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:rgba(65,104,165,.32);color:#dce8ff;font-size:.72rem;font-weight:900}

.squad-leader-card li:first-child .leader-rank{background:rgba(229,185,79,.2);color:#ffe59a}

.leader-player{overflow:hidden;padding:0;border:0;background:transparent;color:var(--text);font:inherit;font-weight:800;text-align:left;text-overflow:ellipsis;white-space:nowrap;cursor:pointer}

.leader-player:hover,.leader-player:focus-visible{color:#ffe59a;text-decoration:underline}

.squad-leader-card li>strong{text-align:right;color:#fff;font-size:1.05rem}

.squad-leader-card li>strong small{display:block;color:var(--muted);font-size:.68rem;font-weight:700}

.leader-player-unlinked{cursor:default}

.leader-player-unlinked small{display:block;margin-top:2px;color:var(--muted);font-size:.62rem;font-weight:750;text-transform:uppercase}

.global-player-leaders{margin-top:72px;padding-top:38px;border-top:1px solid var(--line)}

.global-player-leaders-heading{display:flex;align-items:end;justify-content:space-between;gap:28px;margin-bottom:20px}

.global-player-leaders-heading h2{margin-bottom:0}

.global-player-leaders-heading>p{max-width:560px;margin:0;color:var(--muted)}

.global-leaderboard-controls{display:grid;gap:8px;margin-bottom:12px;padding:10px 12px;border:1px solid var(--line);border-radius:11px;background:linear-gradient(145deg,rgba(23,79,165,.22),var(--surface))}

.global-leaderboard-caption{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 2px 10px}

.global-leaderboard-caption strong{color:#fff;font-size:1.08rem}

.global-leaderboard-caption span,.global-leaderboard-note{color:var(--muted);font-size:.8rem}

.global-player-table{width:100%;min-width:980px;table-layout:fixed}

.global-player-table .global-col-rank{width:54px}

.global-player-table .global-col-player{width:28%}

.global-player-table .global-col-team{width:17%}

.global-player-table .global-col-appearances{width:68px}

.global-player-table .global-col-minutes{width:86px}

.global-player-table .global-col-value{width:180px}

.global-player-table .global-col-rate{width:170px}

.global-player-table th:first-child,.global-player-table td:first-child{text-align:center}

.global-player-table th:nth-child(2),.global-player-table td:nth-child(2),.global-player-table th:nth-child(3),.global-player-table td:nth-child(3){text-align:left}

.global-player-table tbody tr:hover{background:rgba(23,79,165,.2)}

.global-leader-rank{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:50%;background:rgba(65,104,165,.32);color:#dce8ff;font-size:.75rem;font-weight:900}

.global-player-table tr:first-child .global-leader-rank{background:rgba(229,185,79,.22);color:#ffe59a}

.global-leader-player{display:block;min-width:0;color:var(--text);text-decoration:none}

.global-leader-player>span{display:flex;align-items:center;min-width:0;gap:7px}

.global-leader-player>span>strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

.global-leader-player:hover strong,.global-leader-player:focus-visible strong{color:#ffe59a;text-decoration:underline}

.global-leader-player small{display:block;color:var(--muted);font-size:.7rem}

.serie-b-marker{display:inline-flex;flex:0 0 auto;padding:2px 6px;border:1px solid rgba(244,207,114,.45);border-radius:999px;background:rgba(229,185,79,.12);color:#ffe59a;font-size:.62rem;font-weight:900;white-space:nowrap}

.global-leader-value{color:#ffe59a;font-size:1rem}

.global-leader-rate{color:#dce8ff;font-size:.92rem}

.global-leaderboard-note{margin:12px 2px 0}

.referee-card,.objective-card,.squad-leader-card{transition:border-color .18s ease,transform .18s ease}

.referee-card:hover,.objective-card:hover,.squad-leader-card:hover{border-color:var(--line-strong);transform:translateY(-2px)}

.card,.home-next,.home-rail a,.day-nav,.referee-controls,.editorial-empty,.cup-stage,.objective-card,.squad-leader-card,.pilot-section{border-color:rgba(255,255,255,.1);background:linear-gradient(145deg,rgba(255,255,255,.075),rgba(255,255,255,.035));box-shadow:inset 0 1px rgba(255,255,255,.055),0 16px 46px rgba(0,0,0,.16);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)}

.team-stat-grid article,.player-bio-grid>div,.player-stat-grid article{border-color:rgba(255,255,255,.095);background:rgba(255,255,255,.045);box-shadow:inset 0 1px rgba(255,255,255,.035)}

.objective-card,.player-detail{border-radius:24px}

.squad-table thead th{background:#edf2f8}

.squad-table th:first-child,.squad-table td:first-child{background:#f8f9fb}

.season-overview strong,.squad-leader-card h4,.squad-leader-card li>strong,.objective-metric strong,.global-leaderboard-caption strong{color:#172033}

.leader-rank{background:rgba(20,89,166,.1);color:#1459a6}

.squad-leader-card li:first-child .leader-rank{background:rgba(167,116,22,.13);color:#8a5d0d}

.leader-player:hover,.leader-player:focus-visible,.global-leader-player:hover strong,.global-leader-player:focus-visible strong{color:#0d559f}

.global-leaderboard-controls{border-color:rgba(18,64,119,.1);background:rgba(255,255,255,.58)}

.global-leader-value{color:#8a5d0d}

.global-leader-rate{color:#174f91}

.serie-b-marker{border-color:rgba(167,116,22,.25);background:rgba(167,116,22,.08);color:#865a0d}

.player-detail,.player-detail-close{background:#f5f5f5;color:#172033}

.card p,.home-rail small,.objective-card p,.squad-leader-card span,.lineup-day>span,.lineup-day>small{color:var(--glass-muted)}

.table-wrap,.squad-table-wrap{
  border-color:var(--glass-border);
  background:rgba(255,255,255,.48);
  box-shadow:0 8px 4px #0000000d,0 22px 28px #0000000a,inset 0 1px 4px #ffffff8a;
  backdrop-filter:blur(18px);
  -webkit-backdrop-filter:blur(18px);
}

.squad-table thead th,.squad-table th:first-child,.squad-table td:first-child{background:rgba(247,253,253,.9)}

.objective-metric strong,.season-overview strong,.squad-leader-card h4,.squad-leader-card li>strong,.global-leaderboard-caption strong{color:var(--glass-text)}

.player-detail,.player-detail-close{border-color:var(--glass-border);background:#f4f7f7;color:var(--glass-text)}

.player-detail::backdrop{background:rgba(40,58,59,.42)}

.squad-table tbody tr:hover td:first-child,
.squad-table tbody tr:focus-within td:first-child{
  background:rgba(224,250,250,.96);
  box-shadow:8px 0 14px -10px rgba(40,58,59,.28);
}

.prediction-player-market{margin-top:14px;padding:16px;border:1px solid rgba(36,90,120,.12);border-radius:16px;background:rgba(255,255,255,.54)}

.prediction-player-market p{margin:5px 0 0;color:var(--muted);font-size:11px}

.probable-lineup-player{display:grid;justify-items:center;min-width:0;color:#fff;text-align:center}

.probable-lineup-player strong{max-width:125px;margin-top:7px;padding:6px 10px;border:1px solid rgba(255,255,255,.18);border-radius:10px;background:rgba(4,20,15,.82);box-shadow:0 7px 18px rgba(0,0,0,.22);font-size:.78rem;line-height:1.1}

.probable-lineup-player strong{color:#fff}

/* Top 15 calciatori: blocco unico, gerarchia e spaziature coordinate al sistema glass. */
.global-player-leaders{
  margin-top:72px;
  padding:30px;
  overflow:hidden;
  border:1px solid var(--glass-border);
  border-radius:28px;
  background:linear-gradient(118deg,rgba(255,255,255,.5),transparent 40%),linear-gradient(300deg,rgba(225,246,249,.32),transparent 58%),rgba(247,250,250,.5);
  box-shadow:0 8px 4px #0000000d,0 26px 42px rgba(32,49,73,.08),inset 0 1px 4px #ffffffa8;
  backdrop-filter:blur(20px) saturate(125%);
  -webkit-backdrop-filter:blur(20px) saturate(125%);
}

.global-player-leaders-heading{
  align-items:center;
  margin:0 0 22px;
  padding-bottom:22px;
  border-bottom:1px solid rgba(40,58,59,.11);
}

.global-player-leaders-heading h2{margin:0;line-height:1.08}

.global-player-leaders-heading>p{max-width:520px;font-size:.92rem;line-height:1.55}

.global-leaderboard-controls{
  margin:0;
  padding:12px 14px;
  border-radius:16px;
  box-shadow:inset 0 1px 3px #ffffff9c;
}

.global-period-group{padding-bottom:11px;border-bottom:1px solid rgba(40,58,59,.1)}

.global-period-button{border-color:rgba(167,116,22,.26);background:rgba(255,248,232,.46);color:#7a5718}

#global-player-leaderboard{margin-top:14px}

.global-leaderboard-caption{
  margin:0;
  padding:14px 16px;
  border:1px solid var(--glass-border);
  border-bottom:0;
  border-radius:18px 18px 0 0;
  background:rgba(255,255,255,.5);
  box-shadow:inset 0 1px 3px #ffffffa8;
}

.global-leaderboard-caption strong{font-size:1rem;letter-spacing:.01em}

.global-leaderboard-caption span{text-align:right}

#global-player-leaderboard .table-wrap{
  border-radius:0 0 18px 18px;
  box-shadow:0 14px 28px rgba(32,49,73,.07),inset 0 1px 3px #ffffff8a;
}

.global-player-table th{padding-top:13px;padding-bottom:13px;letter-spacing:.06em}

.global-player-table td{padding-top:14px;padding-bottom:14px}

.global-player-table tbody tr:nth-child(-n+3) td:first-child{background:rgba(255,247,226,.34)}

.global-player-table tr:nth-child(2) .global-leader-rank{background:rgba(36,90,120,.13);color:#365f78}

.global-player-table tr:nth-child(3) .global-leader-rank{background:rgba(167,116,22,.11);color:#8a641f}

.global-leader-player strong{font-size:.94rem}

.global-leader-player small{margin-top:2px}

.global-leaderboard-note{
  margin:14px 0 0;
  padding:11px 14px;
  border-left:3px solid rgba(167,116,22,.48);
  border-radius:0 12px 12px 0;
  background:rgba(255,255,255,.3);
  line-height:1.5;
}
.player-comparator{margin-top:28px;padding:26px;border:1px solid rgba(24,75,102,.14);border-radius:22px;background:linear-gradient(145deg,#f9fdff,#eaf5f7);box-shadow:0 18px 46px rgba(14,49,67,.08)}
.player-comparator>header{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:18px}.player-comparator>header h2{margin:3px 0 0}.player-comparator>header>p{max-width:460px;margin:0;color:var(--muted);font-size:12px;line-height:1.55}
.player-comparator-controls{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.team-player-comparator .player-comparator-controls{grid-template-columns:repeat(2,minmax(0,1fr))}
.player-comparator-controls label{display:grid;align-content:start;gap:7px;color:#36596a;font-size:11px;font-weight:900;letter-spacing:.06em;text-transform:uppercase}.player-comparator-controls select,.player-comparator-controls input{width:100%;min-height:44px;padding:11px 12px;border:1px solid #7897a6;border-radius:11px;background:#fff;color:#102f3f;font:700 13px Inter,sans-serif}.player-comparator-controls input::placeholder{color:#607d8b;opacity:1}.player-comparator-controls select:focus-visible,.player-comparator-controls input:focus-visible{outline:3px solid rgba(9,105,130,.28);outline-offset:2px;border-color:#096982}.player-autocomplete{position:relative;display:block}.player-comparator-control-hint{color:#54717f;font-size:10px;font-weight:650;letter-spacing:0;line-height:1.35;text-transform:none}.player-suggestions{position:absolute;z-index:20;top:calc(100% + 6px);left:0;width:100%;max-height:272px;overflow-y:auto;padding:6px;border:1px solid #7897a6;border-radius:12px;background:#fff;box-shadow:0 16px 34px rgba(10,45,61,.2)}.player-suggestions[hidden]{display:none}.player-suggestions button{display:grid;width:100%;gap:2px;padding:10px;border:0;border-radius:8px;background:#fff;color:#163c4e;text-align:left;cursor:pointer}.player-suggestions button+button{margin-top:2px}.player-suggestions button:hover,.player-suggestions button:focus-visible,.player-suggestions button.active{outline:0;background:#123f66;color:#fff}.player-suggestions button strong{font-size:13px}.player-suggestions button small{color:#567381;font-size:10px}.player-suggestions button:hover small,.player-suggestions button:focus-visible small,.player-suggestions button.active small{color:#d8ecf5}.player-suggestions-empty{display:block;padding:12px;color:#526f7d;font-size:12px;font-weight:700;letter-spacing:0;text-transform:none}
.player-comparator-result{margin-top:16px}.player-comparator-head{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:12px}.player-comparator-head article{padding:16px;border-radius:15px;background:#123f66;color:#fff}.player-comparator-head h3{margin:0;color:#fff;font-size:18px}.player-comparator-head p{margin:4px 0;color:#d7edf6;font-size:11px}.player-comparator-head strong{color:#fff;font-size:11px}
.player-comparator table{width:100%;border-collapse:collapse;background:#fff}.player-comparator th,.player-comparator td{padding:11px;border-bottom:1px solid rgba(24,75,102,.11);text-align:left}.player-comparator td strong,.player-comparator td small{display:block}.player-comparator td small{margin-top:3px;color:var(--muted);font-size:10px}
@media(max-width:700px){.player-comparator{padding:20px 14px}.player-comparator>header{align-items:flex-start;flex-direction:column}.player-comparator-controls,.team-player-comparator .player-comparator-controls{grid-template-columns:1fr}.player-comparator-head{grid-template-columns:1fr 1fr}.player-comparator table{min-width:560px}}
/* Statistiche squadre: superfici esplicite, senza coinvolgere le 20 card. */
body[data-page="team-stats"] :is(.player-comparator,.global-player-leaders,.global-leaderboard-controls){
 background:var(--glass-light-bg);border-color:var(--glass-light-border);color:var(--glass-light-text);
 box-shadow:var(--glass-shadow);backdrop-filter:var(--glass-blur);-webkit-backdrop-filter:var(--glass-blur);
}
body[data-page="team-stats"] .player-comparator-head article{
 background:var(--glass-dark-bg);border:1px solid var(--glass-dark-border);color:var(--glass-dark-text);
 box-shadow:var(--glass-shadow);backdrop-filter:var(--glass-blur);-webkit-backdrop-filter:var(--glass-blur);
}
body[data-page="team-stats"] .player-comparator-head :is(h3,p,strong){color:var(--glass-dark-text)}
body[data-page="team-stats"] :is(.player-comparator>header>p,.global-player-leaders-heading>p,.global-leaderboard-caption span,.global-leaderboard-note){color:#52636b}
body[data-page="team-stats"] .global-leaderboard-caption{background:rgba(255,255,255,.52);box-shadow:none}
body[data-page="team-stats"] :is(.player-comparator,.global-player-leaders) .table-wrap{
 background:rgba(255,255,255,.35);border-color:rgba(40,58,59,.14);box-shadow:0 14px 28px rgba(32,49,73,.07),inset 0 1px rgba(255,255,255,.54);
}
body[data-page="team-stats"] :is(.player-comparator table,.global-player-table){background:transparent;font-family:var(--font-body);font-variant-numeric:tabular-nums}
body[data-page="team-stats"] :is(.player-comparator,.global-player-table) :is(th,td){border-bottom:1px solid rgba(40,58,59,.1)}
body[data-page="team-stats"] :is(.player-comparator,.global-player-table) thead th{background:rgba(255,255,255,.52);color:#47575a;font-size:11px;font-weight:650;letter-spacing:.06em;text-transform:uppercase}
body[data-page="team-stats"] .player-comparator tbody th{background:transparent;color:#47575a;font-weight:650}
body[data-page="team-stats"] :is(.player-comparator,.global-player-table) tbody tr:nth-child(even){background:rgba(20,43,59,.025)}
body[data-page="team-stats"] :is(.player-comparator,.global-player-table) tbody tr:hover{background:rgba(181,250,255,.34)}
body[data-page="team-stats"] .player-comparator :is(th,td):nth-child(n+2){text-align:right}
body[data-page="team-stats"] .global-player-table :is(th,td):nth-child(n+4){text-align:center}
body[data-page="team-stats"] .global-leader-player strong{font-family:var(--font-body);font-size:14px;font-weight:800}
body[data-page="team-stats"] .global-player-leaders .global-stat-button{
 min-height:36px;padding:8px 16px;border:1px solid var(--glass-light-border);border-radius:999px;
 background:var(--glass-light-bg);color:var(--glass-light-text);box-shadow:var(--glass-shadow);
 backdrop-filter:var(--glass-blur);-webkit-backdrop-filter:var(--glass-blur);
 font-size:.86rem;line-height:1.2;font-weight:700;transform:none;
 transition:background-color .2s ease,box-shadow .2s ease,color .2s ease;
}
body[data-page="team-stats"] .global-player-leaders .global-stat-button:hover{background-color:#e0ebf0;color:#152e42;transform:none}
body[data-page="team-stats"] .global-player-leaders .global-stat-button.active{background:var(--glass-dark-bg);border-color:var(--glass-dark-border);color:var(--glass-dark-text)}
body[data-page="team-stats"] .global-stat-group>div{display:flex;flex-wrap:wrap;gap:8px}
@media(prefers-reduced-motion:reduce){body[data-page="team-stats"] .global-player-leaders .global-stat-button{transition:none}}
/* Posizioni leggibili sulle righe chiare, preservando le tinte delle medaglie. */
body[data-page="team-stats"] .global-leader-rank{color:#294b61}
body[data-page="team-stats"] .global-player-table tr:first-child .global-leader-rank{color:#78520f}

css/reading-detail.css:
/* Shared reading presentation, isolated from calendars and the betslip. */
.rd-shell .rd-h2h-count{margin:0 0 12px;font-size:11px;color:var(--rd-muted)}
.rd-shell .rd-h2h-timeline{list-style:none;margin:0;padding:0 0 0 18px;border-left:1px solid var(--rd-line)}
.rd-shell .rd-h2h-timeline>li{position:relative;padding:0;margin:0}
.rd-shell .rd-h2h-timeline>li::before{content:"";position:absolute;left:-22px;top:22px;width:7px;height:7px;border:1px solid var(--rd-line);border-radius:50%;background:var(--rd-bg)}
.rd-shell .rd-h2h-timeline>li:first-child::before{background:var(--rd-accent);border-color:var(--rd-accent)}
.rd-shell .rd-h2h-meeting{margin:0;padding:0;border:0;border-bottom:1px solid var(--rd-line);border-radius:0;background:none;box-shadow:none;min-width:0}
.rd-shell .rd-h2h-meeting>summary{display:block;list-style:none;padding:12px 8px;cursor:pointer;min-width:0;color:var(--rd-ink);background:none}
.rd-shell .rd-h2h-meeting>summary::-webkit-details-marker{display:none}
.rd-shell .rd-h2h-meeting>summary::marker{content:""}
.rd-shell .rd-h2h-meeting>summary:focus-visible{outline:2px solid var(--rd-accent);outline-offset:2px}
.rd-shell .rd-h2h-meeting.is-latest>summary{background:color-mix(in srgb,var(--rd-accent) 5%,transparent)}
.rd-shell .rd-h2h-meta{display:flex;align-items:baseline;gap:8px;font-size:10px;line-height:1.4;color:var(--rd-muted);margin-bottom:7px}
.rd-h2h-meta>time{flex-shrink:0;font-variant-numeric:tabular-nums}
.rd-h2h-meta>span{flex:1;min-width:0;overflow-wrap:anywhere}
.rd-shell .rd-h2h-meta>small{font-size:9px;color:var(--rd-accent);white-space:nowrap}
.rd-h2h-toggle{width:12px;flex-shrink:0;font-style:normal;text-align:center;color:var(--rd-muted)}
.rd-h2h-toggle::before{content:"+"}.rd-h2h-meeting[open] .rd-h2h-toggle::before{content:"−"}
.rd-shell .rd-h2h-scoreline{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:16px}
.rd-shell .rd-h2h-scoreline>span{font-size:14px;font-weight:600;line-height:1.35;min-width:0;overflow-wrap:anywhere}
.rd-h2h-home{text-align:left}.rd-h2h-away{text-align:right}
.rd-shell .rd-h2h-scoreline>b{display:flex;align-items:center;gap:7px;font-size:24px;line-height:1.2;font-weight:750;font-variant-numeric:tabular-nums;white-space:nowrap}
