.rd-shell [data-metric-mode=shots] .rd-row-shot,.rd-shell [data-metric-mode=sot] .rd-row-sot{color:var(--rd-accent)}
.rd-shell .rd-player-expanded{font-size:12px;line-height:1.65;padding:2px 0 12px;min-width:0;overflow-wrap:anywhere}
.rd-shell .rd-player-expanded .rd-player-role{color:var(--rd-muted);font-size:11px;margin:5px 0}
.rd-shell .rd-player-expanded .rd-player-kpis{gap:8px;margin:12px 0}
.rd-shell .rd-player-expanded .rd-metric dd{font-size:17px}
.rd-shell .rd-player-expanded .rd-player-probabilities{flex-wrap:wrap;gap:4px 12px;padding-top:8px}
.rd-shell .rd-player-expanded .rd-record>div{grid-template-columns:1fr;gap:2px}
.rd-shell .rd-player-expanded .rd-record{font-size:11px}
@media(max-width:767px){
 .rd-shell .rd-player-columns{gap:14px}
 .rd-shell #lettura-giocatori .rd-player-toolbar{gap:8px}
 .rd-shell .rd-player-team-name{font-size:14px;padding:7px 0 10px;min-height:36px}
 .rd-shell .rd-player-column-labels{grid-template-columns:minmax(0,1fr) 24px 24px;gap:4px;padding-right:13px;font-size:9px}
 .rd-shell .rd-player-row>summary{grid-template-columns:17px minmax(0,1fr) 24px 24px 9px;gap:4px;min-height:38px;padding:6px 0}
 .rd-shell .rd-row-identity h3{font-size:11px;line-height:1.4}
 .rd-shell .rd-row-number{font-size:9px}
 .rd-shell :is(.rd-row-shot,.rd-row-sot){font-size:12px}
 .rd-shell .rd-row-chevron{font-size:11px}
 .rd-shell .rd-compact-outsider{font-size:8px}
 .rd-shell .rd-player-expanded .rd-player-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}
 .rd-shell .rd-player-expanded .rd-metric dd{font-size:15px}
 .rd-shell .rd-player-expanded :is(.rd-footnote,.rd-empty){font-size:11px}
 .rd-shell .rd-player-expanded .rd-empty{padding:6px 8px}
 .rd-shell .rd-player-expanded .rd-player-links button{padding:7px;font-size:11px;overflow-wrap:anywhere}
}

.rd-shell .rd-form-chart{display:block;width:100%;height:auto;max-height:200px}
.rd-shell .rd-recent-form{margin-top:28px}

/* The remaining booking panel sits directly in the discipline section. */
.rd-shell #lettura-disciplina .prediction-booked-panel{margin-top:0}

/* A theme-aware green keeps the new home foul bar readable on both canvases. */
body[data-reading-detail-theme]{--rd-fouls-home:#126451}
body[data-reading-detail-theme="champions"]{--rd-fouls-home:#78d6ac}
.rd-shell .rd-diverging-row[data-statistic="fouls"]{--rd-home:var(--rd-fouls-home)}
/* Shared referee dashboard: proportions follow the supplied reference at the existing 1050px width. */
.rd-shell .rf-panel{padding:0!important;border:0!important;background:none!important;margin:0 0 32px!important;box-shadow:none!important}
.rf-dashboard{--rf-yellow:#e6b500;--rf-red:#dc262c;--rf-green:#00856b;--rf-blue:#213e50;color:var(--rd-ink);font-size:12px;line-height:1.5;min-width:0}
body[data-reading-detail-theme="champions"] .rf-dashboard{--rf-blue:#9ac5ee;--rf-green:#46c6a0}
.rf-dashboard .rf-card{border:1px solid var(--rd-line);border-radius:15px;background:color-mix(in srgb,var(--rd-surface) 65%,transparent);padding:20px;min-width:0;box-shadow:none}
.rf-dashboard :is(h3,h4,p,dl,dd){margin:0}
.rf-dashboard .rf-heading,.rf-dashboard h4{font:750 12px/1.4 Inter,system-ui,sans-serif;letter-spacing:.08em;text-transform:uppercase;color:var(--rd-ink)}
.rf-dashboard .rf-heading{margin:0 0 13px;color:var(--rd-muted)}
.rf-dashboard .rf-designation{display:grid;grid-template-columns:minmax(0,62fr) minmax(0,38fr);padding:22px 26px;margin-bottom:12px;gap:26px}
.rf-identity{display:grid;grid-template-columns:130px minmax(0,1fr);align-items:center;gap:22px;min-width:0}
.rf-identity>svg{width:130px;max-width:100%;height:120px;color:var(--rd-ink)}
.rf-label,.rf-crew dt{font-size:11px;letter-spacing:.07em;font-weight:650;text-transform:uppercase;color:var(--rd-muted)}
.rf-dashboard .rf-identity h3{font:800 32px/1.15 Inter,system-ui,sans-serif;letter-spacing:-.025em;margin:5px 0 10px;overflow-wrap:anywhere}
.rf-dashboard .rf-season{border-top:1px solid var(--rd-line);padding-top:10px;margin-top:12px;color:var(--rd-muted);font-size:12px}
.rf-crew{display:grid;gap:13px;align-content:center;border-left:1px solid var(--rd-line);padding-left:30px;min-width:0}
.rf-crew>div{display:grid;grid-template-columns:100px minmax(0,1fr);gap:10px;align-items:baseline}
.rf-crew dd{font-size:14px;overflow-wrap:anywhere}
.rf-dashboard .rf-indicators{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;margin-bottom:12px;padding:20px 0}
.rf-indicator{padding:0 25px;display:grid;gap:5px;min-width:0}
.rf-indicator+.rf-indicator{border-left:1px solid var(--rd-line)}
.rf-indicator strong{font-size:29px;line-height:1.2;font-weight:800;letter-spacing:-.02em}
.rf-indicator>span{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--rd-muted);font-weight:700}
.rf-dashboard small{font-size:10px;color:var(--rd-muted)}
.rf-bar{height:7px;border-radius:3px;background:var(--rd-soft);overflow:hidden;margin:3px 0}
.rf-bar i{display:block;height:100%;border-radius:3px;background:var(--rf-color)}
.rf-yellow{--rf-color:var(--rf-yellow)}.rf-red{--rf-color:var(--rf-red)}.rf-green{--rf-color:var(--rf-green)}.rf-blue{--rf-color:var(--rf-blue)}
.rf-lower{display:grid;grid-template-columns:minmax(0,65fr) minmax(0,35fr);gap:12px;align-items:start}
.rf-dashboard .rf-history{padding:17px 15px;align-self:stretch}
.rf-dashboard .rf-history h4{margin:0 0 15px}
.rf-table-scroll{max-width:100%;overflow-x:auto;overscroll-behavior-x:contain}
.rf-dashboard table{border-collapse:collapse;width:100%;min-width:570px;table-layout:auto;font-size:10px;background:none;margin:0}
.rf-dashboard :is(th,td){padding:12px 4px;border:0;border-bottom:1px solid var(--rd-line);background:none!important;color:var(--rd-ink);vertical-align:middle;text-align:center;white-space:nowrap}
.rf-dashboard th{font-size:9px;font-weight:600;letter-spacing:.04em;color:var(--rd-muted);text-transform:uppercase}
.rf-dashboard :is(th,td):nth-child(-n+3){text-align:left}
.rf-dashboard td:nth-child(2){white-space:normal;max-width:80px;font-size:9px}
.rf-dashboard td small{display:block;font-size:8px;white-space:nowrap}
.rf-match{display:grid;grid-template-columns:minmax(65px,1fr) 35px minmax(65px,1fr);gap:5px;align-items:center;min-width:190px}
.rf-match>span{display:flex;align-items:center;gap:4px;white-space:normal;line-height:1.3;min-width:0}
.rf-match img{width:22px;height:25px;object-fit:contain;flex-shrink:0}
.rf-match b{text-align:center;font-size:11px;white-space:nowrap}
.rf-dashboard .rf-average-card{background:color-mix(in srgb,var(--rd-soft) 65%,transparent);padding:17px 19px}
.rf-averages+ .rf-averages{border-top:1px solid var(--rd-line);margin-top:15px;padding-top:14px}
.rf-dashboard .rf-averages h4{font-size:10px;letter-spacing:.04em;margin-bottom:12px}
.rf-averages dl{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}
.rf-averages dd{font-size:22px;line-height:1.25;font-weight:800}
.rf-averages dt{font-size:8px;letter-spacing:.04em;text-transform:uppercase;color:var(--rd-muted);margin:4px 0}
.rf-averages small{display:block;font-size:8px;line-height:1.5}
.rf-dashboard .rf-note{font-size:9px;line-height:1.6;color:var(--rd-muted);margin-top:11px}
.rf-dashboard .rf-empty{color:var(--rd-muted);padding:24px 0}
.rf-dashboard .rf-historical{margin-top:12px}
.rf-historical .reading-referee-stats{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr))!important;gap:14px!important;margin-top:12px!important;padding:0!important;background:none!important;border:0!important}
.rf-historical .reading-referee-stats article{padding:0!important;border:0!important;background:none!important;box-shadow:none!important}
.rf-historical .reading-referee-stats strong{display:block;color:var(--rd-ink)!important;font-size:18px!important}
.rf-historical .reading-referee-stats :is(span,small){color:var(--rd-muted)!important;font-size:10px!important}
@media(max-width:1000px){.rf-dashboard .rf-designation{padding:20px;gap:20px}.rf-identity{grid-template-columns:90px minmax(0,1fr);gap:15px}.rf-identity>svg{width:90px}.rf-dashboard .rf-identity h3{font-size:27px}.rf-crew{padding-left:20px}.rf-crew>div{grid-template-columns:80px minmax(0,1fr)}.rf-crew dd{font-size:12px}.rf-lower{grid-template-columns:1fr}.rf-match{min-width:220px}}
@media(max-width:600px){.rf-dashboard .rf-designation{grid-template-columns:1fr;padding:20px;gap:18px}.rf-identity{grid-template-columns:70px minmax(0,1fr);gap:15px}.rf-identity>svg{width:70px;height:85px}.rf-dashboard .rf-identity h3{font-size:25px}.rf-crew{border-left:0;border-top:1px solid var(--rd-line);padding:16px 0 0;gap:10px}.rf-crew>div{grid-template-columns:95px minmax(0,1fr)}.rf-dashboard .rf-indicators{grid-template-columns:repeat(2,minmax(0,1fr));padding:0}.rf-indicator{padding:18px}.rf-indicator:nth-child(3){border-left:0}.rf-indicator:nth-child(n+3){border-top:1px solid var(--rd-line)}.rf-indicator strong{font-size:28px}.rf-indicator>span{font-size:9px}.rf-dashboard .rf-history{padding:17px 12px}.rf-historical .reading-referee-stats{grid-template-columns:repeat(2,minmax(0,1fr))!important}.rf-averages dd{font-size:23px}}
/* Neutralize legacy designation rules only inside the shared dashboard. */
.rd-shell .rf-dashboard dl>div{padding:0;border:0;border-radius:0;background:none}
.rd-shell .rf-dashboard .rf-crew{grid-template-columns:minmax(0,1fr);margin:0}
.rd-shell .rf-dashboard dt{color:var(--rd-muted);font-weight:600}
.rd-shell .rf-dashboard dd{margin:0;color:var(--rd-ink)}
.rd-shell .rf-dashboard .rf-crew dd{font-size:14px;font-weight:450}
.rd-shell .rf-dashboard .rf-averages dd{font-size:22px;font-weight:800}
.rd-shell .rf-dashboard .rf-averages dt{font-size:8px;letter-spacing:.04em;margin:4px 0}
/* Match the reference's strong referee name despite the shared display-heading reset. */
.rd-shell .rf-dashboard .rf-identity h3{font-weight:800!important;letter-spacing:-.025em!important}
.rd-shell .rf-dashboard .rf-heading{font-weight:750!important;letter-spacing:.08em!important}
.rd-shell .rf-dashboard th{background:transparent!important}
/* Compact, readable text at the site's narrower 1050px canvas. */
.rd-shell .rf-dashboard table{font-size:12px;min-width:600px}
.rd-shell .rf-dashboard td:nth-child(2){font-size:10px}
.rd-shell .rf-dashboard .rf-match b{font-size:12px}
.rd-shell .rf-dashboard .rf-averages :is(dt,small){font-size:9px}
.rd-shell .rf-dashboard thead{background:transparent!important}
/* Lineup state belongs to each existing player row, including when filters are off. */
.rd-shell .rd-row-lineup{display:block;font-size:9px;line-height:1.3;color:var(--rd-muted);font-weight:450}
@media(max-width:600px){.rd-shell .rd-row-lineup{font-size:8px}}
/* The shared card rule above has !important and :is() takes the specificity of
   its deepest selector. Override only Discipline's outer wrappers; transparent
   borders retain their existing box geometry and all inter-section spacing. */
.rd-shell #lettura-disciplina>.rd-section-content>:is(.prediction-booked-panel,.reading-referee-assignment.rf-panel,.champions-player-predictions){
  background:transparent!important;
  border-color:transparent!important;
  box-shadow:none!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
}

css/readings-index.css:
/* Index-only dashboard; the match analysis keeps its existing presentation. */
body:has(.readings-index) main{max-width:1050px;padding-top:30px}
.readings-index{font-family:var(--font-body);color:#10283f;padding-bottom:12px;--ri-border:rgba(86,115,143,.15)}
.readings-index *{box-sizing:border-box}
.readings-index .ri-title{margin:0 10px 28px}
.readings-index .eyebrow{color:#a44424;font-size:11px;letter-spacing:.14em;margin:0 0 6px;font-weight:700;text-transform:uppercase}
.readings-index h1,.readings-index h2,.readings-index h3{color:#0c2439;margin:0;letter-spacing:-.025em}
.readings-index h1{font-family:var(--font-body);font-size:clamp(44px,6vw,66px);line-height:1.08}
.readings-index h2{font-family:var(--font-body);font-size:34px;line-height:1.15}
.readings-index :is(.ri-archive,.ri-future){border:1px solid var(--ri-border);border-radius:23px;padding:20px;margin-bottom:25px;background:linear-gradient(125deg,rgba(255,255,255,.77),rgba(240,249,255,.5),rgba(255,249,247,.55));box-shadow:0 8px 24px #18374c06}
.readings-index .ri-current{margin-bottom:25px}
.readings-index .ri-heading{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:17px}
.readings-index .ri-heading-line{display:flex;align-items:center;gap:14px;flex-wrap:wrap;min-width:0}
.readings-index .ri-badge{font:500 11px/1.3 var(--font-body);padding:5px 13px;border-radius:20px;background:#e0edfc;color:#15334e;white-space:nowrap}
.readings-index .ri-range{color:#60778b;font-size:11px;line-height:1.5}
.readings-index .ri-matches{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}
.readings-index .ri-match{display:flex;flex-direction:column;min-width:0;padding:13px 11px;border:1px solid var(--ri-border);border-radius:15px;text-decoration:none;color:inherit;transition:box-shadow .18s,transform .18s}
.readings-index .ri-match:hover{transform:translateY(-2px);box-shadow:0 7px 18px #253c5014}
.readings-index .ri-date{font-size:10px;letter-spacing:.06em;color:#516a7d;font-weight:650;min-height:25px}
.readings-index .ri-teams{display:grid;grid-template-columns:minmax(0,1fr) 50px minmax(0,1fr);align-items:center;gap:4px;flex:1;padding:7px 0 12px;text-align:center}
.readings-index .ri-teams>.team-with-logo{display:flex;flex-direction:column;gap:6px;min-width:0}
.readings-index .ri-teams .team-logo{width:60px;height:60px;min-width:0;background:none;box-shadow:none;border:0}
.readings-index .ri-teams .team-logo img{width:100%;height:100%;object-fit:contain}
.readings-index .ri-teams .team-name{font-size:12px;font-weight:600;white-space:normal;overflow-wrap:anywhere}
.readings-index .ri-teams>b{font-size:12px;color:#526a80}
.readings-index .ri-finished .ri-teams>b{font-size:23px;color:#10283f;white-space:nowrap}
.readings-index .ri-section-title{margin-bottom:16px;font-size:29px}
.readings-index .ri-round{border-bottom:1px solid var(--ri-border)}
.readings-index summary{cursor:pointer;list-style:none}
.readings-index summary::-webkit-details-marker{display:none}
.readings-index .ri-round>summary{display:flex;align-items:center;gap:12px;padding:12px 0}
.readings-index .ri-round>summary>.ri-heading-line{margin-right:auto}
.readings-index .ri-round>summary strong{font:700 19px var(--font-body)}
.readings-index .ri-chevron{font-size:22px;transition:transform .15s}
.readings-index .ri-round[open]>summary .ri-chevron{transform:rotate(180deg)}
.readings-index .ri-round[open]>summary strong{font-size:30px}
.readings-index .ri-results{grid-template-columns:repeat(2,minmax(0,1fr));gap:0 20px;padding-bottom:14px}
.readings-index .ri-compact{padding:8px 3px;border:0;border-bottom:1px solid var(--ri-border);border-radius:0;background:transparent;box-shadow:none}
.readings-index .ri-compact:hover{background:rgba(255,255,255,.45);box-shadow:none;transform:none}
.readings-index .ri-compact .ri-teams{padding:0;grid-template-columns:minmax(0,1fr) 62px minmax(0,1fr);gap:5px}
.readings-index .ri-compact .ri-teams>.team-with-logo{flex-direction:row;gap:9px;text-align:left}
.readings-index .ri-compact .ri-teams>.team-with-logo:last-child{flex-direction:row-reverse;text-align:right}
.readings-index .ri-compact .team-logo{width:28px;height:32px;flex-shrink:0}
.readings-index .ri-compact .team-name{font-size:11px}
.readings-index .ri-calendar{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:9px}
.readings-index .ri-calendar-day>summary{border:1px solid var(--ri-border);border-radius:13px;background:linear-gradient(135deg,#fff9,#f2f8fc88);text-align:center;padding:12px 3px;color:#536a7e}
.readings-index .ri-calendar-day>summary>span{display:block;text-transform:uppercase;font-size:9px;letter-spacing:.06em}
.readings-index .ri-calendar-day>summary strong{display:block;font:700 29px/1.4 var(--font-body);color:#10283f}
.readings-index .ri-calendar-day>summary small{font-size:9px}
.readings-index .ri-calendar-day[open]>summary{border-color:#acd2ff;background:#eaf4ff}
.readings-index .ri-future-panel{grid-column:1/-1;border:1px solid var(--ri-border);padding:16px;border-radius:14px;margin:3px 0 10px}
.readings-index :is(a,summary):focus-visible{outline:3px solid #589add;outline-offset:3px}
@media(max-width:1000px){.readings-index .ri-matches{grid-template-columns:repeat(2,minmax(0,1fr))}.readings-index .ri-calendar{grid-template-columns:repeat(4,minmax(0,1fr))}}
@media(max-width:600px){.readings-index :is(.ri-archive,.ri-future){padding:14px;border-radius:18px;margin-bottom:20px}.readings-index .ri-heading{align-items:flex-start;flex-direction:column;gap:8px}.readings-index h2{font-size:29px}.readings-index .ri-matches{grid-template-columns:minmax(0,1fr)}.readings-index .ri-calendar{grid-template-columns:repeat(3,minmax(0,1fr))}.readings-index .ri-round>summary{flex-wrap:wrap;gap:7px}.readings-index .ri-round>summary>.ri-range{order:3;width:100%}.readings-index .ri-round[open]>summary strong{font-size:26px}.readings-index .ri-heading-line{gap:8px}.readings-index .ri-future-panel{padding:9px}.readings-index .ri-title{margin-bottom:22px}}
.readings-index .ri-calendar-day:not([open])>.ri-future-panel{display:none}
.readings-index .ri-intro{max-width:660px;font-size:14px;line-height:1.65;color:#50687d;margin:8px 0 0}
.readings-index .ri-calendar-day{display:block;min-width:0}.readings-index .ri-calendar-day[open]{grid-column:1/-1}.readings-index .ri-calendar-day[open]>summary{max-width:120px;margin-bottom:12px}

css/responsive.css:
/* responsive.css - modulo del sistema grafico condiviso. */
@media(max-width:900px){.site-header{align-items:flex-start}.menu-button{display:block}.site-nav{display:none;position:absolute;top:74px;left:12px;right:12px;padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--surface);box-shadow:0 18px 40px #0008}.site-nav.open{display:grid;grid-template-columns:1fr 1fr}.hero{grid-template-columns:1fr}.grid{grid-template-columns:1fr 1fr}.match{grid-template-columns:1fr}}

@media(max-width:580px){main{width:min(100% - 24px,var(--max));padding-top:28px}.brand small{display:none}.hero{padding:24px}.grid,.site-nav.open{grid-template-columns:1fr}th,td{padding:10px}}

@media(max-width:760px){.match-date{max-width:54%}}

@media(max-width:580px){.match-head{display:block}.match-date{max-width:none;margin-top:8px;text-align:left}}

@media(max-width:900px){.team-nav>div{grid-template-columns:repeat(10,1fr)}}

@media(max-width:760px){.team-match-list{grid-template-columns:1fr}.team-hero-logo{justify-content:start}.team-schedule-head{align-items:flex-start;flex-direction:column}.team-matchday .match{min-height:0}}

@media(max-width:580px){.team-nav{margin-top:18px;margin-inline:-4px}.team-nav>div{display:flex;overflow-x:auto;padding-bottom:4px;scrollbar-width:thin}.team-nav-link{flex:0 0 44px;width:44px;height:44px;aspect-ratio:auto}}

@media(max-width:580px){.match.fixture-card .match-head{grid-template-columns:1fr;align-items:start}.match.fixture-card .match-date{max-width:none;text-align:left}.match.fixture-card .fixture-team{padding:8px 10px}.match.fixture-card .team-with-logo{font-size:15px}}

@media(max-width:580px){.match.fixture-card .fixture-teams{column-gap:58px;padding:22px 12px 8px}.match.fixture-card .team-logo{flex-basis:70px;width:70px;height:70px}.match.fixture-card .team-with-logo{font-size:13px}.match.fixture-card .team-name{min-height:32px}.match.fixture-card .fixture-score .score-result{min-width:40px;height:40px}.match.fixture-card .match-events{margin-inline:12px}}

@media(max-width:900px){.ranking-grid{grid-template-columns:1fr 1fr}}

@media(max-width:580px){.ranking-grid{grid-template-columns:1fr}.ranking-card li strong{float:none;display:block;margin-left:4px}}

@media(max-width:580px){.standings-switch{flex-direction:row}.standing-team{min-width:130px}}

@media(max-width:760px){body[data-page="home"] .hero{min-height:460px;background-position:68% center}}

@media(max-width:760px){.referee-grid{grid-template-columns:1fr}}

