css/site-layout.css:
/* Final shared geometry, after competition and responsive modules. */
body :is(.site-header,main,#team-squad-app,.site-footer-inner){
  width:var(--container-width);
  max-width:var(--max);
  min-width:0;
  margin-inline:auto;
}
/* Compact only the large outer spaces; keep internal fields and controls intact. */
body:not([data-page="home"]) main{padding-top:32px;padding-bottom:64px}
body:not([data-page="home"]) .site-footer{margin-top:32px}
body:not([data-page="home"]) main>.section{margin-top:68px}
body:not([data-page="home"]) main>.section>.section-heading{margin-bottom:22px}
body:not([data-page="home"]) :is(.detail-section,.subpage-header){padding-block:27px}
#team-squad-app.team-editorial>[data-editorial-section]{padding-block:20px}
body[data-page="champions"] .champions-team-summary{padding-block:22px;margin-bottom:24px}
@media(min-width:761px){
  body[data-page="champions"] .champions-team-hero{padding-block:35px}
  body[data-page="champions"] .champions-team-detail .champions-player-overview{padding-block:22px}
}
main>.table-wrap,main .table-wrap{max-width:100%;min-width:0;overflow-x:auto}
@media(max-width:760px){
  body:not([data-page="home"]) main{padding-top:24px}
  body:not([data-page="home"]) main>.section{margin-top:52px}
  #team-squad-app.team-editorial>[data-editorial-section]{padding-block:13px}
}

/* Phase 2: outer geometry and editorial typography only. Component internals,
   table scrolling, pitch coordinates and functional controls retain their CSS. */
:root{
  --page-gutter:var(--ds-page-gutter);
  --container-width:min(var(--ds-content-max),calc(100% - 2 * var(--ds-page-gutter)));
}
body :is(.site-header,main,#team-squad-app,.site-footer-inner){
  width:var(--container-width);
  max-width:var(--ds-content-max);
}
body:not([data-page="home"]) main{padding-block:var(--ds-space-6) var(--ds-space-8)}
body:not([data-page="home"]) main>.section{margin-top:var(--ds-space-8)}
body main>.section>.section-heading{margin-bottom:var(--ds-space-5)}
body[data-page="home"] main{padding-block:var(--ds-space-5) var(--ds-space-7)}
body[data-page="home"] main>.section{margin-top:var(--ds-space-7)}

/* Explicit page-title roles; match-card, player and numerical headings excluded. */
body #app>.hero h1,
body #app>.loading h1,
body #team-squad-app>.loading h1,
body #app>.reading-match-hero h1,
body #app>.readings-index>.ri-title h1,
body #app>.champions-match-report>h1,
body #team-squad-app.team-editorial>.team-detail-hero h1{
  font-family:var(--ds-font-display);
  font-size:var(--ds-title-page);
  font-weight:400;
  line-height:var(--ds-leading-title);
  overflow-wrap:anywhere;
}
body #app>.loading h1,
body #team-squad-app>.loading h1{color:var(--ds-color-text)}
/* Only the two existing flagship heroes retain a larger page title. */
body[data-page="home"] #app>.hero h1,
body[data-page="champions"] #app .champions-hero h1{
  font-family:var(--ds-font-display);
  font-size:var(--ds-title-hero);
  line-height:var(--ds-leading-title);
}
body[data-page="champions"] #app .champions-team-hero h1,
body[data-page="champions"] #app .champions-reading-hero h1{
  font-family:var(--ds-font-display);
  font-size:var(--ds-title-page);
  line-height:var(--ds-leading-title);
}

/* Editorial sections, not generic H2/H3 or technical component headers. */
body #app>.section>.section-heading h2,
body #app>.home-standings [data-standings-scope-panel]>h2,
body #app>.readings-index :is(.ri-heading-line>h2,.ri-section-title),
body #app>.global-player-leaders>.global-player-leaders-heading h2,
body #app>.player-comparator>header h2,
body #app .betting-round-heading h2,
body #team-squad-app.team-editorial>section>.team-editorial-heading h2,
body #team-squad-app.team-editorial .team-editorial-statistics>.team-season-column>.team-season-heading h2{
  font-family:var(--ds-font-display);
  font-size:var(--ds-title-section);
  font-weight:400;
  line-height:var(--ds-leading-title);
  overflow-wrap:anywhere;
}

/* Navbar: identical geometry, theme-local glass and navigation states. */
body[data-page] .site-header{
  --glass-text:var(--ds-color-text);
  --glass-color:var(--ds-color-glass);
  gap:var(--ds-space-5);
  padding:var(--ds-space-2) var(--ds-space-3);
  border-radius:var(--ds-radius-pill);
  border-color:var(--ds-color-glass-border);
  background:var(--ds-color-glass);
  box-shadow:var(--ds-shadow-card);
  font-family:var(--ds-font-body);
  backdrop-filter:var(--ds-glass-blur);
  -webkit-backdrop-filter:var(--ds-glass-blur);
}
body .site-header .page-link{
  padding:var(--ds-space-2) var(--ds-space-3);
  font-family:var(--ds-font-body);
  font-size:var(--ds-text-meta);
  font-weight:600;
  line-height:var(--ds-leading-body);
  color:var(--ds-color-text);
}
body .site-header .page-link:is(.active,:hover){
  background:var(--ds-color-surface-soft);
  border-color:var(--ds-color-border);
  color:var(--ds-color-text);
}
body .site-header .page-link:focus-visible{
  outline:2px solid var(--ds-color-focus);
  outline-offset:3px;
}
body .site-header>.menu-button{
  color:var(--ds-color-text);
  background:var(--ds-color-surface-soft);
  border-color:var(--ds-color-border);
  font-family:var(--ds-font-body);
}
body .site-footer{font-family:var(--ds-font-body)}
body .site-footer-inner{padding-block:var(--ds-space-7) var(--ds-space-5)}
body .site-footer-top{padding-bottom:var(--ds-space-7)}
body .site-footer-bottom{gap:var(--ds-space-5);padding-top:var(--ds-space-5)}

@media(max-width:900px){
  body .site-header{padding:var(--ds-space-2) var(--ds-space-3)}
  body .site-header>.site-nav{
    background:var(--ds-color-surface);
    border-color:var(--ds-color-border);
  }
  body[data-page="champions"] .site-header .site-nav.open .page-link:not(.active){color:var(--ds-color-text)}
}
@media(max-width:760px){
  body:not([data-page="home"]) main{padding-top:var(--ds-space-5)}
  body:not([data-page="home"]) main>.section{margin-top:var(--ds-space-7)}
  body .site-footer-inner{padding-top:var(--ds-space-6)}
  body .site-footer-top{padding-bottom:var(--ds-space-6)}
}

css/team.css:
/* team.css - modulo del sistema grafico condiviso. */
.team-with-logo{display:flex;align-items:center;gap:9px}

.team-logo{position:relative;display:grid;place-items:center;flex:0 0 34px;width:34px;height:34px}

.team-logo img{width:100%;height:100%;object-fit:contain}

.team-logo b{display:none}

.team-logo.fallback{border:1px solid var(--line);border-radius:50%;background:var(--surface2)}

.team-logo.fallback b{display:block;font-size:10px;color:var(--gold)}

.fixture-team{display:flex;align-items:center;gap:10px;min-width:0;padding:5px 7px;border-radius:10px}

.fixture-team:hover{background:rgba(255,255,255,.03)}

.fixture-team .team-with-logo{gap:10px;min-width:0;font-size:16px;font-weight:850}

.fixture-team .team-with-logo>span:last-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* Ricerca rapida e calendario dedicato per squadra. */
.team-nav{margin:24px 0 38px;padding:14px 16px;border:1px solid var(--line);border-radius:16px;background:linear-gradient(135deg,rgba(23,79,165,.18),rgba(12,26,22,.96))}

.team-nav>span{display:block;margin-bottom:10px;color:var(--muted);font-size:11px;font-weight:900;letter-spacing:.1em;text-transform:uppercase}

.team-nav>div{display:grid;grid-template-columns:repeat(20,minmax(0,1fr));gap:7px}

.team-nav-link{display:grid;place-items:center;aspect-ratio:1;min-width:0;padding:6px;border:1px solid transparent;border-radius:10px;background:rgba(255,255,255,.025);text-decoration:none;transition:.18s ease}

.team-nav-link:hover,.team-nav-link.active{border-color:var(--gold);background:rgba(242,193,78,.12);transform:translateY(-2px)}

.team-nav-link img{width:100%;height:100%;max-width:38px;max-height:38px;object-fit:contain}

.team-nav-link b{font-size:11px;color:var(--gold)}

.team-hero-logo{display:grid;place-items:center}

.team-hero-logo img{width:clamp(90px,12vw,150px);height:clamp(90px,12vw,150px);object-fit:contain;filter:drop-shadow(0 12px 18px #0005)}

.team-schedule-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:18px}

.team-schedule-head h2{margin:0}

.team-match-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;align-items:stretch}

.team-matchday{display:flex;flex-direction:column;min-width:0}

.team-matchday h3{margin:0;padding:10px 16px;border:1px solid var(--line);border-bottom:0;border-radius:13px 13px 0 0;background:rgba(23,79,165,.18);color:var(--gold);font-size:13px;letter-spacing:.05em;text-transform:uppercase}

.team-matchday .match{display:flex;flex:1;flex-direction:column;align-items:stretch;min-width:0;margin:0}

.team-matchday .match-head{width:100%}

.team-matchday .fixture-teams{width:100%}

.team-matchday .fixture-team{width:100%}

.team-matchday .actions{width:100%;margin-top:auto}

.team-matchday .muted{display:block;overflow-wrap:anywhere}

.match.fixture-card .fixture-team{display:flex;align-items:center;width:100%;min-width:0;padding:9px 11px;border:1px solid rgba(81,121,181,.22);border-radius:12px;background:rgba(255,255,255,.035)}

.match.fixture-card .fixture-team:hover{border-color:rgba(81,121,181,.45);background:rgba(255,255,255,.055)}

.match.fixture-card .team-with-logo{gap:12px;min-width:0;font-size:16px;font-weight:850}

.match.fixture-card .team-logo{flex-basis:38px;width:38px;height:38px}

.team-matchday h3{display:none}

.team-matchday .match.fixture-card{flex:1}

.match.fixture-card .fixture-team{justify-content:center;padding:0;border:0;background:transparent;text-align:center}

.match.fixture-card .fixture-team:hover{border-color:transparent;background:transparent}

.match.fixture-card .team-with-logo{flex-direction:column;gap:10px;width:100%;font-size:15px;line-height:1.2}

.match.fixture-card .team-logo{flex:0 0 86px;width:86px;height:86px;filter:drop-shadow(0 10px 14px rgba(0,6,22,.35))}

.match.fixture-card .team-logo.fallback{border-radius:20px}

.match.fixture-card .team-logo.fallback b{font-size:18px}

.match.fixture-card .team-name{display:block;min-height:36px;overflow:visible;white-space:normal;text-wrap:balance}

.standing-team{display:flex;align-items:center;gap:10px;min-width:150px}

.pilot-team-table{min-width:1050px}

.pilot-referee-table th:first-child,.pilot-referee-table td:first-child,.pilot-team-table th:first-child,.pilot-team-table td:first-child{text-align:left}

/* Directory e schede rosa/statistiche generate da data/teams/*.json */
.team-detail-hero,.detail-section,.subpage-header{max-width:var(--max);margin:0 auto;padding:32px 24px}

.team-directory-grid{max-width:var(--max);margin:0 auto 48px;padding:0 24px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}

.team-directory-card{display:grid;grid-template-columns:72px 1fr auto;align-items:center;gap:18px;padding:20px;border:1px solid var(--line,#d9dde5);border-radius:18px;background:var(--card,#fff);color:inherit;text-decoration:none;box-shadow:0 8px 24px rgba(14,25,48,.06)}

.team-directory-card:hover{transform:translateY(-2px);box-shadow:0 12px 30px rgba(14,25,48,.12)}

.team-directory-card img,.team-detail-hero>img{width:72px;height:72px;object-fit:contain}

.team-directory-card h2{margin:8px 0 4px;font-size:1.25rem}

.team-directory-card p,.team-directory-card small{margin:0;color:var(--muted,#667085)}

.team-detail-hero{display:flex;align-items:center;gap:24px}

.team-detail-hero>img{width:156px;height:156px}

.team-detail-hero>div{flex:1;min-width:0}

.team-detail-hero h1{margin:.25rem 0}

.team-stat-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}

.team-stat-grid article{padding:14px;border-radius:12px;background:var(--card,#fff);border:1px solid var(--line,#e1e5ec)}

.team-stat-grid span{display:block;color:var(--muted,#667085);font-size:.8rem}

.team-stat-grid strong{display:block;margin-top:5px;font-size:1.15rem}

.split-grid .team-stat-grid{grid-template-columns:repeat(2,minmax(0,1fr))}

.squad-controls{display:grid;grid-template-columns:2fr repeat(3,1fr);gap:12px;margin:16px 0}

.squad-controls label{font-size:.78rem;font-weight:700}

.squad-controls input,.squad-controls select{display:block;width:100%;margin-top:5px;padding:10px;border:1px solid var(--line,#ccd2dc);border-radius:9px;background:var(--card,#fff);color:inherit}

/* Schede giocatore Milan */
.roster-summary,.squad-count{color:var(--muted,#667085)}

.squad-count{margin:4px 0 10px;font-size:.85rem}

/* Statistiche squadra: palette blu leggibile e componenti condivisi. */
.team-directory-card,.team-stat-grid article{border-color:var(--line);background:linear-gradient(155deg,var(--surface2),var(--surface));color:var(--text)}

.team-directory-card:hover{border-color:var(--gold);box-shadow:0 14px 34px rgba(0,7,31,.42)}

.team-directory-card p,.team-directory-card small,.team-stat-grid span{color:var(--muted)}

.team-directory-card small{display:block;margin-top:3px}

.squad-controls input,.squad-controls select{border-color:var(--line);background:var(--surface);color:var(--text)}

.squad-controls input::placeholder{color:var(--muted)}

/* Il PNG e ritagliato sul contenuto: il marchio resta interamente visibile. */

/* Stato dinamico degli obiettivi stagionali */
.objective-section-head h2{margin-bottom:0}

.objective-card{overflow:hidden;border:1px solid var(--line);border-radius:18px;background:linear-gradient(145deg,rgba(23,79,165,.2),var(--surface));box-shadow:0 12px 28px rgba(0,7,31,.2)}

.objective-card>header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 16px;border-bottom:1px solid var(--line);background:rgba(5,19,52,.5)}

.objective-card>header .team-with-logo{font-weight:900}

.objective-card>header>span{color:#fff;font-size:.67rem;font-weight:900;letter-spacing:.04em;text-align:right;text-transform:uppercase}

.objective-title{padding:16px}

.objective-title small{color:var(--gold);font-size:.7rem;font-weight:900;letter-spacing:.07em;text-transform:uppercase}

.objective-title h3{margin:5px 0 4px;font-size:1.18rem}

.objective-title p{margin:0;color:var(--muted);font-size:.8rem}

.objective-metrics{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));border-top:1px solid var(--line)}

.objective-metric{min-width:0;padding:12px 8px;text-align:center;border-right:1px solid var(--line)}

.objective-metric:last-child{border-right:0}

.objective-metric span{display:block;min-height:2.1em;color:var(--muted);font-size:.62rem;font-weight:800;line-height:1.05;text-transform:uppercase}

.objective-metric strong{display:block;margin-top:7px;color:#fff;font-size:1.03rem}

.objective-metric.positive strong{color:#70dfa5}

.objective-metric.negative strong{color:#ff8f91}

.objective-metric.urgent strong{color:#ffe083}

.objective-method{margin:14px 2px 0;color:var(--muted);font-size:.8rem}

/* Directory squadre: identità cromatica dei club. */
.team-directory-card{grid-template-columns:96px minmax(0,1fr);gap:22px;padding:22px;border-color:color-mix(in srgb,var(--team-primary) 68%,white);background:linear-gradient(135deg,color-mix(in srgb,var(--team-primary) 78%,#061020),color-mix(in srgb,var(--team-secondary) 76%,#061020));color:#fff;box-shadow:0 8px 24px rgba(14,25,48,.2)}

.team-directory-card:hover{border-color:#fff;box-shadow:0 14px 34px rgba(0,7,31,.42)}

.team-directory-card img{width:96px;height:96px}

.team-directory-card h2{margin:0 0 7px;font-size:1.65rem;line-height:1.08}

.team-directory-card p,.team-directory-card small{color:rgba(255,255,255,.84)}

.home-match-teams .team-with-logo{min-width:0}

.home-match-teams .team-logo{width:32px;height:32px;flex:0 0 32px}

.home-match-teams .team-logo img{width:24px;height:24px}

.home-match-teams .team-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px;font-weight:800}

.team-directory-card{transition:.2s ease}

.team-directory-card:hover{transform:translateY(-4px)}

.team-directory-card[hidden],.referee-card[hidden]{display:none!important}

.objective-metric.urgent .metric-track b{background:linear-gradient(90deg,#ef9e34,#ffe083)}

/* Directory squadre 4x5 con card fronte/retro. */
.team-directory-grid.team-flip-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;padding-inline:0}

.team-flip-card{display:block;height:300px;padding:0;border:0;background:none;box-shadow:none;perspective:1100px}

.team-flip-card:hover{border:0;box-shadow:none;transform:none}

.team-flip-inner{position:relative;display:block;width:100%;height:100%;transition:transform .58s cubic-bezier(.2,.72,.2,1);transform-style:preserve-3d}

.team-flip-card:hover .team-flip-inner,.team-flip-card:focus-visible .team-flip-inner{transform:rotateY(180deg)}

.team-flip-face{position:absolute;display:flex;inset:0;overflow:hidden;border:1px solid color-mix(in srgb,var(--team-primary) 68%,white);border-radius:20px;backface-visibility:hidden;-webkit-backface-visibility:hidden}

.team-flip-front{align-items:center;justify-content:center;flex-direction:column;gap:13px;padding:22px;background:radial-gradient(circle at 50% 30%,rgba(255,255,255,.16),transparent 42%),linear-gradient(145deg,color-mix(in srgb,var(--team-primary) 82%,#061020),color-mix(in srgb,var(--team-secondary) 80%,#061020));box-shadow:inset 0 1px rgba(255,255,255,.12),var(--shadow-sm)}

.team-flip-front img{width:112px;height:112px;object-fit:contain;filter:drop-shadow(0 12px 18px rgba(0,0,0,.36))}

.team-flip-front small{color:rgba(255,255,255,.72);font-size:.68rem;font-weight:900;letter-spacing:.08em;text-transform:uppercase}

.team-flip-back{align-items:flex-start;justify-content:center;flex-direction:column;gap:7px;padding:22px;background:linear-gradient(145deg,color-mix(in srgb,var(--team-secondary) 72%,#061020),color-mix(in srgb,var(--team-primary) 74%,#061020));transform:rotateY(180deg)}

.team-flip-back strong{margin-bottom:5px;color:#fff;font-size:1.3rem}

.team-flip-back span{color:rgba(255,255,255,.82);font-size:.76rem;line-height:1.35}

.team-flip-back b{width:100%;margin-top:8px;padding-top:11px;border-top:1px solid rgba(255,255,255,.24);color:var(--gold);font-size:.78rem}

.team-flip-card:focus-visible{outline:2px solid var(--gold);outline-offset:4px}

.team-page-jumps{display:flex;gap:8px;width:100%;margin:18px 0 0;padding:0;overflow-x:auto;scrollbar-width:none}

.team-page-jumps::-webkit-scrollbar{display:none}

.team-page-jumps a{flex:0 0 auto;padding:8px 12px;border:1px solid var(--line);border-radius:999px;background:rgba(255,255,255,.5);color:var(--muted);font-size:.72rem;font-weight:800;text-decoration:none}

.team-page-jumps a:hover{border-color:var(--line-strong);color:var(--text)}

.team-page-jumps a.team-calendar-link{border-color:#17366f;background:#17366f;color:#fff;box-shadow:0 8px 18px rgba(23,54,111,.16)}

.team-page-jumps a.team-calendar-link:hover{border-color:#0e2a69;background:#0e2a69;color:#fff}

.team-season-comparison{padding-top:20px;padding-bottom:20px;scroll-margin-top:90px}

.team-season-comparison-heading{margin-bottom:18px;padding-bottom:14px;border-bottom:1px solid var(--line)}

.team-season-comparison-heading h2{margin:3px 0 0;font-size:clamp(1.45rem,2.6vw,2rem)}

.team-season-comparison-heading p{margin:6px 0 0;color:var(--muted);font-size:.82rem}

.team-attack-channels{margin-bottom:26px;padding:18px 20px;border:1px solid var(--line);border-radius:18px;background:color-mix(in srgb,var(--panel) 88%,transparent)}

.team-attack-channels h3{margin:0 0 14px;color:var(--text);font-size:.82rem;letter-spacing:.08em;text-transform:uppercase}

.team-attack-channel-bars{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}

.team-attack-channel-bars>div{display:grid;grid-template-columns:50px minmax(70px,1fr) 42px;align-items:center;gap:9px}

.team-attack-channel-bars span{color:var(--muted);font-size:.76rem}

.team-attack-channel-bars i{height:8px;overflow:hidden;border-radius:999px;background:color-mix(in srgb,var(--line) 72%,transparent)}

.team-attack-channel-bars i b{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--gold),#d7b96e)}

.team-attack-channel-bars strong{font-size:.78rem;text-align:right}

.team-attack-channels p{margin:13px 0 0;color:var(--muted);font-size:.76rem}

.team-attack-channels p strong{color:#7a6740}

.team-season-columns{display:grid;gap:12px}

.team-season-column{overflow:hidden;border:1px solid var(--line);border-radius:18px;background:color-mix(in srgb,var(--panel) 82%,transparent)}

.team-season-heading{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:15px 18px;cursor:pointer;list-style:none}

.team-season-heading::-webkit-details-marker{display:none}

.team-season-heading::after{content:"+";display:grid;place-items:center;flex:0 0 28px;width:28px;height:28px;border:1px solid var(--line);border-radius:50%;color:var(--muted);font-size:1rem;font-weight:700}

.team-season-column[open]>.team-season-heading::after{content:"−"}

.team-season-heading>div{display:grid;gap:2px}

.team-season-heading h2{margin:0;font-family:"Anton",sans-serif;font-size:1.65rem;font-weight:400;letter-spacing:.01em}

.team-season-heading>span{margin-left:auto;color:var(--muted);font-size:.75rem;font-weight:700;white-space:nowrap}

.team-season-content{display:grid;grid-template-columns:1.15fr 1fr 1fr;gap:24px;padding:4px 18px 18px;border-top:1px solid var(--line)}

.team-season-group{min-width:0;padding-top:12px}

.team-season-group>h3{margin:0 0 4px;padding:8px 0;color:var(--gold);font-size:.78rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase}

.team-season-list{margin:0}

.team-season-list>div{display:flex;align-items:baseline;justify-content:space-between;gap:18px;padding:7px 0;border-bottom:1px solid color-mix(in srgb,var(--line) 72%,transparent)}

.team-season-list dt{color:var(--muted);font-size:.78rem;line-height:1.3}

.team-season-list dd{margin:0;color:var(--text);font-size:.9rem;font-weight:850;text-align:right}

.team-season-splits{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}

.team-season-splits h4{margin-bottom:6px;color:var(--text);font-size:.75rem;letter-spacing:.06em;text-transform:uppercase}

.team-season-empty{grid-column:1/-1;margin:12px 0 0;padding:10px 12px;border-left:3px solid var(--gold);border-radius:0 10px 10px 0;background:rgba(243,201,105,.08);color:var(--muted);font-size:.82rem}

.match.fixture-card .fixture-team{border-color:rgba(255,255,255,.08);background:rgba(255,255,255,.035)}

.team-flip-face{border-color:rgba(255,255,255,.16);border-radius:26px}

.team-flip-front{box-shadow:inset 0 1px rgba(255,255,255,.16),0 18px 48px rgba(0,0,0,.22)}

.team-flip-back{background:linear-gradient(155deg,color-mix(in srgb,var(--team-secondary) 60%,#101724),color-mix(in srgb,var(--team-primary) 62%,#0a101e))}

.match.fixture-card .fixture-team{border-color:rgba(111,172,244,.17);background:rgba(35,94,180,.12)}

.match.fixture-card .fixture-team,.match.fixture-card .fixture-team:hover{border:0;background:transparent;box-shadow:none}

.team-personal-calendar{scroll-margin-top:100px}

.team-personal-calendar .team-schedule-head>div{min-width:0}

.team-personal-calendar .team-schedule-head h2{margin-bottom:6px}

.team-personal-calendar .team-schedule-head p:last-child{margin:0}

.team-personal-calendar .venue-status{justify-content:center;background:rgba(36,90,120,.1);color:var(--glass-blue)}

.team-calendar-list{overflow:hidden;border:1px solid rgba(40,58,59,.12);border-radius:22px;background:rgba(255,255,255,.38);box-shadow:0 16px 40px rgba(40,58,59,.08)}

.team-calendar-row{display:grid;grid-template-columns:72px 190px 92px minmax(300px,1fr) 130px;gap:18px;align-items:center;min-height:82px;padding:13px 18px;border-bottom:1px solid rgba(40,58,59,.1)}

.team-calendar-row:last-child{border-bottom:0}

.team-calendar-row:hover{background:rgba(181,250,255,.16)}

.team-calendar-row.is-european{border-color:rgba(38,86,151,.2);background:linear-gradient(105deg,rgba(228,239,255,.72),rgba(255,255,255,.36))}

.team-calendar-row.is-cup{border-color:rgba(154,90,8,.2);background:linear-gradient(105deg,rgba(255,244,216,.72),rgba(255,255,255,.36))}

.team-calendar-row.has-fatigue{box-shadow:inset 4px 0 0 #c77719}

.team-calendar-round{text-align:center}

.team-calendar-round strong,.team-calendar-round span,.team-calendar-when strong{display:block}

.team-calendar-round strong{color:var(--glass-blue);font-size:22px;line-height:1}

.team-calendar-row.is-european .team-calendar-round strong{font-size:14px;letter-spacing:.08em}

.team-calendar-row.is-cup .team-calendar-round strong{font-size:12px;letter-spacing:.06em}

.team-calendar-round span,.team-calendar-when span{margin-top:5px;color:var(--glass-muted);font-size:10px;letter-spacing:.06em;text-transform:uppercase}

.team-calendar-when strong{font-size:12px;font-weight:700;line-height:1.4}

.team-calendar-when .status{display:inline-flex}

.team-calendar-workload,.team-calendar-fatigue{display:block;margin-top:6px;font-size:10px;font-weight:800;line-height:1.35}

.team-calendar-workload{color:#285585}

.team-calendar-fatigue{color:#9a5208}

.team-calendar-match{display:grid;grid-template-columns:minmax(0,1fr) 45px minmax(0,1fr);gap:12px;align-items:center}

.team-calendar-club{display:flex;align-items:center;gap:10px;min-width:0}

.team-calendar-club:first-child{justify-content:flex-end;text-align:right}

.team-calendar-club img,.team-calendar-opponent-mark{flex:0 0 34px;width:34px;height:34px;object-fit:contain}

.team-calendar-opponent-mark{display:grid;place-items:center;border:1px solid rgba(30,70,120,.2);border-radius:50%;background:rgba(255,255,255,.72);color:#285585;font-size:10px;font-style:normal;font-weight:850;letter-spacing:.03em}

.team-calendar-club span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

.team-calendar-club.is-current{color:var(--glass-blue);font-weight:850}

.team-calendar-score{text-align:center;color:var(--glass-gold);font-size:13px}

.team-calendar-actions{display:flex;justify-content:flex-end;gap:10px}

.team-calendar-actions a{color:var(--glass-blue);font-size:11px;font-weight:750;text-decoration:none}

.team-calendar-actions a:hover{text-decoration:underline}

.team-calendar-no-prediction{color:#285585;font-size:10px;font-weight:800;line-height:1.35;text-align:right;text-transform:uppercase}

.team-calendar-picker{padding:18px;border:1px solid rgba(40,58,59,.12);border-radius:22px;background:rgba(255,255,255,.38);box-shadow:0 16px 40px rgba(40,58,59,.08)}

.team-calendar-picker>label{display:grid;grid-template-columns:auto minmax(260px,480px);align-items:center;gap:16px;margin-bottom:16px}

.team-calendar-picker>label>span{font-size:12px;font-weight:800}

.team-calendar-picker select{width:100%}

.team-calendar-picker .team-calendar-row{border:1px solid rgba(40,58,59,.1);border-radius:16px;background:rgba(255,255,255,.3)}

.cup-team-slot{
  display:flex;
  align-items:center;
  gap:7px;
  min-width:0;
  height:20px;
  padding:0 8px;
  color:#c3cfe1;
  font-size:9px;
  font-weight:750;
  letter-spacing:.015em;
  white-space:nowrap;
}

.cup-team-slot>span{
  overflow:hidden;
  text-overflow:ellipsis;
}

.cup-team-slot+.cup-team-slot{border-top:1px solid rgba(123,157,208,.25)}

.cup-team-slot i{
  flex:0 0 5px;
  width:5px;
  height:5px;
  border:1px solid rgba(242,193,78,.58);
  border-radius:50%;
  background:rgba(242,193,78,.12);
}

.objective-metric.positive strong{color:#187044}

.objective-metric.negative strong{color:#b4232c}

.objective-metric.urgent strong{color:#91620d}

/* Card squadre: vetro coordinato alla navbar */
.team-directory-grid.team-flip-grid{gap:18px}

.team-flip-card{filter:drop-shadow(0 16px 16px rgba(40,58,59,.08))}

.team-flip-face{
  border:1px solid #00000015;
  border-radius:26px;
  background:
    linear-gradient(115deg,rgba(255,255,255,.46),transparent 34%),
    linear-gradient(295deg,rgba(255,255,255,.18),transparent 50%),
    #b5faff31;
  box-shadow:
    0 6px 2px #00000012,
    0 14px 12px #0000000d,
    0 28px 28px #0000000a,
    inset 0 1px 4px 1px #ffffff78;
  backdrop-filter:blur(22px) saturate(135%);
  -webkit-backdrop-filter:blur(22px) saturate(135%);
}

.team-flip-front{
  color:#283a3b;
  background:
    radial-gradient(circle at 50% 28%,color-mix(in srgb,var(--team-primary) 12%,transparent),transparent 46%),
    linear-gradient(115deg,rgba(255,255,255,.48),transparent 34%),
    linear-gradient(295deg,rgba(255,255,255,.18),transparent 50%),
    #b5faff31;
}

.team-flip-front img{
  width:126px;
  height:126px;
  opacity:.82;
  filter:
    drop-shadow(-1px -1px 0 rgba(255,255,255,.96))
    drop-shadow(1px 2px 1px rgba(40,58,59,.42));
}

.team-flip-back{
  color:#283a3b;
  background:
    radial-gradient(circle at 100% 0,color-mix(in srgb,var(--team-primary) 11%,transparent),transparent 52%),
    radial-gradient(circle at 0 100%,color-mix(in srgb,var(--team-secondary) 9%,transparent),transparent 48%),
    linear-gradient(115deg,rgba(255,255,255,.46),transparent 36%),
    #b5faff31;
}

.team-flip-back strong{color:#283a3b;text-shadow:0 1px 0 rgba(255,255,255,.74)}

.team-flip-back span{color:rgba(40,58,59,.76)}

.team-flip-back b{
  border-top-color:rgba(40,58,59,.14);
  color:#8a6116;
}

.team-flip-card:focus-visible{outline-color:#283a3b}

.hero:not(.team-flip-face){
  border:1px solid var(--glass-border);
  background:linear-gradient(115deg,rgba(255,255,255,.5),transparent 38%),linear-gradient(295deg,rgba(255,255,255,.16),transparent 52%),var(--glass-surface);
  box-shadow:0 8px 4px #00000012,0 24px 28px #0000000d,inset 0 1px 4px #ffffff80;
  backdrop-filter:blur(22px) saturate(130%);
  -webkit-backdrop-filter:blur(22px) saturate(130%);
}

.match.fixture-card .fixture-team{color:var(--glass-text)}

.objective-metric.positive strong{color:#17653e}

.objective-metric.negative strong{color:#9e2630}

.objective-metric.urgent strong{color:var(--glass-gold)}

.match.fixture-card .team-name{color:#28383b}

/* Stato obiettivi nella pagina della singola squadra */
.team-objective-section{margin-top:18px;padding-top:20px;padding-bottom:20px;scroll-margin-top:90px}

.team-objective-section .objective-section-head{align-items:center}

.team-objective-section .objective-card{max-width:none}

.team-method-details{margin-top:10px;color:var(--muted);font-size:.78rem}

.team-method-details summary{width:max-content;max-width:100%;cursor:pointer;font-weight:800}

.team-method-details p{max-width:850px;margin:8px 0 0;line-height:1.5}

.team-objective-team{color:#fff;font-weight:800}

.team-page-navigation{align-items:center;gap:24px}

.team-page-navigation-all{display:inline-flex;align-items:center;min-height:53px;padding:9px 12px;border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.54);text-decoration:none}

.team-page-navigation>nav{display:flex;justify-content:flex-end;gap:10px;margin-left:auto}

.team-page-navigation>nav a{display:grid;gap:2px;min-width:156px;padding:9px 12px;border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.54);text-decoration:none}

.team-page-navigation>nav a:last-child{text-align:right}

.team-page-navigation>nav span{color:var(--muted);font-size:.62rem;font-weight:800;letter-spacing:.04em;text-transform:uppercase}

.team-page-navigation>nav strong{color:var(--text);font-size:.82rem}

.home-match-teams .team-with-logo:first-child{justify-self:end;flex-direction:row-reverse;text-align:right}

.home-match-teams .team-with-logo:last-child{justify-self:start}

/* Selettore squadre: fascia compatta e stemmi otticamente uniformi. */
.team-nav{
  display:grid;
  grid-template-columns:180px minmax(0,1fr);
  align-items:center;
  gap:14px;
  margin:22px 0 42px;
  padding:12px 14px;
  border:1px solid rgba(40,58,59,.12);
  border-radius:20px;
  background:linear-gradient(115deg,rgba(255,255,255,.62),rgba(239,250,250,.68));
  box-shadow:0 10px 24px rgba(40,58,59,.08),inset 0 1px 3px rgba(255,255,255,.9);
  backdrop-filter:blur(20px) saturate(125%);
  -webkit-backdrop-filter:blur(20px) saturate(125%);
}

.team-nav>span{
  margin:0;
  padding-left:5px;
  color:#586769;
  font-size:10px;
  line-height:1.35;
  letter-spacing:.11em;
}

.team-nav>div{display:grid;grid-template-columns:repeat(20,minmax(38px,1fr));gap:5px;min-width:0}

.team-nav-link{
  width:100%;
  height:46px;
  min-width:0;
  padding:7px;
  border:0;
  border-radius:0;
  background:transparent;
  box-shadow:none;
}

.team-nav-link img{width:32px;height:32px;max-width:32px;max-height:32px;filter:drop-shadow(0 1px 1px rgba(5,24,34,.58)) drop-shadow(0 4px 6px rgba(5,24,34,.26));transition:filter .18s ease,transform .18s ease}

.team-nav-link[data-team="juventus"] img{width:23px;max-width:23px}

.team-nav-link:hover,.team-nav-link.active{
  background:transparent;
  box-shadow:none;
  transform:translateY(-2px);
}

.team-nav-link:hover img,.team-nav-link.active img{filter:drop-shadow(0 1px 1px rgba(5,24,34,.68)) drop-shadow(0 7px 9px rgba(5,24,34,.34));transform:scale(1.08)}

.reading-fixture-teams .team-with-logo{flex-direction:column;gap:10px;width:100%;text-align:center}

.reading-fixture-teams .team-logo{flex:0 0 86px;width:86px;height:86px;filter:drop-shadow(0 10px 14px rgba(34,48,58,.18))}

.reading-fixture-teams .team-name{font-size:15px;font-weight:850;line-height:1.2}

.reading-matchup .team-with-logo{flex-direction:column;gap:10px;text-align:center}

.reading-matchup .team-logo{width:86px;height:86px}

.reading-matchup .team-name{font-size:16px;font-weight:850}

.prediction-team-volume{padding:22px;border:1px solid var(--glass-border);border-radius:24px;background:linear-gradient(145deg,rgba(255,255,255,.9),rgba(255,255,255,.58));box-shadow:inset 0 1px #fff,0 14px 36px rgba(32,49,73,.08)}

.prediction-team-volume>.team-with-logo{font-size:18px;font-weight:900}

.reading-evidence-card>.team-with-logo{font-size:18px;font-weight:850}

.reading-evidence-card .team-logo{width:46px;height:46px}

/* Profili tattici storici WhoScored */
.team-analysis-grid{display:grid;grid-template-columns:minmax(0,1.06fr) minmax(0,.94fr);gap:24px;max-width:var(--max);margin:0 auto;padding:24px}

.team-analysis-grid>.detail-section{min-width:0;margin:0;padding:0}

.team-style-section{align-content:start;display:grid;gap:18px;scroll-margin-top:90px}

.team-style-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:20px}

.team-style-heading h2{margin:4px 0 0}

.team-style-quality{display:inline-flex;align-items:center;min-height:32px;padding:7px 12px;border:1px solid rgba(14,42,105,.15);border-radius:999px;background:#f4f7fc;color:#17366f;font-size:.78rem;font-weight:800}

.team-style-quality.quality-limited-sample{background:#fff4dc;color:#744a00}

.team-style-quality.quality-statistical-only{background:#f3f3f3;color:#555}

.team-style-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}

.team-style-metrics>div{padding:13px;border:1px solid rgba(14,42,105,.1);border-radius:14px;background:#f8faff}

.team-style-metrics span,.team-style-metrics strong{display:block}

.team-style-metrics span{margin-bottom:5px;color:#61708e;font-size:.75rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em}

.team-style-metrics strong{font-size:1.05rem}

.team-style-trait-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,.8fr);align-items:start;gap:10px}

.team-style-traits,.team-style-lower>article{padding:20px;border:1px solid rgba(14,42,105,.1);border-radius:20px;background:#fff}

.team-style-traits h3,.team-style-lower h3{margin:0 0 14px}

.team-style-traits ul{display:grid;gap:9px;margin:0;padding:0;list-style:none}

.team-style-traits li{display:flex;justify-content:space-between;gap:12px;padding-bottom:9px;border-bottom:1px solid rgba(14,42,105,.08)}

.team-style-traits li:last-child{padding-bottom:0;border-bottom:0}

.team-style-traits small{color:#7a6740;font-weight:700;white-space:nowrap}

.team-style-traits{padding:14px;border-radius:16px}

.team-style-traits:last-child{grid-column:1/-1}

.team-style-traits h3{margin-bottom:9px;font-size:.82rem;line-height:1.25}

.team-style-traits li{gap:8px;padding-bottom:7px;font-size:.75rem;line-height:1.35}

.team-style-traits small{font-size:.63rem;letter-spacing:.02em}

.team-style-traits:last-child ul{grid-template-columns:repeat(2,minmax(0,1fr));column-gap:16px}

.team-style-lower{display:block}

.team-style-goals{display:grid;gap:10px}

.team-style-goals>div{display:grid;grid-template-columns:1fr auto auto;gap:12px;align-items:center}

.team-style-goals small{min-width:42px;color:#61708e;text-align:right}

.team-style-section .objective-method a{font-weight:800}

.team-style-details,.squad-table-disclosure{overflow:hidden;border:1px solid var(--line);border-radius:16px;background:rgba(255,255,255,.42)}

.team-style-details>summary,.squad-table-disclosure>summary{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:14px 16px;cursor:pointer;list-style:none;font-size:.82rem;font-weight:850}

.team-style-details>summary::-webkit-details-marker,.squad-table-disclosure>summary::-webkit-details-marker{display:none}

.team-style-details>summary::after,.squad-table-disclosure>summary::after{content:"+";font-size:1.1rem}

.team-style-details[open]>summary::after,.squad-table-disclosure[open]>summary::after{content:"−"}

.team-style-details-content{display:grid;gap:16px;padding:0 14px 14px;border-top:1px solid var(--line)}

.team-style-details-content>.team-style-trait-grid{margin-top:14px}

.team-probable-lineup{align-content:start;display:grid;gap:20px;scroll-margin-top:90px}

.probable-lineup-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:20px}

.probable-lineup-heading h2{margin:4px 0 0}

.probable-lineup-heading>strong{padding:9px 14px;border-radius:999px;background:#0e2a69;color:#fff;font-size:1rem}

.probable-lineup-pitch{min-height:520px;padding:28px 22px;display:flex;flex-direction:column;justify-content:space-between;gap:20px;border:2px solid rgba(255,255,255,.8);border-radius:26px;background:linear-gradient(90deg,rgba(255,255,255,.08) 1px,transparent 1px),linear-gradient(rgba(255,255,255,.08) 1px,transparent 1px),#176b42;background-size:36px 36px;box-shadow:inset 0 0 0 8px rgba(255,255,255,.12)}

.probable-lineup-row{display:flex;justify-content:space-evenly;gap:10px}

.probable-lineup-row span{max-width:150px;padding:8px 11px;border:1px solid rgba(255,255,255,.42);border-radius:999px;background:rgba(6,34,22,.82);color:#fff;font-size:.82rem;font-weight:800;text-align:center;box-shadow:0 6px 18px rgba(0,0,0,.18)}

/* Visualizzazione grafica delle probabili formazioni */
.team-probable-lineup{display:grid;gap:18px}

.probable-lineup-heading{align-items:center}

.probable-lineup-heading>span{display:inline-flex;padding:8px 12px;border:1px solid rgba(14,42,105,.12);border-radius:999px;background:#fff;color:var(--muted,#667085);font-size:.72rem;font-weight:800;letter-spacing:.04em;text-transform:uppercase}

.probable-lineup-board{width:100%;max-width:640px;overflow:hidden;border:1px solid rgba(9,22,42,.2);border-radius:30px;background:#111923;box-shadow:0 24px 60px rgba(4,13,28,.2)}

.probable-lineup-board-head{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:16px;padding:22px 26px;background:linear-gradient(115deg,var(--lineup-primary),var(--lineup-secondary));color:#fff}

.probable-lineup-board-head img{width:58px;height:58px;padding:5px;border-radius:15px;background:rgba(255,255,255,.94);object-fit:contain}

.probable-lineup-board-head small{display:block;margin-bottom:2px;color:rgba(255,255,255,.7);font-size:.7rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase}

.probable-lineup-board-head h3{margin:0;color:#fff;font-family:"Anton",sans-serif;font-size:2rem;font-weight:400;letter-spacing:.02em;text-transform:uppercase}

.probable-lineup-board-head>strong{padding:10px 15px;border:1px solid rgba(255,255,255,.28);border-radius:999px;background:rgba(0,0,0,.24);font-size:1rem}

.probable-lineup-board .probable-lineup-pitch{position:relative;isolation:isolate;aspect-ratio:4/5;min-height:0;margin:14px;padding:28px 20px;overflow:hidden;border:1px solid rgba(255,255,255,.72);border-radius:22px;background:radial-gradient(circle at 50% 48%,rgba(255,255,255,.08),transparent 34%),repeating-linear-gradient(0deg,rgba(255,255,255,.035) 0,rgba(255,255,255,.035) 56px,rgba(0,0,0,.035) 56px,rgba(0,0,0,.035) 112px),linear-gradient(150deg,#176b45,#0a4b35);box-shadow:inset 0 0 45px rgba(0,0,0,.25)}

.probable-lineup-row{position:relative;z-index:1;display:flex;align-items:center;justify-content:space-evenly;width:min(calc(var(--lineup-count) * 150px),94%);margin:0 auto;gap:14px}

.probable-lineup-board footer{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:0 24px 20px;color:#b8c2ce;font-size:.76rem}

.probable-lineup-board footer p{margin:0}
.probable-lineup-board footer .probable-lineup-substitutes{margin-top:6px;line-height:1.45}
.probable-lineup-substitutes strong{color:#fff}

.probable-lineup-board footer a{color:#fff;font-weight:800;white-space:nowrap}

.probable-lineup-board-head>strong{color:var(--lineup-head-ink,#fff)}

.team-roster-section{scroll-margin-top:90px}

.team-roster-heading{display:flex;align-items:end;justify-content:space-between;gap:18px;padding-bottom:14px;border-bottom:1px solid var(--line)}

.team-roster-heading h2{margin:3px 0 0}

.team-roster-heading>span{padding:6px 10px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:.72rem;font-weight:800}

.team-roster-section .squad-leaders{margin-top:22px;padding-top:0;border-top:0}

.squad-table-disclosure{margin-top:22px}

.squad-table-disclosure>summary>span:first-child{display:grid;gap:3px}

.squad-table-disclosure>summary small{color:var(--muted);font-weight:600}

.squad-table-disclosure>summary>span:last-child{margin-left:auto;color:var(--muted);font-size:.72rem;text-transform:uppercase}

.squad-table-disclosure-content{padding:16px;border-top:1px solid var(--line)}

.squad-table-disclosure-content .roster-summary{margin-top:0}

.reading-tactical-card>.team-with-logo{font-size:19px;font-weight:850}

.reading-matchup .team-with-logo{min-width:0;padding:14px 8px;border-radius:19px;background:rgba(255,255,255,.38)}

.reading-matchup .team-logo{filter:drop-shadow(0 12px 16px rgba(34,48,58,.18))}

.reading-match-hero~.reading-h2h-section .reading-h2h-match,.reading-match-hero~.reading-info-grid .round16-info-box,.reading-match-hero~.reading-info-grid .reading-evidence-card,.reading-match-hero~.reading-projection-prototype .prediction-team-volume,.reading-match-hero~.prediction-scenarios article,.reading-match-hero~.reading-panel-grid .reading-data-panel{border-color:rgba(36,90,120,.1);background:linear-gradient(145deg,rgba(255,255,255,.82),rgba(247,251,252,.58));box-shadow:inset 0 1px #fff,0 12px 30px rgba(32,49,73,.06)}

.reading-matchup .team-with-logo{padding:8px 4px;background:transparent}

.reading-match-hero~.prediction-engine-panel>.objective-method{display:inline;margin:10px 0 0;font-size:.72rem;line-height:1.45}

.reading-match-hero~.prediction-engine-panel>.objective-method:not(:last-child)::after{content:" · ";color:var(--glass-gold);font-weight:900}

.prediction-engine-notes .objective-method{margin:6px 0;font-size:.72rem;line-height:1.45}

/* Team-referee WhoScored profiles */
.team-referee-section{scroll-margin-top:96px}

.team-referee-selector{display:grid;gap:8px;max-width:420px;margin:26px 0 20px}

.team-referee-selector span{color:var(--muted);font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.08em}

.team-referee-selector select{width:100%;padding:13px 42px 13px 14px;border:1px solid rgba(255,255,255,.14);border-radius:12px;background:#101b2c;color:var(--text);font:inherit}

.team-referee-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:14px}

.team-referee-summary article{display:grid;gap:4px;padding:15px;border:1px solid rgba(255,255,255,.1);border-radius:12px;background:rgba(255,255,255,.025)}

.team-referee-summary span{color:var(--muted);font-size:12px}

.team-referee-summary strong{font-size:24px}

.team-referee-coverage{margin:0 0 16px;padding:13px 15px;border:1px solid rgba(39,209,127,.28);border-radius:12px;background:rgba(39,209,127,.06)}

.team-referee-coverage.is-partial{border-color:rgba(242,193,78,.32);background:rgba(242,193,78,.07)}

.team-referee-coverage p{margin:4px 0 0;color:var(--muted);font-size:13px}

.team-referee-table{min-width:1120px}

.team-referee-table td:first-child{min-width:180px}

.team-referee-table td:first-child a{color:var(--text)}

.team-referee-table td:first-child small{display:block;margin-top:3px;color:var(--muted);font-size:10px}

.team-referee-table td:nth-child(2) .sample-label{display:block;width:max-content;margin-top:5px}

.team-referee-source{display:flex;justify-content:space-between;gap:16px;margin-top:12px;color:var(--muted);font-size:12px}

.team-referee-empty{padding:22px;border:1px dashed rgba(242,193,78,.34);border-radius:14px;background:rgba(242,193,78,.05)}

.team-referee-empty p{max-width:760px;color:var(--muted)}

.cup-team-slot{display:grid;grid-template-columns:7px minmax(0,1fr);align-items:center;gap:9px;min-width:0;min-height:48px;height:auto;padding:8px 13px;color:#263d52;font-size:13px;font-weight:820;line-height:1.3;white-space:normal}

.cup-match-card.is-finished .cup-team-slot{height:120px;box-sizing:border-box}

.cup-team-slot.has-events{grid-template-columns:7px minmax(90px,120px) minmax(0,1fr)}

.cup-team-slot>span{overflow:visible;text-overflow:clip}

.cup-team-slot+.cup-team-slot{border-top:1px solid rgba(36,90,120,.1)}

.cup-team-slot>.cup-team-dot{width:7px;height:7px;border:1px solid rgba(167,116,22,.55);border-radius:50%;background:#fff6dc}

.cup-team-name{font-weight:850}

.cup-team-events{display:flex;align-items:center;flex-wrap:wrap;gap:5px;min-width:0}

.cup-team-event{display:inline-flex;align-items:center;gap:4px;min-width:0;padding:3px 6px;border:1px solid rgba(36,90,120,.1);border-radius:999px;background:#f7f9fa;color:#445e73;font-size:9px;font-weight:700;line-height:1.2}

.cup-team-event>img{width:14px;height:14px;flex:0 0 14px;border-radius:50%;object-fit:cover}

.cup-team-event strong{color:#7b5c18;font-size:9px}

.cup-team-slot .cup-card-symbol{display:inline-block;width:8px;height:12px;flex:0 0 8px;border:1px solid rgba(89,67,11,.2);border-radius:1px;background:#f3c927}

.cup-team-slot .cup-card-symbol.is-yellow{background:#f3c927}

.cup-team-slot .cup-card-symbol.is-red{border-color:rgba(105,7,17,.22);background:#d92535}

.cup-team-event.is-red strong{color:#a51b28}

body[data-page="referees"] .pilot-summary article,
body[data-page="referees"] .team-referee-summary article{border-color:var(--glass-border);background:rgba(255,255,255,.5);box-shadow:inset 0 1px rgba(255,255,255,.72)}

body[data-page="referees"] .pilot-summary span,
body[data-page="referees"] .team-referee-summary span{color:var(--glass-muted)}

body[data-page="referees"] .pilot-summary strong,
body[data-page="referees"] .team-referee-summary strong{color:var(--glass-text)}

.team-referee-selector{margin-top:20px}

.team-referee-table th{white-space:normal;line-height:1.25}

/* Campo fotografico condiviso dalle probabili formazioni */
.probable-lineup-board .probable-lineup-pitch,
.reading-lineup-field{
  background-image:linear-gradient(rgba(5,24,14,.24),rgba(5,24,14,.24)),url("../assets/images/lineup-pitch.jpg");
  background-position:center;
  background-repeat:no-repeat;
  background-size:100% 100%;
}

/* Statistiche squadre mobile: logo e riepilogo dentro un'unica card. */
@media(max-width:760px){
  .team-flip-card{height:auto;filter:none;perspective:none}
  .team-flip-inner{
    display:grid;
    grid-template-columns:98px minmax(0,1fr);
    align-items:center;
    gap:18px;
    height:auto;
    min-height:220px;
    padding:20px;
    overflow:hidden;
    border:1px solid var(--glass-border);
    border-radius:26px;
    background:radial-gradient(circle at 0 0,color-mix(in srgb,var(--team-primary) 12%,transparent),transparent 48%),linear-gradient(115deg,rgba(255,255,255,.5),transparent 38%),var(--glass-surface);
    box-shadow:0 8px 4px #00000012,0 24px 28px #0000000d,inset 0 1px 4px #ffffff80;
    transform:none!important;
  }
  .team-flip-face{
    position:relative;
    inset:auto;
    min-height:0;
    padding:0;
    overflow:visible;
    border:0;
    border-radius:0;
    background:none;
    box-shadow:none;
    backdrop-filter:none;
    -webkit-backdrop-filter:none;
    backface-visibility:visible;
    -webkit-backface-visibility:visible;
  }
  .team-flip-front{justify-content:center}
  .team-flip-front img{width:92px;height:92px}
  .team-flip-back{gap:6px;transform:none}
  .team-flip-back strong{margin-bottom:3px;font-size:1.18rem}
  .team-flip-back b{margin-top:6px;padding-top:9px}
}
/* Shared team dashboard: the existing light and dark glass tokens only. */
