#team-squad-app .team-analysis-grid>.detail-section{padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;backdrop-filter:none}
#team-squad-app .team-style-heading,#team-squad-app .probable-lineup-heading{min-height:74px;align-items:start;margin:0}
#team-squad-app .probable-lineup-heading>span{display:none}
#team-squad-app .probable-lineup-board{max-width:none;background:var(--glass-dark-bg);border:1px solid var(--glass-dark-border);border-radius:18px;box-shadow:var(--glass-shadow);backdrop-filter:var(--glass-blur);color:var(--glass-dark-text)}
#team-squad-app .probable-lineup-board-head{background:transparent;padding:16px;gap:12px}
#team-squad-app .probable-lineup-board-head img{width:42px;height:42px;border-radius:10px}
#team-squad-app .probable-lineup-board-head h3{font-family:var(--font-body);font-size:20px;color:var(--glass-dark-text);text-transform:none}
#team-squad-app .probable-lineup-board-head>strong{color:var(--glass-dark-text);background:transparent}
#team-squad-app .probable-lineup-board footer{padding:0 16px 16px;gap:12px;align-items:start;flex-wrap:wrap}
.team-vertical-field{position:relative;isolation:isolate;margin:0 12px 16px;height:600px;border-radius:12px;overflow:hidden;background:repeating-linear-gradient(0deg,rgba(255,255,255,.025) 0 10%,transparent 10% 20%),#183e33}
.team-vertical-field .reading-kit-player{position:absolute;display:flex;align-items:center;flex-direction:column;gap:5px;width:17%;max-width:94px;transform:translate(-50%,-50%)}
.team-vertical-field .reading-kit-player strong{box-sizing:border-box;width:100%;min-height:2.5em;padding:2px;color:#fff;font-size:12px;font-weight:650;line-height:1.25;overflow-wrap:anywhere;text-align:center;text-shadow:0 1px 3px #071e18}
#team-squad-app .team-style-metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px}
#team-squad-app .team-style-metrics>div{padding:12px 0;border:0;border-bottom:1px solid var(--line);border-radius:0;background:transparent}
#team-squad-app .team-style-metrics span{font-size:11px;letter-spacing:.03em}
#team-squad-app :is(.team-style-traits,.team-style-lower>article,.team-style-goals>div){background:transparent;border-radius:12px}
#team-squad-app .team-style-details-content{padding:14px 0}
#team-squad-app .team-style-trait-grid{gap:12px}
#team-squad-app .player-comparator>header{align-items:start}
#team-squad-app .player-comparator-controls input{box-sizing:border-box;min-width:0}
#team-squad-app .player-comparator-head article{border-radius:14px}
#team-squad-app .player-comparator-head h3{color:var(--glass-dark-text);font-size:20px;overflow-wrap:anywhere}
#team-squad-app .squad-leader-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
#team-squad-app .squad-leader-card{height:100%;box-sizing:border-box;border:1px solid var(--glass-light-border);border-radius:16px;background:transparent;box-shadow:none;backdrop-filter:none;transform:none}
#team-squad-app .squad-leader-card header{background:transparent;border-bottom:1px solid var(--line)}
#team-squad-app .squad-leader-card li{grid-template-columns:22px minmax(0,1fr) auto;gap:8px;align-items:center;min-height:46px}
#team-squad-app .squad-leader-card .leader-player{white-space:normal;overflow-wrap:anywhere;text-align:left}
#team-squad-app .squad-leader-card strong{font-variant-numeric:tabular-nums}
#team-squad-app :is(.team-season-comparison,.team-tactics-section,.team-roster-section,.player-comparator){scroll-margin-top:100px}
@media(max-width:1000px){
 #team-squad-app .team-season-content{grid-template-columns:repeat(2,minmax(0,1fr))}
 #team-squad-app .team-analysis-grid{grid-template-columns:1fr}
 #team-squad-app .team-probable-lineup{max-width:600px;margin:auto}
 #team-squad-app .team-style-heading,#team-squad-app .probable-lineup-heading{min-height:0}
 #team-squad-app .squad-leader-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media(max-width:600px){
 #team-squad-app{width:var(--container-width);gap:16px;padding-top:20px}
 #team-squad-app :is(.team-detail-hero,.detail-section,.team-tactics-section){padding:16px;border-radius:20px}
 #team-squad-app .team-detail-hero{display:grid;grid-template-columns:64px minmax(0,1fr);gap:16px}
 #team-squad-app .team-detail-hero>img{width:64px;height:64px;margin:0;align-self:start}
 #team-squad-app .team-detail-hero h1{font-size:26px}
 #team-squad-app .team-detail-hero>div>p{font-size:12px}
 #team-squad-app .team-page-jumps{gap:6px}
 #team-squad-app .team-page-jumps a{font-size:11px;padding:6px 8px}
 #team-squad-app .objective-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}
 #team-squad-app .team-season-content{grid-template-columns:1fr;padding:6px 12px 14px;gap:8px}
 #team-squad-app .team-season-heading{padding:14px 12px;gap:8px;flex-wrap:wrap}
 #team-squad-app .team-season-heading h2{font-size:18px}
 #team-squad-app .team-season-heading>span{margin:0;font-size:11px;white-space:normal}
 #team-squad-app .team-season-heading::after{margin-left:auto}
 #team-squad-app .squad-leader-grid{grid-template-columns:1fr}
 #team-squad-app .player-comparator>header{display:block}
 #team-squad-app .player-comparator>header>p{margin-top:8px}
 #team-squad-app .player-comparator-controls{grid-template-columns:1fr}
 #team-squad-app .player-comparator-head{gap:8px}
 #team-squad-app .player-comparator-head article{padding:12px}
 #team-squad-app .player-comparator-head h3{font-size:16px}
 #team-squad-app .player-comparator table{min-width:0;table-layout:fixed;font-size:11px}
 #team-squad-app .player-comparator :is(th,td){padding:8px 4px;overflow-wrap:anywhere}
 #team-squad-app .team-season-splits{gap:16px}
 #team-squad-app .team-style-trait-grid{grid-template-columns:1fr}
 .team-vertical-field{height:520px;margin:0 8px 12px}
 .team-vertical-field .reading-kit-player strong{font-size:10px}
 .team-vertical-field .reading-kit-shirt{width:30px;height:30px}
}

/* Individual team pages: open editorial layout. All overrides stay inside
   this root; the shared lineup board and field geometry remain untouched. */
#team-squad-app.team-editorial{gap:12px}
#team-squad-app.team-editorial>[data-editorial-section]{margin:0;padding:24px;border:1px solid transparent;border-radius:0;background:transparent;box-shadow:none;backdrop-filter:none;-webkit-backdrop-filter:none}
#team-squad-app.team-editorial>[data-editorial-section]+[data-editorial-section]{border-top-color:var(--line)}
#team-squad-app.team-editorial .team-detail-hero{padding-block:20px}
#team-squad-app.team-editorial .team-detail-hero h1{font-size:clamp(27px,3vw,40px)}
#team-squad-app.team-editorial .team-detail-hero p{margin:7px 0;color:var(--muted);font-size:13px}
#team-squad-app.team-editorial .team-page-jumps{gap:8px 18px}
#team-squad-app.team-editorial .team-page-jumps a{padding:3px 0;border:0;border-radius:0;background:transparent;font-size:12px;text-decoration:none}
#team-squad-app.team-editorial .team-page-jumps a:hover{text-decoration:underline}
#team-squad-app.team-editorial .team-editorial-heading{margin:0 0 24px;padding:0;border:0}
#team-squad-app.team-editorial .team-editorial-heading .eyebrow{margin:0 0 8px}
#team-squad-app.team-editorial .team-editorial-heading h2{margin:0;font-family:Anton,Impact,sans-serif;font-size:clamp(24px,2.6vw,34px);font-weight:400;line-height:1.18;letter-spacing:.025em}
#team-squad-app.team-editorial .team-key-numbers{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));margin:0}
#team-squad-app.team-editorial .team-key-numbers>div{display:flex;flex-direction:column-reverse;align-items:flex-start;padding:0 24px;border-left:1px solid var(--line)}
#team-squad-app.team-editorial .team-key-numbers>div:first-child{padding-left:0;border-left:0}
#team-squad-app.team-editorial .team-key-numbers dt{color:var(--muted);font-size:12px}
#team-squad-app.team-editorial .team-key-numbers dd{margin:0 0 8px;font-size:clamp(32px,4vw,48px);font-weight:650;line-height:1.1;font-variant-numeric:tabular-nums}
#team-squad-app.team-editorial .team-editorial-note{margin:0 0 18px;color:var(--muted);font-size:12px;line-height:1.6}
#team-squad-app.team-editorial .team-season-summary>.team-editorial-note{margin:20px 0 0}
#team-squad-app.team-editorial .team-tactical-summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 24px;margin:0}
#team-squad-app.team-editorial .team-tactical-summary>div{padding-bottom:16px;border-bottom:1px solid var(--line)}
#team-squad-app.team-editorial .team-tactical-summary dt{color:var(--muted);font-size:12px}
#team-squad-app.team-editorial .team-tactical-summary dd{margin:8px 0 0;font-size:28px;font-weight:650;line-height:1.2}
#team-squad-app.team-editorial .team-style-essential{gap:18px}
#team-squad-app.team-editorial .team-style-essential>.team-style-heading{margin:0}
#team-squad-app.team-editorial .team-editorial-disclosure{margin-top:24px;border:0;border-top:1px solid var(--line);border-radius:0;background:transparent;overflow:visible}
#team-squad-app.team-editorial .team-editorial-disclosure>summary{display:flex;justify-content:space-between;align-items:center;gap:16px;min-height:48px;padding:12px 0;list-style:none;cursor:pointer;color:var(--glass-light-text);font-size:14px;font-weight:650}
#team-squad-app.team-editorial .team-editorial-disclosure>summary::-webkit-details-marker{display:none}
#team-squad-app.team-editorial .team-editorial-disclosure>summary::after{content:none}
#team-squad-app.team-editorial .team-editorial-disclosure>summary:hover{color:var(--button-blue-strong)}
#team-squad-app.team-editorial .team-editorial-disclosure>summary:focus-visible{outline:2px solid var(--button-blue-strong);outline-offset:4px}
#team-squad-app.team-editorial .team-disclosure-arrow{font-size:24px;font-weight:400;line-height:1}
#team-squad-app.team-editorial .team-editorial-disclosure[open]>summary .team-disclosure-arrow{transform:rotate(180deg)}
#team-squad-app.team-editorial .team-disclosure-content{padding:18px 0 8px;min-width:0}
#team-squad-app.team-editorial .team-disclosure-content>.detail-section{margin:0 0 24px;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none;backdrop-filter:none}
#team-squad-app.team-editorial .team-stat-summary,#team-squad-app.team-editorial .team-leader-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}
#team-squad-app.team-editorial .team-stat-summary article,#team-squad-app.team-editorial .team-leader-summary article{padding:0;min-width:0;border:0;border-radius:0;background:transparent;box-shadow:none}
#team-squad-app.team-editorial .team-stat-summary h3{font-size:15px;margin-bottom:16px}
#team-squad-app.team-editorial .team-stat-summary dl{margin:0}
#team-squad-app.team-editorial .team-stat-summary dl>div{display:flex;justify-content:space-between;gap:16px;padding:8px 0;border-bottom:1px solid var(--line);font-size:12px}
#team-squad-app.team-editorial .team-stat-summary dt{color:var(--muted)}
#team-squad-app.team-editorial .team-stat-summary dd{margin:0;font-weight:700;font-variant-numeric:tabular-nums}
#team-squad-app.team-editorial .team-leader-summary p{margin:0 0 12px;color:var(--muted);font-size:12px}
#team-squad-app.team-editorial .team-leader-summary strong{display:block;font-size:21px;line-height:1.3;overflow-wrap:anywhere}
#team-squad-app.team-editorial .team-leader-summary span{display:block;margin-top:8px;color:var(--muted);font-size:12px}
#team-squad-app.team-editorial .team-season-column{border:0;border-top:1px solid var(--line);border-radius:0;background:transparent;box-shadow:none}
#team-squad-app.team-editorial .team-season-heading{padding:18px 0;background:transparent}
#team-squad-app.team-editorial .team-season-content{padding:18px 0;grid-template-columns:repeat(3,minmax(0,1fr))}
#team-squad-app.team-editorial .team-season-group{min-width:0}
#team-squad-app.team-editorial .team-stat-table-wrap{max-width:100%;overflow-x:auto}
#team-squad-app.team-editorial table.team-season-list{width:100%;min-width:0;border-collapse:collapse;background:transparent;table-layout:auto}
#team-squad-app.team-editorial .team-season-list :is(th,td){padding:10px 8px;border-bottom:1px solid var(--line);font-size:12px;line-height:1.4;letter-spacing:normal;text-transform:none;background:transparent;color:inherit;white-space:normal}
#team-squad-app.team-editorial .team-season-list th{text-align:left;font-weight:400;color:var(--muted)}
#team-squad-app.team-editorial .team-season-list td{text-align:right;font-weight:700;white-space:nowrap;font-variant-numeric:tabular-nums}
#team-squad-app.team-editorial .team-season-list tr:nth-child(even){background:rgba(20,43,59,.025)}
#team-squad-app.team-editorial .team-season-list tr:hover{background:rgba(181,250,255,.34)}
#team-squad-app.team-editorial .squad-leader-card{height:auto;padding:0;border:0;border-radius:0;background:transparent;box-shadow:none}
#team-squad-app.team-editorial .squad-leader-card header{padding:12px 0;background:transparent}
#team-squad-app.team-editorial .squad-leader-card ol{padding:0}
#team-squad-app.team-editorial .squad-leaders-heading>span:last-child{border:0;padding:0}
#team-squad-app.team-editorial .squad-table-disclosure,#team-squad-app.team-editorial .team-style-details{background:transparent;border-radius:0;border-inline:0}
#team-squad-app.team-editorial .team-style-traits,#team-squad-app.team-editorial .team-style-lower>article{padding:12px 0;border:0;border-radius:0;background:transparent}
#team-squad-app.team-editorial .team-editorial-comparator .team-editorial-disclosure{margin:0;border:0}
#team-squad-app.team-editorial .team-editorial-comparator>details>summary{font-size:clamp(22px,2vw,28px)}
#team-squad-app.team-editorial .player-comparator-head article{background:var(--glass-dark-bg);border:1px solid var(--glass-dark-border);color:var(--glass-dark-text);box-shadow:var(--glass-shadow)}
#team-squad-app.team-editorial .player-comparator-head :is(h3,p,strong){color:var(--glass-dark-text)}
#team-squad-app.team-editorial .team-objective-section .objective-metric{padding:12px 0;border:0;border-radius:0;border-bottom:1px solid var(--line)}
#team-squad-app.team-editorial .team-page-navigation a{max-width:100%}
@media(max-width:1000px){
 #team-squad-app.team-editorial .team-season-content{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media(max-width:600px){
 #team-squad-app.team-editorial>[data-editorial-section]{padding:16px}
 #team-squad-app.team-editorial .team-detail-hero{grid-template-columns:64px minmax(0,1fr)}
 #team-squad-app.team-editorial .team-detail-hero h1{font-size:26px}
 #team-squad-app.team-editorial .team-page-jumps{gap:8px 14px}
 #team-squad-app.team-editorial .team-key-numbers{grid-template-columns:repeat(3,minmax(0,1fr));gap:24px 0}
 #team-squad-app.team-editorial .team-key-numbers>div{padding:0 12px}
 #team-squad-app.team-editorial .team-key-numbers>div:nth-child(3n+1){border-left:0;padding-left:0}
 #team-squad-app.team-editorial .team-stat-summary,#team-squad-app.team-editorial .team-leader-summary{grid-template-columns:1fr;gap:24px}
 #team-squad-app.team-editorial .team-leader-summary article+article{border-top:1px solid var(--line);padding-top:18px}
 #team-squad-app.team-editorial .team-season-content{grid-template-columns:1fr;padding:16px 0}
 #team-squad-app.team-editorial .team-season-heading{padding-inline:0}
 #team-squad-app.team-editorial .squad-leaders-heading{align-items:start;flex-wrap:wrap;gap:10px}
 #team-squad-app.team-editorial .squad-table-disclosure>summary{flex-wrap:wrap}
 #team-squad-app.team-editorial .team-style-trait-grid{grid-template-columns:1fr}
}

#team-squad-app.team-editorial .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}

/* Seasonal roster: compact rows, independent of match call-ups and lineups. */
#team-squad-app.team-editorial .team-full-roster-group{margin:24px 0 0}
#team-squad-app.team-editorial .team-full-roster-group:first-of-type{margin-top:0}
#team-squad-app.team-editorial .team-full-roster-group h3{margin:0 0 12px;font-size:16px}
#team-squad-app.team-editorial .team-full-roster-group h3 span{color:var(--muted);font-size:12px;font-weight:400}
#team-squad-app.team-editorial .team-full-roster-scroll{max-width:100%;overflow-x:auto;overscroll-behavior-inline:contain}
#team-squad-app.team-editorial .team-full-roster-table{width:100%;min-width:680px;border-collapse:collapse;background:transparent;font-size:12px}
#team-squad-app.team-editorial .team-full-roster-table :is(th,td){padding:8px 12px;border-bottom:1px solid var(--line);text-align:right;line-height:1.4;font-variant-numeric:tabular-nums;white-space:nowrap}
#team-squad-app.team-editorial .team-full-roster-table :is(th,td):first-child,#team-squad-app.team-editorial .team-full-roster-table :is(th,td):nth-child(3){text-align:left}
#team-squad-app.team-editorial .team-full-roster-table thead th{background:var(--glass-light-bg);color:var(--muted);font-size:11px;font-weight:650}
#team-squad-app.team-editorial .team-full-roster-table tbody th{font-weight:650}
#team-squad-app.team-editorial .team-full-roster-table tbody tr:nth-child(even){background:rgba(20,43,59,.025)}
#team-squad-app.team-editorial .team-full-roster-table tbody tr:hover{background:rgba(181,250,255,.34)}

/* Verified squad numbers extend the historical table by one column. */
#team-squad-app.team-editorial .squad-table{width:1673px;min-width:1673px}
#team-squad-app.team-editorial .squad-col-number{width:52px}
#team-squad-app.team-editorial .team-full-roster-section,#team-squad-app.team-editorial #squad-results{min-width:0;max-width:100%}

#team-squad-app.team-editorial .squad-table :is(th,td):first-child{background:#f3f8fa}
#team-squad-app.team-editorial .squad-table thead th{background:#edf3f5}
#team-squad-app.team-editorial .squad-table tbody tr:is(:hover,:focus-within) td:first-child{background:#d5f1f2}
/* Compact team presentation; roster, comparator and lineup geometry are preserved. */
#team-squad-app.team-editorial{max-width:1050px;gap:8px}
#team-squad-app.team-editorial>.team-season-summary{padding-block:16px}
#team-squad-app.team-editorial .team-season-summary .team-key-numbers dd{font-size:30px;margin-bottom:4px}
#team-squad-app.team-editorial>.team-objective-compact{display:grid;grid-template-columns:1fr 1fr;gap:24px;padding:0 24px 20px}
#team-squad-app.team-editorial .team-objective-compact h3{font-size:18px;margin:4px 0}
#team-squad-app.team-editorial .team-objective-compact p,#team-squad-app.team-editorial .team-objective-compact small{font-size:12px;color:var(--muted);margin:0}
#team-squad-app.team-editorial .team-objective-compact .objective-metrics{display:grid;grid-template-columns:1fr 1fr;gap:16px}
#team-squad-app.team-editorial .team-objective-compact .objective-metric{padding:0;border:0;border-radius:0;background:transparent}
#team-squad-app.team-editorial>.team-tactics-section .team-editorial-heading,#team-squad-app.team-editorial>.team-roster-section .team-editorial-heading{margin-bottom:16px}
#team-squad-app.team-editorial>.team-tactics-section .team-editorial-heading h2,#team-squad-app.team-editorial>.team-roster-section .team-editorial-heading h2{font-family:var(--font-body);font-size:24px;letter-spacing:-.025em;font-weight:650}
#team-squad-app.team-editorial .team-tactical-analysis .team-style-trait-grid{grid-template-columns:1fr 1fr;gap:16px}
#team-squad-app.team-editorial .team-tactical-analysis .team-style-traits{border-top:1px solid var(--line);padding:12px 0 0}
#team-squad-app.team-editorial .team-tactical-analysis h3{font-size:14px;margin:0 0 10px}
#team-squad-app.team-editorial .team-tactical-analysis li{font-size:12px;line-height:1.6}
#team-squad-app.team-editorial .team-editorial-statistics .team-season-heading h2{font-size:24px}
#team-squad-app.team-editorial .team-editorial-statistics .team-attack-channels{margin:0 0 20px;padding:0;border:0;background:transparent}
#team-squad-app.team-editorial .squad-leader-grid{gap:24px 28px}
#team-squad-app.team-editorial .squad-leader-card{border-top:1px solid var(--line)}
@media(max-width:700px){
 #team-squad-app.team-editorial>.team-objective-compact{grid-template-columns:1fr;padding:0 16px 16px;gap:16px}
 #team-squad-app.team-editorial .team-tactical-analysis .team-style-trait-grid{grid-template-columns:1fr}
}
#team-squad-app.team-editorial .team-tactical-analysis .team-style-traits:last-child{grid-column:auto}
#team-squad-app.team-editorial .team-editorial-statistics .team-season-heading{cursor:default}
#team-squad-app.team-editorial .team-editorial-statistics .team-season-heading::after{content:none}

css/tokens.css:
/* Foundations only. Theme tokens do not restyle existing components.
   Legacy colour/radius/shadow families retain their current cascade until migration. */
:root{
  --ds-font-body:"Inter","Segoe UI",Arial,sans-serif;
  --ds-font-display:"Anton",Impact,sans-serif;
  --ds-font-data:var(--ds-font-body);
  --ds-text-meta:12px;
  --ds-text-compact:14px;
  --ds-text-body:16px;
  --ds-title-page:clamp(40px,4vw,48px);
